#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="${PLAN_AUDIT_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
PARENT_DIR="${PLAN_AUDIT_PARENT:-$(cd "$ROOT_DIR/.." && pwd)}"

usage() {
  cat <<'USAGE'
Usage: scripts/audit-plan-readiness.sh

Statically verifies that the maintained Fearless repos still expose the release
and production-readiness gates required by FEARLESS_PROJECT_PLAN.md.

Environment:
  PLAN_AUDIT_ROOT    Workspace root containing fearless-* repos.
  PLAN_AUDIT_PARENT  Parent directory containing sibling indexer repos.
  PLAN_AUDIT_ANDROID_ROOT
                     Current Android release-candidate worktree. Defaults to
                     fearless-Android under PLAN_AUDIT_ROOT.
  PLAN_AUDIT_IOS_ROOT
                     Current integrated iOS release-candidate worktree.
                     Defaults to fearless-iOS under PLAN_AUDIT_ROOT.
  PLAN_AUDIT_IOS_TESTFLIGHT_ROOT
                     Clean iOS release-candidate worktree containing the
                     tracked current TestFlight publication contract.
  PLAN_AUDIT_IROHA_ROOT
                     Current clean Iroha integration-candidate worktree.
                     Defaults to the iroha sibling of PLAN_AUDIT_ROOT.
  PLAN_AUDIT_FAIL_FAST
                     Exit on the first recorded failure when set to true.
USAGE
}

if [[ "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then
  usage
  exit 0
fi

if (($# > 0)); then
  echo "[plan-readiness][error] Unknown argument: $1" >&2
  usage >&2
  exit 2
fi

failures=()

log() { echo "[plan-readiness] $*"; }
warn() { echo "[plan-readiness][warn] $*" >&2; }

sha256_file() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{print $1}'
  else
    shasum -a 256 "$1" | awk '{print $1}'
  fi
}

record_failure() {
  failures+=("$1")
  warn "$1"
  if [[ "${PLAN_AUDIT_FAIL_FAST:-false}" == "true" ]]; then
    exit 1
  fi
}

require_file() {
  local file="$1"
  local description="$2"
  [[ -f "$file" ]] || record_failure "$description missing: $file"
}

require_exact_file_size() {
  local file="$1"
  local expected_bytes="$2"
  local description="$3"
  local actual_bytes
  if [[ ! -f "$file" ]]; then
    return
  fi
  actual_bytes="$(wc -c < "$file" | tr -d '[:space:]')"
  if [[ "$actual_bytes" != "$expected_bytes" ]]; then
    record_failure "$description expected exactly ${expected_bytes} bytes in $file, found ${actual_bytes}"
  fi
}

require_exact_file_sha256() {
  local file="$1"
  local expected_sha256="$2"
  local description="$3"
  local actual_sha256
  if [[ ! -f "$file" ]]; then
    return
  fi
  actual_sha256="$(sha256_file "$file")"
  if [[ "$actual_sha256" != "$expected_sha256" ]]; then
    record_failure "$description expected SHA-256 $expected_sha256 in $file, found $actual_sha256"
  fi
}

require_exact_python_frozenset_literal() {
  local file="$1"
  local symbol="$2"
  local description="$3"
  shift 3
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! python3 - "$file" "$symbol" "$@" <<'PY'
import ast
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
symbol = sys.argv[2]
expected = sys.argv[3:]
try:
    tree = ast.parse(path.read_bytes(), filename=str(path))
except (SyntaxError, UnicodeDecodeError):
    raise SystemExit(1)
assignments = [
    node.value
    for node in ast.walk(tree)
    if isinstance(node, ast.Assign)
    and any(isinstance(target, ast.Name) and target.id == symbol for target in node.targets)
]
if len(assignments) != 1:
    raise SystemExit(1)
value = assignments[0]
if (
    not isinstance(value, ast.Call)
    or not isinstance(value.func, ast.Name)
    or value.func.id != "frozenset"
    or len(value.args) != 1
    or value.keywords
    or not isinstance(value.args[0], (ast.Set, ast.Tuple, ast.List))
):
    raise SystemExit(1)
members = value.args[0].elts
if not all(isinstance(member, ast.Constant) and isinstance(member.value, str) for member in members):
    raise SystemExit(1)
actual = [member.value for member in members]
if len(actual) != len(set(actual)) or set(actual) != set(expected) or len(actual) != len(expected):
    raise SystemExit(1)
PY
  then
    record_failure "$description missing in $file"
  fi
}

reject_path() {
  local path="$1"
  local description="$2"
  if [[ -e "$path" || -L "$path" ]]; then
    record_failure "$description present: $path"
  fi
}

reject_symlink() {
  local path="$1"
  local description="$2"
  if [[ -L "$path" ]]; then
    record_failure "$description is a symlink: $path"
  fi
}

require_executable_file() {
  local file="$1"
  local description="$2"
  if [[ ! -f "$file" ]]; then
    record_failure "$description missing: $file"
  elif [[ ! -x "$file" ]]; then
    record_failure "$description is not executable: $file"
  fi
}

require_identical_files() {
  local first="$1"
  local second="$2"
  local description="$3"
  if [[ ! -f "$first" || ! -f "$second" ]]; then
    return
  fi
  if ! cmp -s "$first" "$second"; then
    record_failure "$description differ: $first and $second"
  fi
}

require_pattern() {
  local file="$1"
  local pattern="$2"
  local description="$3"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! grep -Eq -- "$pattern" "$file"; then
    record_failure "$description missing in $file"
  fi
}

require_matching_append_block_catalog_routes() {
  local file="$1"
  local description="$2"
  if [[ ! -f "$file" ]]; then
    return
  fi

  local diagnostic
  if ! diagnostic="$(awk '
    function routing_failure(message) {
      print message
      invalid = 1
    }

    /^EXPECTED_TEST_CASE_CATALOG=[0-9]+$/ {
      expected_catalog = $0
      sub(/^EXPECTED_TEST_CASE_CATALOG=/, "", expected_catalog)
      next
    }

    /^if \(\(TEST_CASE_START <= [0-9]+\)\); then$/ {
      if (active) {
        routing_failure("catalog append block started before the prior block closed at line " NR)
      }
      threshold = $0
      sub(/^if \(\(TEST_CASE_START <= /, "", threshold)
      sub(/\)\); then$/, "", threshold)
      active = 1
      saw_else = 0
      terminal_count = 0
      routed_case_count = 0
      block_start_index = catalog_index
      next
    }

    active && !saw_else && /^(expect_success|expect_failure)[[:space:]]/ {
      routed_case_count += 1
      next
    }

    active && /^else$/ {
      if (saw_else) {
        routing_failure("catalog append block has multiple terminal else clauses at line " NR)
      }
      saw_else = 1
      next
    }

    active && saw_else && /^  TEST_CASE_INDEX=[0-9]+$/ {
      terminal = $0
      sub(/^  TEST_CASE_INDEX=/, "", terminal)
      terminal_count += 1
      next
    }

    active && saw_else && /^fi$/ {
      block_count += 1
      if (terminal_count != 1) {
        routing_failure("catalog append block ending at line " NR " must set exactly one terminal TEST_CASE_INDEX")
      } else if (threshold != terminal) {
        routing_failure("catalog append block threshold " threshold " does not match terminal TEST_CASE_INDEX " terminal)
      }
      if (block_start_index + routed_case_count != threshold) {
        routing_failure("catalog append block ending at line " NR " routes through " threshold \
          " but its " routed_case_count " top-level cases advance index " block_start_index \
          " only through " block_start_index + routed_case_count)
      }
      catalog_index = threshold
      active = 0
      saw_else = 0
      terminal_count = 0
      routed_case_count = 0
      next
    }

    !active && /^(expect_success|expect_failure)[[:space:]]/ {
      catalog_index += 1
      next
    }

    END {
      if (active) {
        routing_failure("catalog append block is not closed")
      }
      if (block_count == 0) {
        routing_failure("catalog contains no routed append blocks")
      }
      if (expected_catalog == "") {
        routing_failure("catalog expected-case sentinel is missing")
      } else if (catalog_index != expected_catalog) {
        routing_failure("catalog routes and top-level cases end at " catalog_index \
          " but EXPECTED_TEST_CASE_CATALOG is " expected_catalog)
      }
      exit(invalid ? 1 : 0)
    }
  ' "$file")"; then
    record_failure "$description failed in $file: $diagnostic"
  fi
}

require_exact_line_count() {
  local file="$1"
  local expected_line="$2"
  local expected_count="$3"
  local description="$4"
  local actual_count
  if [[ ! -f "$file" ]]; then
    return
  fi
  actual_count="$(awk -v expected="$expected_line" '$0 == expected { count++ } END { print count + 0 }' "$file")"
  if [[ "$actual_count" != "$expected_count" ]]; then
    record_failure "$description missing or duplicated: expected exactly $expected_count canonical command line(s) in $file, found $actual_count"
  fi
}

require_exact_adjacent_line_pair_count() {
  local file="$1"
  local first_line="$2"
  local second_line="$3"
  local expected_count="$4"
  local description="$5"
  local actual_count
  if [[ ! -f "$file" ]]; then
    return
  fi
  actual_count="$(awk -v first="$first_line" -v second="$second_line" '
    previous == first && $0 == second { count++ }
    { previous = $0 }
    END { print count + 0 }
  ' "$file")"
  if [[ "$actual_count" != "$expected_count" ]]; then
    record_failure "$description missing or duplicated: expected exactly $expected_count contiguous canonical command block(s) in $file, found $actual_count"
  fi
}

require_min_pattern_count() {
  local file="$1"
  local pattern="$2"
  local minimum="$3"
  local description="$4"
  if [[ ! -f "$file" ]]; then
    return
  fi
  local actual_count
  actual_count="$(grep -Ec -- "$pattern" "$file" || true)"
  if ((actual_count < minimum)); then
    record_failure "$description expected at least $minimum occurrences in $file, found $actual_count"
  fi
}

require_exact_pattern_count() {
  local file="$1"
  local pattern="$2"
  local expected="$3"
  local description="$4"
  local actual_count
  if [[ ! -f "$file" ]]; then
    return
  fi
  actual_count="$(grep -Ec -- "$pattern" "$file" || true)"
  if ((actual_count != expected)); then
    record_failure "$description expected exactly $expected occurrences in $file, found $actual_count"
  fi
}

require_nexus_evidence_test_inventory() {
  local file="$1"
  local positive_count negative_call_count wallet_loop_count summary_count
  if [[ ! -f "$file" ]]; then
    return
  fi

  positive_count="$(awk '
    /^[[:space:]]*\(\(positive_cases \+= 1\)\)$/ { count++ }
    END { print count + 0 }
  ' "$file")"
  negative_call_count="$(awk '
    /^[[:space:]]*expect_failure[[:space:]]/ { count++ }
    END { print count + 0 }
  ' "$file")"
  wallet_loop_count="$(awk '
    $0 == "for wallet_index in 0 1 2; do" { count++ }
    END { print count + 0 }
  ' "$file")"
  summary_count="$(grep -Ec -- 'all assertions passed \(\$\{positive_cases\} positive, \$\{negative_cases\} negative\)' "$file" || true)"

  if [[ "$positive_count" != "14" || "$summary_count" != "1" ]]; then
    record_failure "root SORA Nexus production evidence exact 14 positive-case inventory missing or drifted in $file (increments=$positive_count summaries=$summary_count)"
  fi
  # There are 158 static expect_failure call sites. One is inside the exact
  # three-wallet loop, so it runs twice more than its single source occurrence:
  # 158 + 2 = the observed and reviewed 160 negative/adversarial cases.
  if [[ "$negative_call_count" != "158" || "$wallet_loop_count" != "1" ]]; then
    record_failure "root SORA Nexus production evidence exact 160 negative-case inventory missing or drifted in $file (call-sites=$negative_call_count wallet-loops=$wallet_loop_count)"
  fi
}

require_order() {
  local file="$1"
  local first_pattern="$2"
  local second_pattern="$3"
  local description="$4"
  if [[ ! -f "$file" ]]; then
    return
  fi
  local first_line second_line
  first_line="$(grep -En -- "$first_pattern" "$file" | head -n 1 | cut -d: -f1 || true)"
  if [[ -n "$first_line" ]]; then
    second_line="$(grep -En -- "$second_pattern" "$file" | awk -F: -v first="$first_line" '$1 > first { print $1; exit }' || true)"
  else
    second_line=""
  fi
  if [[ -z "$first_line" || -z "$second_line" ]]; then
    record_failure "$description missing in $file"
  fi
}

require_pattern_multiline() {
  local file="$1"
  local pattern="$2"
  local description="$3"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! PATTERN="$pattern" perl -0ne 'if (/$ENV{PATTERN}/s) { $found = 1; last } END { exit($found ? 0 : 1) }' "$file"; then
    record_failure "$description missing in $file"
  fi
}

require_pattern_between() {
  local file="$1"
  local start_pattern="$2"
  local end_pattern="$3"
  local pattern="$4"
  local description="$5"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! awk -v start="$start_pattern" -v end="$end_pattern" -v pattern="$pattern" '
    $0 ~ start { in_block = 1 }
    in_block && $0 ~ pattern { found = 1 }
    in_block && $0 ~ end { exit }
    END { exit(found ? 0 : 1) }
  ' "$file"; then
    record_failure "$description missing in $file"
  fi
}

require_pattern_multiline_between() {
  local file="$1"
  local start_pattern="$2"
  local end_pattern="$3"
  local pattern="$4"
  local description="$5"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! START_PATTERN="$start_pattern" END_PATTERN="$end_pattern" PATTERN="$pattern" \
    perl -0ne '
      if (/$ENV{START_PATTERN}(.*?)$ENV{END_PATTERN}/ms) {
        $block = $1;
        $found = 1 if $block =~ /$ENV{PATTERN}/s;
      }
      END { exit($found ? 0 : 1) }
    ' "$file"; then
    record_failure "$description missing in $file"
  fi
}

reject_pattern() {
  local file="$1"
  local pattern="$2"
  local description="$3"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if grep -Eq -- "$pattern" "$file"; then
    record_failure "$description present in $file"
  fi
}

reject_pattern_multiline() {
  local file="$1"
  local pattern="$2"
  local description="$3"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if PATTERN="$pattern" perl -0ne 'if (/$ENV{PATTERN}/s) { $found = 1; last } END { exit($found ? 0 : 1) }' "$file"; then
    record_failure "$description present in $file"
  fi
}

require_tsv_data_row_count() {
  local file="$1"
  local expected_count="$2"
  local description="$3"
  local actual_count
  if [[ ! -f "$file" ]]; then
    return
  fi
  actual_count="$(awk 'NF && $0 !~ /^#/ { count++ } END { print count + 0 }' "$file")"
  if [[ "$actual_count" != "$expected_count" ]]; then
    record_failure "$description expected $expected_count rows in $file, found $actual_count"
  fi
}

require_unique_transaction_fixture_manifest() {
  local file="$1"
  local expected_count="$2"
  local description="$3"
  if [[ ! -f "$file" ]]; then
    return
  fi

  local validation_output validation_file
  validation_file="$(mktemp "${TMPDIR:-/tmp}/fearless-fixture-manifest.XXXXXX")"
  if ! node - "$file" "$expected_count" >"$validation_file" 2>&1 <<'NODE'
const fs = require('node:fs');

const [file, expectedCountText] = process.argv.slice(2);
const expectedCount = Number(expectedCountText);

function fail(message) {
  throw new Error(message);
}

function requireCanonicalBase64(value, field) {
  if (typeof value !== 'string' || value.length === 0) {
    fail(`${field} must be a non-empty canonical base64 string`);
  }
  if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
    fail(`${field} is not canonical base64`);
  }
  const bytes = Buffer.from(value, 'base64');
  if (bytes.length === 0 || bytes.toString('base64') !== value) {
    fail(`${field} is not canonical base64`);
  }
  return bytes.toString('hex');
}

function insertUnique(seen, value, field) {
  if (seen.has(value)) {
    fail(`duplicate ${field}: ${value}`);
  }
  seen.add(value);
}

let rawManifest;
let manifest;
try {
  rawManifest = fs.readFileSync(file, 'utf8');
  manifest = JSON.parse(rawManifest);
} catch (error) {
  fail(`cannot parse manifest: ${error.message}`);
}
if (!manifest || !Array.isArray(manifest.fixtures)) {
  fail('manifest.fixtures must be an array');
}
if (manifest.fixtures.length !== expectedCount) {
  fail(`expected ${expectedCount} fixtures, found ${manifest.fixtures.length}`);
}

const integerTokenPattern = /"(creation_time_ms|encoded_len|signed_len|time_to_live_ms|nonce)"\s*:\s*(null|true|false|"(?:\\.|[^"\\])*"|-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?)/gu;
const integerTokens = [...rawManifest.matchAll(integerTokenPattern)];
if (integerTokens.length !== expectedCount * 5) {
  fail(`each fixture must encode exactly five reviewed integer fields; found ${integerTokens.length}`);
}
for (const [, field, token] of integerTokens) {
  if (token === 'null' && (field === 'time_to_live_ms' || field === 'nonce')) continue;
  if (!/^(?:0|[1-9][0-9]*)$/.test(token)) {
    fail(`${field} must use a canonical nonnegative JSON integer token or reviewed null`);
  }
}

const identities = {
  name: new Set(),
  encoded_file: new Set(),
  payload_hash: new Set(),
  payload_bytes: new Set(),
  signed_hash: new Set(),
  signed_bytes: new Set(),
};

for (const [index, fixture] of manifest.fixtures.entries()) {
  if (!fixture || typeof fixture !== 'object' || Array.isArray(fixture)) {
    fail(`fixtures[${index}] must be an object`);
  }
  for (const field of ['name', 'encoded_file']) {
    const value = fixture[field];
    if (typeof value !== 'string' || value.length === 0) {
      fail(`fixtures[${index}].${field} must be a non-empty string`);
    }
    insertUnique(identities[field], value, `fixture ${field}`);
  }
  for (const field of ['chain', 'authority']) {
    if (typeof fixture[field] !== 'string' || fixture[field].length === 0) {
      fail(`fixtures[${index}].${field} must be a non-empty string`);
    }
  }
  for (const field of ['creation_time_ms', 'encoded_len', 'signed_len']) {
    if (!Number.isSafeInteger(fixture[field]) || fixture[field] < 0) {
      fail(`fixtures[${index}].${field} must be a nonnegative safe integer`);
    }
  }
  for (const field of ['time_to_live_ms', 'nonce']) {
    if (fixture[field] !== null && (!Number.isSafeInteger(fixture[field]) || fixture[field] < 0)) {
      fail(`fixtures[${index}].${field} must be null or a nonnegative safe integer`);
    }
  }
  for (const field of ['payload_hash', 'signed_hash']) {
    const value = fixture[field];
    if (typeof value !== 'string' || !/^[0-9a-f]{64}$/.test(value)) {
      fail(`fixtures[${index}].${field} must be a canonical lowercase 32-byte hex digest`);
    }
    insertUnique(identities[field], value, `fixture ${field}`);
  }
  const payloadBytesHex = requireCanonicalBase64(
    fixture.payload_base64,
    `fixtures[${index}].payload_base64`,
  );
  const signedBytesHex = requireCanonicalBase64(
    fixture.signed_base64,
    `fixtures[${index}].signed_base64`,
  );
  if (fixture.encoded_len !== payloadBytesHex.length / 2) {
    fail(`fixtures[${index}].encoded_len does not match payload bytes`);
  }
  if (fixture.signed_len !== signedBytesHex.length / 2) {
    fail(`fixtures[${index}].signed_len does not match signed bytes`);
  }
  insertUnique(
    identities.payload_bytes,
    payloadBytesHex,
    'fixture payload bytes',
  );
  insertUnique(
    identities.signed_bytes,
    signedBytesHex,
    'fixture signed bytes',
  );
}
NODE
  then
    validation_output="$(cat "$validation_file")"
    rm -f "$validation_file"
    record_failure "$description failed for $file: $validation_output"
  else
    rm -f "$validation_file"
  fi
}

require_transaction_fixture_family_alignment() {
  local canonical_file="$1"
  local target_file="$2"
  local omitted_name="$3"
  local description="$4"
  if [[ ! -f "$canonical_file" || ! -f "$target_file" ]]; then
    return
  fi

  local validation_output
  if ! validation_output="$(node - "$canonical_file" "$target_file" "$omitted_name" <<'NODE'
const fs = require('node:fs');

const [canonicalFile, targetFile, omittedName] = process.argv.slice(2);
const canonical = JSON.parse(fs.readFileSync(canonicalFile, 'utf8')).fixtures;
const target = JSON.parse(fs.readFileSync(targetFile, 'utf8')).fixtures;

function fail(message) {
  throw new Error(message);
}

function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

const canonicalByName = new Map(canonical.map((fixture) => [fixture.name, fixture]));
const targetByName = new Map(target.map((fixture) => [fixture.name, fixture]));
const expectedNames = [...canonicalByName.keys()].filter((name) => name !== omittedName).sort();
const actualNames = [...targetByName.keys()].sort();
if (canonicalJson(actualNames) !== canonicalJson(expectedNames)) {
  fail(`fixture name set mismatch: expected ${expectedNames.join(',')}; found ${actualNames.join(',')}`);
}
for (const name of expectedNames) {
  if (canonicalJson(targetByName.get(name)) !== canonicalJson(canonicalByName.get(name))) {
    fail(`fixture ${name} differs from the canonical family`);
  }
}
NODE
)"; then
    record_failure "$description failed for $target_file: $validation_output"
  fi
}

reject_pattern_between() {
  local file="$1"
  local start_pattern="$2"
  local end_pattern="$3"
  local pattern="$4"
  local description="$5"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if awk -v start="$start_pattern" -v end="$end_pattern" -v pattern="$pattern" '
    $0 ~ start { in_block = 1 }
    in_block && $0 ~ pattern { found = 1 }
    in_block && $0 ~ end { exit }
    END { exit(found ? 0 : 1) }
  ' "$file"; then
    record_failure "$description present in $file"
  fi
}

require_pattern_i() {
  local file="$1"
  local pattern="$2"
  local description="$3"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! grep -Eiq -- "$pattern" "$file"; then
    record_failure "$description missing in $file"
  fi
}

require_repo() {
  local repo_path="$1"
  local label="$2"
  [[ -d "$repo_path" ]] || record_failure "$label repo missing: $repo_path"
}

common_release_gate_checks() {
  local repo_path="$1"
  local label="$2"
  local ci_file="$3"

  local release="$repo_path/docs/release-checklist.md"
  local branch_flow="$repo_path/.github/workflows/branch-flow.yml"
  local codeowners="$repo_path/.github/CODEOWNERS"
  local pr_template="$repo_path/.github/pull_request_template.md"
  local todo_audit="$repo_path/scripts/audit-todo-debt.sh"
  local todo_test="$repo_path/scripts/test-todo-debt-audit.sh"

  require_file "$release" "$label release checklist"
  require_file "$ci_file" "$label main CI workflow"
  require_file "$branch_flow" "$label Branch Flow workflow"
  require_file "$codeowners" "$label CODEOWNERS"
  require_file "$pr_template" "$label pull request template"

  require_executable_file "$repo_path/scripts/audit-branch-flow.sh" "$label branch-flow audit"
  require_executable_file "$repo_path/scripts/test-branch-flow-audit.sh" "$label branch-flow audit self-test"
