  require_pattern_multiline "$app_build" 'internalAppSharing[[:space:]]*\{[^}]{0,700}initWith release[^}]{0,700}signingConfig null[^}]{0,700}matchingFallbacks = \['\''release'\''\][^}]{0,700}versionNameSuffix '\''-ias'\''' "fearless-Android unsigned IAS release semantics"
