  reject_pattern "$app_build" 'generatedIas|iasBridge|atomicNoReplaceMove|src/internalAppSharing|configuredIas|requestedIas|iasDebugKeyStore|com\.github\.triplet\.play' "fearless-Android retired generated IAS bridge or publisher wiring"
  require_exact_pattern_count "$nft_build" 'invoke\("FL_ANDROID_ALCHEMY_API_ETHEREUM_KEY"\)' 1 "fearless-Android compiled NFT Alchemy credential"

  require_exact_line_count "$release_workflow" "name: Android Signed Release Artifact" 1 "fearless-Android signed-artifact workflow identity"
  require_exact_line_count "$release_workflow" "  release-controls:" 1 "fearless-Android release controls job"
  require_exact_line_count "$release_workflow" "    name: Credential-free release controls" 1 "fearless-Android credential-free release controls identity"
  require_exact_line_count "$release_workflow" "  release-build:" 1 "fearless-Android unsigned release build job"
