iroha_production_send_readiness_checks() {
  local repo_path="$1"
  local label="$2"
  local platform="$3"
  local ci_file="$4"
  local manifest="$repo_path/config/iroha-production-send-readiness.json"
  local readiness_doc="$repo_path/docs/iroha-production-send-readiness.md"
  local release="$repo_path/docs/release-checklist.md"
  local audit="$repo_path/scripts/audit-iroha-production-send-readiness.sh"
  local audit_test="$repo_path/scripts/test-iroha-production-send-readiness-audit.sh"
  local expected_schema=1
  if [[ "$platform" == "android" || "$platform" == "ios" ]]; then
    expected_schema=2
  fi

  require_file "$manifest" "$label Iroha production-send readiness manifest"
  require_file "$readiness_doc" "$label Iroha production-send blocker documentation"
  require_executable_file "$audit" "$label Iroha production-send readiness audit"
  require_executable_file "$audit_test" "$label Iroha production-send readiness adversarial self-test"
  require_pattern "$manifest" "\"schemaVersion\":[[:space:]]*$expected_schema" "$label Iroha production-send readiness schema"
  require_pattern "$manifest" "\"platform\":[[:space:]]*\"$platform\"" "$label Iroha production-send platform identity"
  require_pattern "$manifest" '"status":[[:space:]]*"blocked"' "$label Iroha production-send blocked status"
  require_pattern "$manifest" '"releaseEnabled":[[:space:]]*false' "$label Iroha production-send disabled release state"
  require_pattern "$manifest" '"nexusEnabledByDefault":[[:space:]]*false' "$label Iroha Nexus disabled-by-default state"
  require_pattern "$manifest" 'v2\.0\.0-rc\.2\.1-fearless-mobile-sdk\.3' "$label pinned Iroha mobile SDK release"
  require_pattern "$audit" 'EXPECTED_MANIFEST_SHA256="[0-9a-f]{64}"' "$label Iroha production-send manifest digest pin"
  require_pattern "$audit" "manifest\.status === 'blocked'" "$label Iroha production-send fail-closed status gate"
  require_pattern "$audit" 'manifest\.releaseEnabled === false' "$label Iroha production-send release disable gate"
  require_pattern "$audit" 'manifest\.nexusEnabledByDefault === false' "$label Iroha Nexus default-disable gate"
  if [[ "$platform" == "browser-extension" ]]; then
    require_pattern "$audit" 'exactly five exit criteria are required|unexpected exit criteria' "$label Iroha production-send exact exit criteria gate"
  elif [[ "$platform" == "ios" ]]; then
    require_pattern "$audit" 'exactly eleven exit criteria are required' "$label Iroha production-send exact exit criteria gate"
  fi
  require_pattern "$audit" 'required regular file is missing or is a symlink' "$label Iroha readiness symlink rejection"
  require_pattern "$audit_test" 'manifest (digest )?tamper' "$label Iroha readiness manifest-tamper adversarial fixture"
  require_pattern "$audit_test" 'manifest symlink' "$label Iroha readiness manifest-symlink adversarial fixture"
  require_pattern "$audit_test" 'Nexus enabled' "$label Iroha Nexus enablement adversarial fixture"
  require_pattern "$audit_test" 'mismatch test removed' "$label Iroha key-mismatch coverage adversarial fixture"
  require_pattern "$audit_test" 'capability claim regressed' "$label Iroha capability non-enablement adversarial fixture"
  require_pattern "$ci_file" 'test-iroha-production-send-readiness-audit\.sh' "$label CI Iroha production-send readiness self-test"
  require_pattern "$ci_file" 'audit-iroha-production-send-readiness\.sh' "$label CI Iroha production-send readiness audit"
  require_pattern "$release" 'test-iroha-production-send-readiness-audit\.sh.*audit-iroha-production-send-readiness\.sh' "$label release checklist Iroha production-send gates"
  require_pattern "$release" 'config/iroha-production-send-readiness\.json.*blocked' "$label release checklist explicit Iroha blocked state"
  require_pattern "$readiness_doc" 'BLOCKED / fail closed' "$label Iroha production-send fail-closed documentation"
  require_pattern "$readiness_doc" 'does \*\*not\*\* make Iroha send production-ready|Passing it does \*\*not\*\* make Iroha send production-ready' "$label Iroha signer-seam non-readiness documentation"

  case "$platform" in
    android)
      require_pattern "$audit" 'manifest\.artifact\.bytes > manifest\.artifact\.reviewThresholdBytes' "$label Android SDK mandatory review threshold gate"
      require_pattern "$manifest" 'android_staged_bridge_production_gates_required' "$label Android staged bridge production blocker"
      require_pattern "$manifest" '"defaultSigner":[[:space:]]*"UnavailableIrohaTransferSigner"' "$label Android unavailable signer default"
      require_pattern "$manifest" '"archiveReview":[[:space:]]*"passed"' "$label Android completed archive review state"
      require_pattern "$manifest" '"applicationRuntimeDependency":[[:space:]]*false' "$label Android staged bridge application-runtime exclusion"
      require_pattern "$audit" 'production exit criteria drifted' "$label Android exact staged production exit criteria gate"
      require_pattern "$audit" 'staged Iroha SDK dependency leaked outside the two audited staging modules' "$label Android production SDK dependency rejection"
      require_pattern "$audit" 'Iroha SDK/native binary material must remain generated and untracked' "$label Android tracked native binary rejection"
      require_pattern "$audit_test" 'provider bypass' "$label Android signer-provider bypass fixture"
      require_pattern "$audit_test" 'tracked native bridge' "$label Android tracked native bridge fixture"
      local release_workflow="$repo_path/.github/workflows/android-release.yml"
      require_pattern "$release_workflow" 'test-iroha-production-send-readiness-audit\.sh' "$label release workflow Iroha production-send readiness self-test"
      require_pattern "$release_workflow" 'audit-iroha-production-send-readiness\.sh' "$label release workflow Iroha production-send readiness audit"
      ;;
    ios)
      require_pattern "$audit" '(manifest\.)?artifact\.bytes > (manifest\.)?artifact\.reviewThresholdBytes' "$label Apple XCFramework mandatory review threshold gate"
      require_pattern "$manifest" 'apple_xcframework_review_and_materialization_required' "$label Apple XCFramework review/materialization blocker"
      require_pattern "$manifest" 'NoritoBridge-v2\.0\.0-rc\.2\.1-fearless-mobile-sdk\.3\.xcframework\.zip' "$label pinned Apple NoritoBridge artifact"
      require_pattern "$audit" 'IrohaSwift/NoritoBridge was added to the Xcode dependency graph before review' "$label iOS unreviewed Iroha package rejection"
      require_pattern "$audit" 'SDK/native binary material was tracked before review' "$label iOS unreviewed native binary rejection"
      require_pattern "$audit_test" 'service bypass' "$label iOS signer service bypass fixture"
      require_pattern "$audit_test" 'tracked XCFramework' "$label iOS tracked XCFramework fixture"
      ;;
    browser-extension)
      require_pattern "$manifest" 'browser_transaction_codec_unpublished_source_only' "$label unpublished-source-only browser transaction codec blocker"
      require_pattern "$manifest" 'iroha_js_host is unavailable in browser builds\.' "$label browser native-host unavailability evidence"
      require_pattern "$manifest" 'globalThis\.__IROHA_NATIVE_BINDING__' "$label browser unreviewed runtime seam evidence"
      require_pattern "$audit" 'VUE_APP_ENABLE_IROHA_TRANSFERS must remain false' "$label browser production transfer flag gate"
      require_pattern "$audit" 'production source initializes the unreviewed native binding global' "$label browser unreviewed global initialization rejection"
      require_pattern "$audit" 'native/WASM codec artifact (was tracked before browser review|was tracked without a reviewed pinned release artifact)' "$label browser unreviewed native/WASM artifact rejection"
      require_pattern "$audit_test" 'runtime enablement' "$label browser runtime enablement fixture"
      require_pattern "$audit_test" 'unreviewed WASM tracked' "$label browser tracked WASM fixture"
      require_pattern "$audit_test" 'SDK checker weakened' "$label browser SDK blocker checker fixture"
      ;;
  esac
}

