  require_pattern "$readiness_doc" '6TEAJqbb8oEPmLncoNiMRbLEK6tw' "fearless-iOS canonical Taira XOR documentation"
  require_pattern "$readiness_doc" 'all six' "fearless-iOS strict fanout documentation"
  require_pattern "$readiness_doc" 'fabricated zero fee' "fearless-iOS fee fail-closed documentation"
