  fi
  if [[ -f "$candidate_evidence/b423c0f8-iroha-js-candidate-replay-base.inventory.tsv" ]]; then
    [[ "$(sha256_file "$candidate_evidence/b423c0f8-iroha-js-candidate-replay-base.inventory.tsv")" == "949e4b1f101cc47ebcd37f933784bffa183224262c94200708c1fcf237bf61d4" ]] ||
      record_failure "fearless-wallet-web replay inventory digest mismatch"
  fi
  if [[ -f "$safari_evidence" ]]; then
    [[ "$(sha256_file "$safari_evidence")" == "02184886d34343924cfe9de378249759fb41b3430d2cd36ec83337955401368a" ]] ||
