  require_pattern_multiline "$manifest" '"upload":[[:space:]]*\{[\s\S]*"status":[[:space:]]*"success"[\s\S]*2026-07-26T13:16:00Z[\s\S]*a483a372fe8fd19761d3b0324427c4cf55a4553b4ed7433b34b78517f292cea7[\s\S]*e82ff42b4b47713d1094c420dd7d1abfbfdfe7e7b80c972909936ad64e1e4756[\s\S]*6ede1d8fb981be149a82d69313be0ebc1838291e27d0ecf1c1576c95350b1af9[\s\S]*"xcodeMutation":[[:space:]]*"Distributions-only"[\s\S]*"reconstructedPreUploadArchiveTreeMatched":[[:space:]]*true[\s\S]*"embeddedAppSignatureVerified":[[:space:]]*true' "fearless-iOS exact successful TestFlight upload and bounded Xcode mutation"
