  require_pattern_multiline "$manifest" '"publicLink":[[:space:]]*\{[\s\S]*"enabled":[[:space:]]*true[\s\S]*"shareableToAnyoneWithLink":[[:space:]]*true[\s\S]*https://testflight\.apple\.com/join/012KzFyD[\s\S]*d6599b1b9c0f7e77d9dd80d9185da67c1d864be5df9a7bbf360f245b099a000c[\s\S]*"landingPageResolved":[[:space:]]*true[\s\S]*"landingPageApplicationName":[[:space:]]*"Fearless Wallet: DeFi Wallet"[\s\S]*"testFlightDeepLinkPresent":[[:space:]]*true[\s\S]*d5d0c2063934c4ca7dd8bb82af038d79909738c93cf96c11ab63bca8c0b7f272[\s\S]*"automaticTesterNotification":[[:space:]]*true[\s\S]*84e53d78316cf46cc1956d04e86782241d6e575da90fef109acaaf44cb368d4c' "fearless-iOS exact anyone-with-link TestFlight publication evidence"
  require_pattern_multiline "$manifest" '"symbolication":[[:space:]]*\{[\s\S]*"status":[[:space:]]*"degraded-third-party-symbolication"[\s\S]*"runtimeInstallLaunchOrMigrationImpact":[[:space:]]*false[\s\S]*"mainApplicationDSYMPresent":[[:space:]]*true[\s\S]*"runtimeFrameworkMissingVendorDSYM":[[:space:]]*"MPQRCoreSDK\.framework"[\s\S]*"blake2lib\.framework"[\s\S]*"libed25519\.framework"[\s\S]*"sr25519lib\.framework"[\s\S]*"productionFollowUpRequired":[[:space:]]*true' "fearless-iOS exact dSYM warning classification and open symbolication follow-up"
  require_pattern_multiline "$manifest" '"readiness":[[:space:]]*\{[\s\S]*"status":[[:space:]]*"blocked"[\s\S]*"publicationVerified":[[:space:]]*true[\s\S]*"externalTestingActive":[[:space:]]*true[\s\S]*"exactAppleDeliveredInstallVerified":[[:space:]]*false[\s\S]*"preservedDataPostInstallRehearsalVerified":[[:space:]]*false[\s\S]*"releaseEnabled":[[:space:]]*false[\s\S]*"blockerCode":[[:space:]]*"testflight-exact-build-preserved-data-install-pending"[\s\S]*without deleting or clearing app data' "fearless-iOS exact Apple-delivered install and preserved-data rehearsal blocker"

  require_pattern "$audit" 'TESTFLIGHT_PUBLICATION_AUDIT_EXPECTED_MANIFEST_SHA256:-d66634ec2fce2305e2cc64e18e55c273dcc802bc82e074f658bef72ad8d53b26' "fearless-iOS current TestFlight audit-pinned manifest digest"
  require_pattern "$audit" 'publicationVerified disagrees with upload, group, or public-link evidence' "fearless-iOS current TestFlight publication cross-field gate"
  require_pattern "$audit" 'releaseEnabled requires publication, exact Apple-delivered install, preserved-data rehearsal, and symbolication closure' "fearless-iOS current TestFlight release enablement gate"
  require_pattern "$audit" 'tracked publication evidence is valid; exact Apple-delivered install remains blocked' "fearless-iOS current TestFlight audit completion marker"
