  require_exact_pattern_count "$audit_test" '^expect_failure(_with_digest)?[[:space:]]' 69 "fearless-iOS current TestFlight exactly 69 negative/adversarial fixtures"
  require_pattern "$audit_test" 'CASES != EXPECTED_CASES' "fearless-iOS current TestFlight runtime case-count enforcement"
  require_pattern "$audit_test" 'passed \$CASES cases \(1 valid \+ \$\(\(CASES - 1\)\) negative/adversarial\)' "fearless-iOS current TestFlight self-test completion inventory"

  require_pattern "$readiness_doc" 'Status: \*\*BLOCKED only on exact Apple-delivered install/rehearsal and symbolication follow-up\*\*' "fearless-iOS documented current TestFlight readiness"
  require_pattern_multiline "$readiness_doc" '`4\.2\.0 \(2026\.7\.26\)` is `Testing`[\s\S]*9410949d-b468-40e5-b2f4-24055e65d270[\s\S]*`122` testers, `2` builds[\s\S]*`120/500` public-link places used[\s\S]*https://testflight\.apple\.com/join/012KzFyD' "fearless-iOS documented active public TestFlight group snapshot"
  require_pattern_multiline "$readiness_doc" 'ignored `build/` output[\s\S]*must not be treated as canonical release source' "fearless-iOS documented ignored raw-attestation boundary"
  require_pattern_multiline "$readiness_doc" 'MPQRCoreSDK\.framework[\s\S]*degraded symbolication[\s\S]*production[[:space:]]*acceptance' "fearless-iOS documented dSYM follow-up"
  require_pattern_multiline "$readiness_doc" 'Do not uninstall the app or clear its container[\s\S]*exactAppleDeliveredInstallVerified=false[\s\S]*preservedDataPostInstallRehearsalVerified=false[\s\S]*releaseEnabled=false' "fearless-iOS documented exact install/rehearsal blocker"
  require_pattern "$release" 'test-testflight-publication-readiness-audit\.sh.*audit-testflight-publication-readiness\.sh' "fearless-iOS release-checklist current TestFlight evidence gate"
  require_pattern_multiline "$release" 'Do not mark the TestFlight[[:space:]]*build release-enabled until an in-place TestFlight update preserves the[[:space:]]*existing app container' "fearless-iOS release-checklist exact Apple-delivered install gate"
  require_exact_line_count "$run_pr" 'bash "$WORKSPACE_DIR/scripts/test-testflight-publication-readiness-audit.sh"' 1 "fearless-iOS PR current TestFlight adversarial self-test"
  require_exact_line_count "$run_pr" 'bash "$WORKSPACE_DIR/scripts/audit-testflight-publication-readiness.sh"' 1 "fearless-iOS PR current TestFlight publication audit"
  require_exact_line_count "$workflow" '          bash ./scripts/test-testflight-publication-readiness-audit.sh' 1 "fearless-iOS CI current TestFlight adversarial self-test"
  require_exact_line_count "$workflow" '          bash ./scripts/audit-testflight-publication-readiness.sh' 1 "fearless-iOS CI current TestFlight publication audit"
  require_pattern "$workflow" 'codecov/codecov-action@fb8b3582c8e4def4969c97caa2f19720cb33a72f' "fearless-iOS reviewed Codecov v7 action pin"
  reject_pattern "$workflow" 'codecov/codecov-action@671740ac38dd9b0130fbe1cec585b89eea48d3de' "fearless-iOS retired Codecov v5 action pin"
  require_pattern "$codecov_coverage_audit" 'require_text "codecov/codecov-action@fb8b3582c8e4def4969c97caa2f19720cb33a72f"' "fearless-iOS coverage contract exact Codecov v7 pin gate"
  require_pattern_multiline "$codecov_workflow_audit" 'codecov/codecov-action@fb8b3582c8e4def4969c97caa2f19720cb33a72f[\s\S]{0,180}reviewed v7\.0\.0 commit with the live codecovsecops verification-key endpoint' "fearless-iOS Codecov live verification-key endpoint action gate"
  require_pattern "$codecov_coverage_test" 'retired Codecov verification-key endpoint action' "fearless-iOS retired Codecov endpoint regression"
  require_pattern "$codecov_coverage_test" '^\[\[ "\$positive_count" == "1" && "\$negative_count" == "8" \]\] \|\|$' "fearless-iOS Codecov exact 1-positive/8-adversarial sentinel"
}

ios_release_signing_gate_checks() {
  local repo_path="$1"
  local scheme="$repo_path/fearless.xcodeproj/xcshareddata/xcschemes/fearless.xcscheme"
  local workflow="$repo_path/.github/workflows/codecov.yml"
  local run_pr="$repo_path/scripts/ci/run-pr.sh"
  local gate="$repo_path/scripts/ci/run-release-signing-gate.sh"
  local bootstrap="$repo_path/scripts/ci/run-release-signing-ci.sh"
  local audit="$repo_path/scripts/audit-release-signing-gate.sh"
  local audit_test="$repo_path/scripts/test-release-signing-gate-audit.sh"
  local behavior_test="$repo_path/scripts/test-release-signing-gate.sh"
  local bootstrap_test="$repo_path/scripts/test-release-signing-bootstrap.sh"

  require_file "$scheme" "fearless-iOS shared Release archive scheme"
  require_executable_file "$gate" "fearless-iOS signed Release archive gate"
  require_executable_file "$bootstrap" "fearless-iOS ephemeral Release signing bootstrap"
  require_executable_file "$audit" "fearless-iOS signed Release archive gate audit"
  require_executable_file "$audit_test" "fearless-iOS signed Release archive audit adversarial test"
  require_executable_file "$behavior_test" "fearless-iOS signed Release archive behavioral test"
  require_executable_file "$bootstrap_test" "fearless-iOS signing-bootstrap behavioral test"

  require_pattern_multiline "$scheme" '<ArchiveAction[\s\S]*buildConfiguration = "Release"' "fearless-iOS Release archive action"
  require_pattern "$scheme" 'export STRICT_REQUIRED_PATCHES=1' "fearless-iOS strict manual Archive dependency preaction"
  require_pattern "$scheme" 'export ALLOW_DERIVEDDATA_FALLBACK=0' "fearless-iOS repository-owned manual Archive dependency preaction"
  require_pattern "$scheme" 'if ! bash \\&quot;\$\{PROJECT_DIR\}/scripts/spm-shared-features-fixes\.sh\\&quot;' "fearless-iOS explicit manual Archive dependency failure check"
  require_pattern "$scheme" '^[[:space:]]*exit 1$' "fearless-iOS fail-closed manual Archive dependency preaction"
  reject_pattern "$scheme" 'spm-shared-features-fixes\.sh[^<]*[|][|][[:space:]]*true' "fearless-iOS fail-open manual Archive dependency preaction"

  require_pattern "$workflow" 'bash \./scripts/test-release-signing-gate-audit\.sh' "fearless-iOS CI signed Release audit self-test"
  require_pattern "$workflow" 'bash \./scripts/test-release-signing-gate\.sh' "fearless-iOS CI signed Release behavioral self-test"
  require_pattern "$workflow" 'bash \./scripts/test-release-signing-bootstrap\.sh' "fearless-iOS CI ephemeral signing-bootstrap self-test"
  require_pattern "$workflow" 'bash \./scripts/audit-release-signing-gate\.sh' "fearless-iOS CI signed Release audit"
  require_pattern_multiline "$workflow" '      - name: Signed Release archive gate\n        if: github\.event_name == '\''push'\''\n        env:\n          IOS_RELEASE_SIGNING_REQUIRED: '\''1'\''\n          IOS_RELEASE_CERTIFICATE_P12_BASE64: \$\{\{ secrets\.IOS_RELEASE_CERTIFICATE_P12_BASE64 \}\}\n          IOS_RELEASE_CERTIFICATE_PASSWORD: \$\{\{ secrets\.IOS_RELEASE_CERTIFICATE_PASSWORD \}\}\n          IOS_RELEASE_PROVISIONING_PROFILE_BASE64: \$\{\{ secrets\.IOS_RELEASE_PROVISIONING_PROFILE_BASE64 \}\}\n        run: bash \./scripts/ci/run-release-signing-ci\.sh' "fearless-iOS exact trusted-push ephemeral signing CI block"
  reject_pattern "$workflow" 'vars\.IOS_RELEASE_SIGNING_REQUIRED|IOS_RELEASE_SIGNING_REQUIRED:[[:space:]]*['\''"]?0' "fearless-iOS optional protected-push signing policy"
  require_pattern "$run_pr" 'test-release-signing-gate-audit\.sh' "fearless-iOS PR signed Release audit self-test"
  require_pattern "$run_pr" 'test-release-signing-gate\.sh' "fearless-iOS PR signed Release behavioral self-test"
  require_pattern "$run_pr" 'test-release-signing-bootstrap\.sh' "fearless-iOS PR signing-bootstrap behavioral self-test"
  require_pattern "$run_pr" 'audit-release-signing-gate\.sh' "fearless-iOS PR signed Release audit"

  require_pattern_multiline "$gate" 'GITHUB_ACTIONS:-false[\s\S]*GITHUB_EVENT_NAME:-[\s\S]*== "push"[\s\S]*refs/heads/develop[|]refs/heads/master' "fearless-iOS signing-material trusted event and branch fence"
  require_pattern_multiline "$gate" '-configuration Release[\s\S]*-destination '\''generic/platform=iOS'\''[\s\S]*-disableAutomaticPackageResolution[\s\S]*archive >"\$build_log" 2>&1' "fearless-iOS real generic-device Release archive command"
  require_pattern "$gate" 'Signing material is only partially configured' "fearless-iOS partial signing material fail-closed gate"
  require_pattern "$gate" 'IOS_RELEASE_SIGNING_REQUIRED' "fearless-iOS explicit required-signing policy"
  require_pattern "$gate" 'profile_matches_release_contract "\$embedded_profile"' "fearless-iOS embedded profile production-contract verification"
  require_pattern "$gate" 'plist_value "\$profile" '\''Entitlements\.beta-reports-active'\''[^\n]*== "true"' "fearless-iOS embedded App Store beta entitlement verification"
  require_pattern "$gate" 'plist_value "\$signed_entitlements" '\''beta-reports-active'\''[^\n]*== "true"' "fearless-iOS signed App Store beta entitlement verification"
  require_pattern "$gate" 'signed_get_task_allow" == "false" && "\$profile_get_task_allow" == "false"' "fearless-iOS production get-task-allow false verification"
  require_pattern "$gate" 'ProvisionedDevices' "fearless-iOS ad-hoc/development profile rejection"
  require_pattern "$gate" 'IOS_RELEASE_EXPECTED_PROFILE_UUID' "fearless-iOS exact bootstrapped profile UUID binding"
  require_pattern "$gate" 'PROVISIONING_PROFILE_SPECIFIER=\$PROFILE_SPECIFIER' "fearless-iOS explicit bootstrapped profile selection"
  require_pattern "$gate" '"\$CODESIGN_BIN" --verify --deep --strict' "fearless-iOS strict archived application signature verification"
  require_pattern "$gate" 'PrivacyInfo\.xcprivacy' "fearless-iOS signed Release privacy manifest verification"
  require_pattern "$gate" 'keychain-access-groups' "fearless-iOS signed Release keychain entitlement allow-list"
  require_pattern "$gate" 'chmod 600 "\$build_log"' "fearless-iOS private signed archive build log"
  require_pattern_multiline "$gate" '\[REDACTED_DIGEST\][\s\S]*Signing Identity:[^\n]*\[REDACTED\][\s\S]*Provisioning Profile:[^\n]*\[REDACTED\][\s\S]*Certificate:[^\n]*\[REDACTED\]' "fearless-iOS signing failure diagnostic redaction"
  reject_pattern "$gate" '(^|[[:space:]])set[[:space:]]+-x|(^|[[:space:]])(printenv|env)([[:space:]]|$)' "fearless-iOS signing environment dump"

  require_exact_pattern_count "$audit_test" '^expect_failure[[:space:]]' 26 "fearless-iOS signed Release audit exactly 26 adversarial fixtures"
  require_exact_pattern_count "$behavior_test" '(^|[[:space:]])expect_failure([[:space:]]|\\)' 24 "fearless-iOS signed Release gate exactly 24 behavioral negative fixtures"
  require_exact_pattern_count "$bootstrap_test" '(^|[[:space:]])expect_failure([[:space:]]|\\)' 9 "fearless-iOS signing bootstrap exactly 9 behavioral negative fixtures"
  require_pattern "$audit_test" 'fail-open archive preaction' "fearless-iOS Archive preaction fail-open adversarial fixture"
  require_pattern "$audit_test" 'signing untrusted pull requests' "fearless-iOS untrusted-PR signing adversarial fixture"
  require_pattern "$audit_test" 'world-readable archive log' "fearless-iOS signing-log permission adversarial fixture"
  require_pattern "$audit_test" 'signing environment dump' "fearless-iOS signing-environment adversarial fixture"
  require_pattern "$behavior_test" 'pull-request signing attempt' "fearless-iOS behavioral untrusted-PR rejection"
  require_pattern "$behavior_test" 'missing required signing material' "fearless-iOS behavioral missing-signing-material rejection"
  require_pattern "$behavior_test" 'archive failure' "fearless-iOS behavioral archive-failure rejection"
  require_pattern "$behavior_test" 'invalid application signature' "fearless-iOS behavioral invalid-signature rejection"
  require_pattern "$behavior_test" 'profile with stale CloudKit container' "fearless-iOS behavioral stale-profile rejection"
  require_pattern "$behavior_test" 'development-signed archive' "fearless-iOS behavioral development-profile rejection"
  require_pattern "$behavior_test" 'profile without beta reporting' "fearless-iOS behavioral missing beta-report entitlement rejection"
  require_pattern "$bootstrap_test" 'missing signing secrets' "fearless-iOS behavioral missing signing-secret rejection"
  require_pattern "$bootstrap_test" 'partially configured signing secrets' "fearless-iOS behavioral partial signing-secret rejection"
  require_pattern "$bootstrap_test" 'ephemeral keychain cleanup failure' "fearless-iOS behavioral signing cleanup rejection"

  require_pattern_multiline "$bootstrap" 'GITHUB_ACTIONS:-false[\s\S]*GITHUB_EVENT_NAME:-[\s\S]*== "push"[\s\S]*refs/heads/develop[|]refs/heads/master[\s\S]*IOS_RELEASE_SIGNING_REQUIRED:-[\s\S]*== "1"[\s\S]*IOS_RELEASE_CERTIFICATE_P12_BASE64[\s\S]*IOS_RELEASE_CERTIFICATE_PASSWORD[\s\S]*IOS_RELEASE_PROVISIONING_PROFILE_BASE64' "fearless-iOS trusted-event-before-secret bootstrap fence"
  require_pattern "$bootstrap" 'Release-signing secrets are missing' "fearless-iOS missing signing-secret fail-closed bootstrap"
  require_pattern "$bootstrap" 'Release-signing secrets are only partially configured' "fearless-iOS partial signing-secret fail-closed bootstrap"
  require_pattern "$bootstrap" '^if \(\(configured != 3\)\); then$' "fearless-iOS exact all-or-nothing signing-secret cardinality gate"
  require_pattern "$bootstrap" 'create-keychain' "fearless-iOS ephemeral signing keychain creation"
  require_pattern "$bootstrap" 'set-key-partition-list' "fearless-iOS ephemeral keychain partition constraint"
  require_pattern "$bootstrap" 'delete-keychain "\$keychain_path"' "fearless-iOS ephemeral signing keychain cleanup"
  require_pattern "$bootstrap" 'rm -f -- "\$installed_profile"' "fearless-iOS ephemeral provisioning profile cleanup"
  require_pattern "$bootstrap" 'unset certificate_base64 profile_base64' "fearless-iOS encoded signing material lifetime bound"
  require_pattern "$bootstrap" 'unset certificate_password' "fearless-iOS certificate password lifetime bound"
  reject_pattern "$bootstrap" '(^|[[:space:]])set[[:space:]]+-x|(^|[[:space:]])(printenv|env)([[:space:]]|$)' "fearless-iOS signing-bootstrap environment dump"
}

