  require_pattern "$bitcoin_smoke_doc" 'bitcoin-testnet-broadcast-evidence\.json' "fearless-wallet-web Bitcoin smoke docs evidence manifest"
  require_pattern "$bitcoin_smoke_doc" 'generate:bitcoin-broadcast-evidence-template' "fearless-wallet-web Bitcoin smoke docs template generator"
  require_pattern "$bitcoin_smoke_doc" 'audit:bitcoin-broadcast-evidence --require-ready' "fearless-wallet-web Bitcoin smoke docs ready audit"
  require_pattern "$bitcoin_smoke_doc" 'https://blockstream\.info/testnet/api' "fearless-wallet-web Bitcoin smoke docs canonical indexer"

  require_pattern "$universal_fields" 'deriveBitcoinReceiveAddress' "fearless-wallet-web Universal Wallet Bitcoin field derivation"
  require_pattern "$universal_fields" 'deriveSolanaAddress' "fearless-wallet-web Universal Wallet Solana field derivation"
  require_pattern "$universal_fields" 'deriveTonAccount' "fearless-wallet-web Universal Wallet TON field derivation"
  require_pattern "$universal_fields" 'deriveIrohaAddress' "fearless-wallet-web Universal Wallet Iroha field derivation"
  require_pattern "$add_wallet" 'deriveUniversalWalletKeyringFields' "fearless-wallet-web standard create flow Universal Wallet field derivation"
  require_pattern "$google_create" 'deriveUniversalWalletKeyringFields' "fearless-wallet-web Google create flow Universal Wallet field derivation"
  require_pattern "$universal_fields_test" 'derives active public keyring fields from Universal Wallet V2 vectors' "fearless-wallet-web Universal Wallet active-field vector test"
  require_pattern "$universal_fields_test" 'rejects malformed mnemonics before returning partial keyring fields' "fearless-wallet-web Universal Wallet malformed mnemonic adversarial test"
  require_pattern "$universal_fields_test" 'does not reuse TON testnet-only addresses for mainnet metadata' "fearless-wallet-web Universal Wallet TON mainnet adversarial test"

  require_pattern "$release" 'test-public-artifacts-audit\.sh' "fearless-wallet-web release checklist public artifact audit self-test"
  require_pattern "$release" 'IROHA_JS_SDK_(VERSION|TARBALL|RELEASE_)' "fearless-wallet-web release checklist Iroha JS SDK artifact pin"
  require_pattern_i "$release" 'Solana extension e2e smoke' "fearless-wallet-web release checklist Solana e2e smoke"
  require_pattern "$release" 'yarn test:smoke:bitcoin' "fearless-wallet-web release checklist Bitcoin smoke"
  require_pattern "$release" 'test:bitcoin-broadcast-evidence-template' "fearless-wallet-web release checklist Bitcoin evidence template self-test"
  require_exact_line_count \
    "$release" \
    '  `yarn generate:bitcoin-broadcast-evidence-template -- --output' \
    1 \
    "fearless-wallet-web release checklist Bitcoin evidence template generator"
  require_exact_line_count \
    "$release" \
    'build/reports/bitcoin-broadcast-evidence-template.json`,' \
    1 \
    "fearless-wallet-web release checklist Bitcoin evidence template generator output"
  require_exact_adjacent_line_pair_count \
    "$release" \
    '  `yarn generate:bitcoin-broadcast-evidence-template -- --output' \
    'build/reports/bitcoin-broadcast-evidence-template.json`,' \
    1 \
    "fearless-wallet-web release checklist Bitcoin evidence template generator command block"
  require_pattern "$release" 'test:bitcoin-broadcast-evidence-audit' "fearless-wallet-web release checklist Bitcoin evidence self-test"
  require_exact_line_count \
    "$release" \
    '  `yarn audit:bitcoin-broadcast-evidence --require-ready`.' \
    1 \
    "fearless-wallet-web release checklist Bitcoin ready evidence audit"
  require_pattern "$release" 'scripts/bitcoin-testnet-broadcast-evidence\.json' "fearless-wallet-web release checklist Bitcoin evidence manifest"
  require_pattern "$release" 'releaseEnabled: true' "fearless-wallet-web release checklist Bitcoin release-enabled requirement"
  require_pattern "$release" 'https://blockstream\.info/testnet/api' "fearless-wallet-web release checklist Bitcoin canonical indexer"
}

web_firefox_release_checks() {
  local repo_path="$1"
  local workflow="$repo_path/.github/workflows/ci.yml"
  local package_json="$repo_path/package.json"
  local contributing="$repo_path/CONTRIBUTING.md"
  local build_script="$repo_path/scripts/build-extension.mjs"
  local build_policy="$repo_path/scripts/firefox-build-warning-policy.mjs"
  local build_policy_test="$repo_path/scripts/test-firefox-build-warning-policy.mjs"
  local webext_policy="$repo_path/scripts/firefox-webext-warning-policy.mjs"
  local webext_policy_test="$repo_path/scripts/test-firefox-webext-warning-policy.mjs"
  local webext_audit="$repo_path/scripts/audit-firefox-webext-warnings.mjs"
  local webext_baseline="$repo_path/config/firefox-webext-warning-baseline.json"
  local smoke_policy="$repo_path/scripts/firefox-extension-smoke-policy.mjs"
  local smoke_policy_test="$repo_path/scripts/test-firefox-extension-smoke-policy.mjs"
  local smoke="$repo_path/scripts/firefox-extension-smoke.mjs"
  local vite_config="$repo_path/vite.config.shared.mjs"
  local vm_shim="$repo_path/src/util/unsupportedNodeVm.ts"
  local vm_test="$repo_path/tests/unit/asn1-browser-fallback.spec.ts"
  local routes="$repo_path/src/router/routes.ts"
  local routes_test="$repo_path/tests/unit/router-catch-all.spec.ts"

  require_file "$build_script" "fearless-wallet-web Firefox production build entrypoint"
  require_file "$build_policy" "fearless-wallet-web Firefox build-warning policy"
  require_file "$build_policy_test" "fearless-wallet-web Firefox build-warning adversarial test"
  require_file "$webext_policy" "fearless-wallet-web Firefox web-ext warning policy"
  require_file "$webext_policy_test" "fearless-wallet-web Firefox web-ext warning adversarial test"
  require_file "$webext_audit" "fearless-wallet-web Firefox web-ext warning audit"
  require_file "$webext_baseline" "fearless-wallet-web Firefox exact warning baseline"
  require_file "$smoke_policy" "fearless-wallet-web Firefox runtime smoke policy"
  require_file "$smoke_policy_test" "fearless-wallet-web Firefox runtime smoke adversarial test"
  require_file "$smoke" "fearless-wallet-web real Firefox extension runtime smoke"
  require_file "$vite_config" "fearless-wallet-web browser build configuration"
  require_file "$vm_shim" "fearless-wallet-web fail-closed browser vm shim"
  require_file "$vm_test" "fearless-wallet-web asn1 browser fallback test"
  require_file "$routes" "fearless-wallet-web Vue Router route table"
  require_file "$routes_test" "fearless-wallet-web Firefox-compatible router regression test"
  require_file "$contributing" "fearless-wallet-web Firefox release documentation"

  require_pattern_multiline "$build_script" 'createFirefoxBuildLogPolicy[\s\S]*browser === '\''firefox'\'' && mode === '\''production'\'' && !watch[\s\S]*production Firefox builds must name a warning-policy target[\s\S]*customLogger:[[:space:]]*firefoxLogPolicy\.logger[\s\S]*onLog:[[:space:]]*firefoxLogPolicy\.onLog' "fearless-wallet-web per-target fail-closed Firefox build warning wiring"
  require_pattern "$build_script" 'polkadotIifePackageInfoPlugin' "fearless-wallet-web scoped Polkadot package-info normalizer wiring"
  require_pattern "$build_policy" 'unreviewed \$\{buildTarget\} warning' "fearless-wallet-web unknown Rolldown warning rejection"
  require_pattern "$build_policy" 'unreviewed \$\{buildTarget\} Vite warning' "fearless-wallet-web unknown Vite warning rejection"
  require_pattern "$build_policy" 'warning source escapes the repository' "fearless-wallet-web build-warning source containment"
  require_pattern_multiline "$build_policy" 'POLKADOT_PACKAGE_INFO_PATH[\s\S]*source\.includes\('\''import\.meta'\''\)[\s\S]*source\.replace\(PACKAGE_INFO_PATH_EXPRESSION, "'\''auto'\''"\)[\s\S]*code\.includes\('\''import\.meta'\''\)' "fearless-wallet-web exact package-metadata import.meta normalization"
  require_pattern "$build_policy_test" 'new warning code' "fearless-wallet-web new build-warning adversarial fixture"
  require_pattern "$build_policy_test" 'EMPTY_IMPORT_META' "fearless-wallet-web empty-import-meta regression fixture"
  require_pattern "$build_policy_test" 'warning path escape' "fearless-wallet-web build-warning traversal fixture"
  require_pattern "$build_policy_test" 'Vite warning bypassing Rolldown review' "fearless-wallet-web Vite warning bypass fixture"
  require_pattern "$build_policy_test" 'reviewed warning replay' "fearless-wallet-web warning replay fixture"

  require_pattern "$webext_policy" 'FIREFOX_WARNING_POLICY_SCHEMA_VERSION = 1' "fearless-wallet-web Firefox warning baseline schema"
  require_pattern "$webext_policy" 'DANGEROUS_EVAL' "fearless-wallet-web reviewed dangerous-eval warning class"
  require_pattern "$webext_policy" 'UNSAFE_VAR_ASSIGNMENT' "fearless-wallet-web reviewed unsafe-var warning class"
  require_pattern "$webext_policy" 'warning fingerprint digest drifted' "fearless-wallet-web exact warning fingerprint gate"
  require_pattern "$webext_policy" 'warning-bearing artifact digest drifted' "fearless-wallet-web warning-bearing bundle digest gate"
  require_pattern "$webext_policy" 'must not contain symlinks' "fearless-wallet-web warning artifact symlink rejection"
  require_pattern "$webext_policy_test" 'new warning' "fearless-wallet-web added warning adversarial fixture"
  require_pattern "$webext_policy_test" 'removed warning' "fearless-wallet-web removed warning adversarial fixture"
  require_pattern "$webext_policy_test" 'artifact content drift' "fearless-wallet-web warning artifact drift fixture"
  require_pattern "$webext_policy_test" 'symlink artifact' "fearless-wallet-web warning symlink fixture"
  require_pattern "$webext_policy_test" 'all 19 adversarial tests passed' "fearless-wallet-web exact web-ext adversarial test sentinel"
  require_pattern_multiline "$webext_audit" 'spawnSync[\s\S]*--output=json[\s\S]*childEnvironment[\s\S]*JSON\.parse[\s\S]*verifyFirefoxWarningBaseline' "fearless-wallet-web isolated structured web-ext lint audit"
  require_pattern "$webext_baseline" '"webExtVersion":[[:space:]]*"10\.4\.0"' "fearless-wallet-web pinned web-ext warning baseline version"
  require_pattern "$webext_baseline" '"warningCount":[[:space:]]*45' "fearless-wallet-web exact Firefox warning count"
  require_pattern "$webext_baseline" '"DANGEROUS_EVAL":[[:space:]]*44' "fearless-wallet-web exact dangerous-eval warning count"
  require_pattern "$webext_baseline" '"UNSAFE_VAR_ASSIGNMENT":[[:space:]]*1' "fearless-wallet-web exact unsafe-var warning count"
  require_pattern "$webext_baseline" '"warningSetSha256":[[:space:]]*"[0-9a-f]{64}"' "fearless-wallet-web exact warning fingerprint digest"

  require_pattern_multiline "$smoke_policy" 'VERIFIED_FIREFOX_VERSION = '\''152\.0\.4'\''[\s\S]*FIREFOX_CI_WORKFLOW_BLOCK[\s\S]*assertFirefoxWorkflowContract[\s\S]*requireCiFirefoxBinary[\s\S]*absolute FIREFOX_BINARY[\s\S]*assertFirefoxVersionResult[\s\S]*exactly one Mozilla Firefox version line[\s\S]*BoundedOutput[\s\S]*withTimeout[\s\S]*Vue did not mark the popup root as mounted[\s\S]*popup rendered no interactive controls[\s\S]*EvalError[\s\S]*createSmokeEnvironment[\s\S]*NODE_OPTIONS' "fearless-wallet-web bounded executable-bound pinned-runtime popup/CSP smoke policy"
  require_pattern "$smoke_policy_test" 'stalled RDP request' "fearless-wallet-web stalled RDP adversarial fixture"
  require_pattern "$smoke_policy_test" 'wrong origin' "fearless-wallet-web popup-origin adversarial fixture"
  require_pattern "$smoke_policy_test" 'mutable or partial Firefox version' "fearless-wallet-web mutable Firefox-version adversarial fixtures"
  require_pattern "$smoke_policy_test" 'CSP permits Function' "fearless-wallet-web permissive-CSP adversarial fixture"
  require_pattern "$smoke_policy_test" 'WEB_EXT_FIREFOX' "fearless-wallet-web web-ext environment injection fixture"
  require_pattern "$smoke_policy_test" 'unexpected process probe failure' "fearless-wallet-web process-cleanup adversarial fixture"
  require_pattern "$smoke_policy_test" 'missing setup step id' "fearless-wallet-web detached setup/smoke CI adversarial fixture"
  require_pattern "$smoke_policy_test" 'mismatched executable Firefox version' "fearless-wallet-web actual executable version adversarial fixture"
  require_pattern "$smoke_policy" 'const candidate = environment\.FIREFOX_BINARY' "fearless-wallet-web mandatory CI Firefox path source"
  require_pattern "$smoke" 'const requiredCiBinary = requireCiFirefoxBinary\(process\.env\)' "fearless-wallet-web CI Firefox path enforcement call"
  require_pattern "$smoke" 'if \(requiredCiBinary\) return firstExecutable\(\[requiredCiBinary\]\);' "fearless-wallet-web no-system-fallback CI Firefox resolution"
  require_pattern_multiline "$smoke" 'spawnSync[\s\S]*VERIFIED_FIREFOX_VERSION[\s\S]*assertFirefoxVersionResult[\s\S]*requireCiFirefoxBinary[\s\S]*RDP_REQUEST_TIMEOUT_MS = 5_000[\s\S]*EXPECTED_EXTENSION_ID[\s\S]*--version[\s\S]*assertFirefoxVersionResult\(result, VERIFIED_FIREFOX_VERSION\)[\s\S]*requestRDP[\s\S]*waitForAddon[\s\S]*waitForRenderedPopup[\s\S]*assertPopupState[\s\S]*assertCspState[\s\S]*recordedErrors[\s\S]*findRuntimeErrors' "fearless-wallet-web executable-version-bound real Firefox RDP popup/CSP/runtime assertions"
  require_pattern "$smoke" 'detached:[[:space:]]*ownsProcessGroup' "fearless-wallet-web detached owned Firefox process group"
  require_pattern "$smoke" 'process\.kill\(-child\.pid,[[:space:]]*signal\)' "fearless-wallet-web whole Firefox process-group signaling"
  require_pattern "$smoke" 'survived SIGKILL' "fearless-wallet-web fail-closed Firefox process cleanup"
  require_pattern "$smoke" 'createSmokeEnvironment\(process\.env\)' "fearless-wallet-web Firefox smoke environment sanitization"

  require_pattern_multiline "$vite_config" 'UNSUPPORTED_NODE_VM[\s\S]*vm:[[:space:]]*UNSUPPORTED_NODE_VM[\s\S]*'\''node:vm'\'':[[:space:]]*UNSUPPORTED_NODE_VM' "fearless-wallet-web explicit vm/node:vm browser aliases"
  require_pattern "$vm_shim" 'Node\.js vm is unavailable in a browser extension' "fearless-wallet-web direct browser vm fail-closed error"
  require_pattern "$vm_test" 'still encodes and decodes DER through the dependency browser fallback' "fearless-wallet-web asn1 browser fallback execution test"
  require_pattern "$routes" 'path:[[:space:]]*'\''/:pathMatch\(\.\*\)\*'\''' "fearless-wallet-web Vue Router 5 catch-all"
  reject_pattern "$routes" 'path:[[:space:]]*'\''\*'\''' "fearless-wallet-web legacy star catch-all"
  require_pattern "$routes" 'params:[[:space:]]*\{[[:space:]]*type:[[:space:]]*'\''substrate'\''[[:space:]]*\}' "fearless-wallet-web exact authentication redirect params"
  require_pattern "$routes_test" 'nested/not-real\?attempt=shadow-known-route#fragment' "fearless-wallet-web adversarial nested catch-all regression"
  require_pattern "$routes_test" 'Components\.AccountSetting' "fearless-wallet-web nested accounts default-route regression"
  require_pattern "$routes_test" 'params:[[:space:]]*\{[[:space:]]*type:[[:space:]]*'\''substrate'\''[[:space:]]*\}' "fearless-wallet-web auth redirect-param regression"

  require_pattern "$package_json" '"build:extension:firefox"[[:space:]]*:[[:space:]]*"yarn test:firefox-build-warning-policy &&' "fearless-wallet-web Firefox build policy script wiring"
  require_pattern "$package_json" '"lint:webext:firefox"[[:space:]]*:[[:space:]]*"node scripts/test-firefox-webext-warning-policy\.mjs && node scripts/audit-firefox-webext-warnings\.mjs"' "fearless-wallet-web strict Firefox web-ext lint script"
  require_pattern "$package_json" '"test:smoke:firefox"[[:space:]]*:[[:space:]]*"yarn test:firefox-smoke-policy && node scripts/firefox-extension-smoke\.mjs"' "fearless-wallet-web Firefox smoke self-test/runtime wiring"
  require_pattern "$package_json" '"test:e2e:firefox"[[:space:]]*:[[:space:]]*"yarn build:extension:firefox && yarn lint:webext:firefox && yarn test:smoke:firefox"' "fearless-wallet-web full Firefox extension end-to-end script"
  require_pattern "$workflow" 'run:[[:space:]]*yarn build:extension:firefox' "fearless-wallet-web CI Firefox production build"
  require_pattern "$workflow" 'run:[[:space:]]*yarn lint:webext:firefox' "fearless-wallet-web CI strict Firefox package lint"
  require_pattern "$workflow" 'browser-actions/setup-firefox@0bc507ddf224827e3b1af68e014d5e42ab93e795' "fearless-wallet-web pinned Firefox setup action"
  require_pattern "$workflow" 'firefox-version:[[:space:]]*152\.0\.4' "fearless-wallet-web pinned Firefox runtime version"
  reject_pattern "$workflow" 'firefox-version:[[:space:]]*(latest|beta|nightly|esr)' "fearless-wallet-web mutable Firefox runtime alias"
  require_pattern_multiline "$workflow" '      - name: Set up Firefox\n        id: setup-firefox\n        uses: browser-actions/setup-firefox@0bc507ddf224827e3b1af68e014d5e42ab93e795[^\n]*\n        with:\n          firefox-version: 152\.0\.4\n\n      - name: Firefox extension runtime and CSP smoke\n        run: yarn test:smoke:firefox\n        env:\n          FIREFOX_BINARY: \$\{\{ steps\.setup-firefox\.outputs\.firefox-path \}\}' "fearless-wallet-web exact contiguous pinned Firefox setup/runtime block"
  require_pattern "$contributing" 'Never update it just to make CI green' "fearless-wallet-web warning-baseline review policy documentation"
  require_pattern_multiline "$contributing" 'fresh headless[[:space:]]+Firefox profile[\s\S]*exact executable reports `Mozilla Firefox[[:space:]]*152\.0\.4`[\s\S]*cannot fall back to a system Firefox' "fearless-wallet-web executable-version-bound real Firefox runtime documentation"
}

ios_website_association_parity_checks() {
  local site_path="$1"
  local ios_path="$2"
  local ios_project="$ios_path/fearless.xcodeproj/project.pbxproj"
  local ios_signing_gate="$ios_path/scripts/ci/run-release-signing-gate.sh"
  local passkey_config="$ROOT_DIR/config/passkey-backup-production.json"
  local association_verifier="$site_path/scripts/verify-app-associations.mjs"
  local extensionless_association="$site_path/src/public/.well-known/apple-app-site-association"
  local json_association="$site_path/src/public/.well-known/apple-app-site-association.json"
  local association_contract="$site_path/docs/app-association-contract.md"
  local association_test="$site_path/scripts/test-app-associations.sh"

  require_file "$ios_project" "fearless-iOS Xcode project for website association parity"
  require_file "$ios_signing_gate" "fearless-iOS release signing gate for website association parity"
  require_file "$passkey_config" "root passkey production config for website association parity"
  require_file "$association_verifier" "fearless-site-web app-association verifier for iOS parity"
  require_file "$extensionless_association" "fearless-site-web extensionless Apple association for iOS parity"
  require_file "$json_association" "fearless-site-web JSON Apple association for iOS parity"
  require_file "$association_contract" "fearless-site-web app-association identity documentation"
  require_file "$association_test" "fearless-site-web app-association adversarial test for iOS parity"

  if [[ ! -f "$ios_project" || ! -f "$ios_signing_gate" || ! -f "$passkey_config" ||
        ! -f "$association_verifier" || ! -f "$extensionless_association" ||
        ! -f "$json_association" || ! -f "$association_contract" || ! -f "$association_test" ]]; then
    return
  fi

  local diagnostic
  local diagnostic_file
  local parity_failed=false
  diagnostic_file="$(mktemp "${TMPDIR:-/tmp}/fearless-ios-association-parity.XXXXXX")"
  if ! node - \
    "$ios_project" \
    "$ios_signing_gate" \
    "$passkey_config" \
    "$association_verifier" \
    "$extensionless_association" \
    "$json_association" \
    "$association_contract" >"$diagnostic_file" 2>&1 <<'NODE'
const fs = require('node:fs');

const [
  iosProjectPath,
  signingGatePath,
  passkeyConfigPath,
  verifierPath,
  extensionlessPath,
  jsonAliasPath,
  contractPath,
] = process.argv.slice(2);

function fail(message) {
  throw new Error(message);
}

function assert(condition, message) {
  if (!condition) fail(message);
}

function readRegularFile(file, label) {
  const stat = fs.lstatSync(file);
  assert(stat.isFile() && !stat.isSymbolicLink(), `${label} must be a regular non-symlink file`);
  return fs.readFileSync(file, 'utf8');
}

function parseJsonFile(file, label) {
  const raw = readRegularFile(file, label);
  try {
    return JSON.parse(raw);
  } catch (error) {
    fail(`${label} must contain valid JSON (${error instanceof Error ? error.message : String(error)})`);
  }
}

function exactShellConstant(raw, name) {
  const pattern = new RegExp(`^${name}="([^"\\n]+)"$`, 'gmu');
  const matches = [...raw.matchAll(pattern)];
  assert(matches.length === 1, `fearless-iOS release signing gate must declare exactly one ${name}`);
  return matches[0][1];
}

function configurationBlocks(project, name) {
  const pattern = new RegExp(
    `[A-F0-9]{24} \\/\\* ${name} \\*\\/ = \\{[\\s\\S]*?\\n\\s*name = ${name};\\n\\s*\\};`,
    'gu',
  );
  return [...project.matchAll(pattern)].map((match) => match[0]);
}

function assertProjectConfiguration(project, name, bundleId, teamId) {
  const blocks = configurationBlocks(project, name);
  assert(blocks.length > 0, `fearless-iOS project must contain a ${name} configuration`);
  const exactBundle = `PRODUCT_BUNDLE_IDENTIFIER = ${bundleId};`;
  const exactTeam = `DEVELOPMENT_TEAM = ${teamId};`;
  assert(
    blocks.some((block) => block.includes(exactBundle) && block.includes(exactTeam)),
    `fearless-iOS ${name} bundle/team identity must match the website association contract`,
  );
}

function assertExactStringSet(actual, expected, label) {
  assert(Array.isArray(actual), `${label} must be an array`);
  assert(actual.every((value) => typeof value === 'string'), `${label} must contain only strings`);
  assert(new Set(actual).size === actual.length, `${label} must not contain duplicate identifiers`);
  const sortedActual = [...actual].sort();
  const sortedExpected = [...expected].sort();
  assert(
    JSON.stringify(sortedActual) === JSON.stringify(sortedExpected),
    `${label} must exactly match current fearless-iOS Release/Development application identifiers`,
  );
}

const iosProject = readRegularFile(iosProjectPath, 'fearless-iOS Xcode project');
const signingGate = readRegularFile(signingGatePath, 'fearless-iOS release signing gate');
const passkeyConfig = parseJsonFile(passkeyConfigPath, 'root passkey production config');
const verifier = readRegularFile(verifierPath, 'fearless-site-web app-association verifier');
const extensionless = parseJsonFile(extensionlessPath, 'fearless-site-web extensionless Apple association');
const jsonAlias = parseJsonFile(jsonAliasPath, 'fearless-site-web JSON Apple association');
const contract = readRegularFile(contractPath, 'fearless-site-web app-association contract');

const teamId = exactShellConstant(signingGate, 'EXPECTED_TEAM_ID');
const releaseBundleId = exactShellConstant(signingGate, 'EXPECTED_BUNDLE_ID');
assert(/^[A-Z0-9]{10}$/u.test(teamId), 'fearless-iOS release signing team ID must be canonical');
assert(
  /^[A-Za-z0-9]+(?:[.-][A-Za-z0-9]+)+$/u.test(releaseBundleId),
  'fearless-iOS release signing bundle ID must be canonical',
);

const cloudKitContainers = passkeyConfig?.ios?.cloudKitContainers;
assert(
  Array.isArray(cloudKitContainers) && cloudKitContainers.length === 2 &&
    cloudKitContainers.every((value) => typeof value === 'string'),
  'root passkey config must contain exactly the iOS release and development CloudKit containers',
);
assert(
  cloudKitContainers[0] === `iCloud.${releaseBundleId}`,
  'root passkey release CloudKit container must match the current iOS Release bundle ID',
);
const developmentContainer = cloudKitContainers[1];
assert(
  developmentContainer.startsWith('iCloud.') && developmentContainer.length > 'iCloud.'.length,
  'root passkey development CloudKit container must contain a bundle ID',
);
const developmentBundleId = developmentContainer.slice('iCloud.'.length);
assert(
  developmentBundleId !== releaseBundleId && developmentBundleId.endsWith('.dev'),
  'root passkey development CloudKit container must identify the distinct iOS Development bundle',
);

assertProjectConfiguration(iosProject, 'Release', releaseBundleId, teamId);
assertProjectConfiguration(iosProject, 'Dev', developmentBundleId, teamId);

const expectedApplicationIds = [
  `${teamId}.${releaseBundleId}`,
  `${teamId}.${developmentBundleId}`,
];
const verifierArray = verifier.match(/const IOS_APPLICATION_IDS = \[([\s\S]*?)\];/u);
assert(verifierArray, 'fearless-site-web verifier must declare IOS_APPLICATION_IDS');
const verifierApplicationIds = [...verifierArray[1].matchAll(/'([^']+)'/gu)].map((match) => match[1]);
assertExactStringSet(
  verifierApplicationIds,
  expectedApplicationIds,
  'fearless-site-web verifier IOS_APPLICATION_IDS',
);

assert(
  Array.isArray(extensionless?.applinks?.details),
  'extensionless Apple association must contain applinks.details',
);
assertExactStringSet(
  extensionless.applinks.details.map((detail) => detail?.appID),
  expectedApplicationIds,
  'extensionless Apple association applinks identifiers',
);
assertExactStringSet(
  extensionless?.webcredentials?.apps,
  expectedApplicationIds,
  'extensionless Apple association webcredentials identifiers',
);

assert(
  Array.isArray(jsonAlias?.applinks?.details) && jsonAlias.applinks.details.length === 1,
  'JSON Apple association must contain exactly one applinks detail',
);
assertExactStringSet(
  jsonAlias.applinks.details[0]?.appIDs,
  expectedApplicationIds,
  'JSON Apple association applinks identifiers',
);
assertExactStringSet(
  jsonAlias?.webcredentials?.apps,
  expectedApplicationIds,
  'JSON Apple association webcredentials identifiers',
);

const normalizedContract = contract.replace(/\s+/gu, ' ');
assert(
  normalizedContract.includes(
    `- iOS release bundle: \`${releaseBundleId}\`, from the Release target in that Xcode project.`,
  ),
  'fearless-site-web association docs must name the current iOS Release bundle ID',
);
assert(
  normalizedContract.includes(
    `- iOS development bundle: \`${developmentBundleId}\`, from the Dev target in that Xcode project.`,
  ),
  'fearless-site-web association docs must name the current iOS Development bundle ID',
);
NODE
  then
    parity_failed=true
  fi

  diagnostic="$(<"$diagnostic_file")"
  rm -f -- "$diagnostic_file"
  if [[ "$parity_failed" == "true" ]]; then
    record_failure "fearless-site-web/iOS app-association identity parity failed: $diagnostic"
  fi

  require_pattern "$association_test" \
    'retired production iOS application identifier' \
    "fearless-site-web retired production iOS application identifier adversarial test"
}

website_checks() {
  local repo_path="$1"
  local ci_file="$repo_path/.github/workflows/ci.yml"
  local package_json="$repo_path/package.json"
  local yarn_lock="$repo_path/yarn.lock"
