  local association_fetch_mock="$repo_path/scripts/test-app-associations-fetch-mock.mjs"
  local association_live_gate="$repo_path/.github/workflows/app-association-live-gate.yml"
  local nuxt_config="$repo_path/nuxt.config.ts"

  common_release_gate_checks "$repo_path" "fearless-site-web" "$ci_file"

