  require_file "$dependency_security" "fearless-site-web dependency security contract"
  require_file "$repo_path/scripts/verify-release-content.mjs" "fearless-site-web release-content verifier"
  require_file "$association_verifier" "fearless-site-web app-association verifier"
  require_executable_file "$association_test" "fearless-site-web app-association adversarial self-test"
  require_file "$association_fetch_mock" "fearless-site-web app-association mocked-live fetch harness"
  require_file "$association_live_gate" "fearless-site-web app-association scheduled live gate"
  require_file "$nuxt_config" "fearless-site-web Nuxt configuration"
  require_file "$repo_path/src/public/.well-known/assetlinks.json" "fearless-site-web Android app-association source"
  require_file "$repo_path/src/public/.well-known/apple-app-site-association" "fearless-site-web extensionless Apple app-association source"
  require_file "$repo_path/src/public/.well-known/apple-app-site-association.json" "fearless-site-web JSON Apple app-association source"

  require_pattern "$ci_file" 'yarn install --immutable' "fearless-site-web immutable dependency install"
  require_pattern "$ci_file" 'yarn audit:dependencies([[:space:]]|$)' "fearless-site-web full dependency audit"
  require_pattern "$ci_file" 'yarn audit:dependencies:production' "fearless-site-web production dependency audit"
  require_pattern "$ci_file" 'yarn verify:release-content' "fearless-site-web release-content CI gate"
  require_pattern "$ci_file" 'yarn test:app-associations' "fearless-site-web app-association adversarial CI gate"
  require_pattern "$ci_file" 'yarn verify:app-associations' "fearless-site-web app-association source CI gate"
  require_pattern "$ci_file" 'yarn typecheck' "fearless-site-web typecheck CI gate"
  require_pattern "$ci_file" 'yarn build' "fearless-site-web build CI gate"

  require_pattern "$package_json" '"verify:release-content"' "fearless-site-web release-content script"
  require_pattern "$package_json" '"verify:app-associations"' "fearless-site-web app-association source verification script"
  require_pattern "$package_json" '"verify:app-associations:live"' "fearless-site-web app-association live verification script"
  require_pattern "$package_json" '"test:app-associations"' "fearless-site-web app-association adversarial test script"
  require_pattern "$package_json" '"typecheck"' "fearless-site-web typecheck script"
  require_pattern "$package_json" '"audit:dependencies":[[:space:]]*"yarn npm audit --all --recursive --severity low --no-deprecations"' "fearless-site-web full dependency audit script"
  require_pattern "$package_json" '"audit:dependencies:production":[[:space:]]*"yarn npm audit --all --recursive --environment production --severity low --no-deprecations"' "fearless-site-web production dependency audit script"
  require_pattern "$package_json" '"@nuxt/image":[[:space:]]*"\^?1\.11\.0"' "fearless-site-web patched Nuxt Image dependency"
  require_pattern "$package_json" '"@nuxtjs/sitemap":[[:space:]]*"7\.4\.3"' "fearless-site-web patched sitemap dependency"
  require_pattern "$package_json" '"nuxt-schema-org":[[:space:]]*"5\.0\.6"' "fearless-site-web patched schema-org dependency"
  require_pattern "$package_json" '"@unhead/vue":[[:space:]]*"\^?2\.1\.15"' "fearless-site-web patched Unhead Vue dependency"
  require_pattern "$package_json" '"unhead":[[:space:]]*"\^?2\.1\.15"' "fearless-site-web patched Unhead dependency"
  require_pattern "$package_json" '"zod":[[:space:]]*"\^?3\.25\.76"' "fearless-site-web schema validation dependency"
  require_pattern "$package_json" '"@nuxtjs/mdc":[[:space:]]*"0\.17\.2"' "fearless-site-web patched MDC resolution"
  require_pattern "$package_json" '"h3":[[:space:]]*"1\.15\.11"' "fearless-site-web patched H3 resolution"
  require_pattern "$package_json" '"node-forge":[[:space:]]*"1\.4\.0"' "fearless-site-web patched node-forge resolution"
  require_pattern "$package_json" '"rollup":[[:space:]]*"4\.62\.2"' "fearless-site-web patched Rollup resolution"
  require_pattern "$package_json" '"tar":[[:space:]]*"7\.5\.19"' "fearless-site-web patched tar resolution"
  require_pattern "$package_json" '"vite":[[:space:]]*"6\.4\.3"' "fearless-site-web patched Vite resolution"
  require_pattern "$package_json" '"ws":[[:space:]]*"8\.21\.0"' "fearless-site-web patched WebSocket resolution"
  require_pattern "$package_json" '"picomatch@npm:\^4\.0\.4":[[:space:]]*"npm:4\.0\.5"' "fearless-site-web patched picomatch resolution"
  require_pattern "$yarn_lock" 'resolution: "@nuxt/image@npm:1\.11\.0"' "fearless-site-web locked Nuxt Image remediation"
  require_pattern "$yarn_lock" 'resolution: "@nuxtjs/mdc@npm:0\.17\.2"' "fearless-site-web locked MDC remediation"
  require_pattern "$yarn_lock" 'resolution: "nuxt-schema-org@npm:5\.0\.6"' "fearless-site-web locked schema-org remediation"
  require_pattern "$yarn_lock" 'resolution: "vite@npm:6\.4\.3"' "fearless-site-web locked Vite remediation"
  require_pattern "$yarn_lock" 'resolution: "ws@npm:8\.21\.0"' "fearless-site-web locked WebSocket remediation"

  require_pattern "$association_verifier" 'MAX_ASSOCIATION_BYTES[[:space:]]*=[[:space:]]*64[[:space:]]*\*[[:space:]]*1024' "fearless-site-web app-association 64 KiB limit"
  require_pattern "$association_verifier" 'actual\.length[[:space:]]*===[[:space:]]*sortedExpected\.length' "fearless-site-web app-association strict unknown-key rejection"
  require_pattern "$association_verifier" 'assertExactKeys\(statement' "fearless-site-web Android app-association exact schema validation"
  require_pattern "$association_verifier" 'assertExactKeys\(rootValue' "fearless-site-web Apple app-association exact schema validation"
  require_pattern "$association_verifier" 'fs\.lstatSync\(file\)' "fearless-site-web app-association non-following source metadata check"
  require_pattern "$association_verifier" '!stat\.isSymbolicLink\(\)' "fearless-site-web app-association source symlink rejection"
  require_pattern "$association_verifier" 'stat\.size[[:space:]]*<=[[:space:]]*MAX_ASSOCIATION_BYTES' "fearless-site-web app-association source size bound"
  require_pattern "$association_verifier" 'byteLength[[:space:]]*>[[:space:]]*MAX_ASSOCIATION_BYTES' "fearless-site-web app-association streamed live size bound"
  require_pattern "$association_verifier" 'stableJson\(liveValue\)[[:space:]]*!==[[:space:]]*stableJson\(sourceValue\)' "fearless-site-web app-association exact source/live equality rejection"
  require_pattern "$association_verifier" "url\\.protocol[[:space:]]*===[[:space:]]*'https:'" "fearless-site-web app-association HTTPS live-base policy"
  require_pattern "$association_verifier" '!url\.username[[:space:]]*&&[[:space:]]*!url\.password' "fearless-site-web app-association credential-free live-base policy"
  require_pattern "$association_verifier" "url\\.pathname[[:space:]]*===[[:space:]]*'/'[[:space:]]*&&[[:space:]]*!url\\.search[[:space:]]*&&[[:space:]]*!url\\.hash" "fearless-site-web app-association canonical live-base policy"
  require_pattern "$association_verifier" 'response\.status[[:space:]]*!==[[:space:]]*200' "fearless-site-web app-association exact HTTP 200 live gate"
  require_pattern "$association_verifier" '\^application\\/.*json' "fearless-site-web app-association JSON content-type live gate"
  require_pattern "$association_verifier" "response\\.headers\\.get\\('x-content-type-options'\\).*toLowerCase\\(\\)[[:space:]]*!==[[:space:]]*'nosniff'" "fearless-site-web app-association nosniff live gate"
  require_pattern "$association_verifier" "redirect:[[:space:]]*'error'" "fearless-site-web app-association redirect rejection"
  require_pattern "$association_verifier" 'AbortSignal\.timeout\(' "fearless-site-web app-association live timeout"

  require_pattern "$association_test" 'node --import "\$FETCH_MOCK"' "fearless-site-web mocked-live adversarial harness invocation"
  require_pattern "$association_test" 'unexpected Android target field' "fearless-site-web Android unknown-field adversarial test"
  require_pattern "$association_test" 'unexpected Apple association root field' "fearless-site-web Apple unknown-field adversarial test"
  require_pattern "$association_test" 'symlinked association source' "fearless-site-web source symlink adversarial test"
  require_pattern "$association_test" 'oversized association source' "fearless-site-web source size adversarial test"
  require_pattern "$association_test" 'non-200 response' "fearless-site-web non-200 live adversarial test"
  require_pattern "$association_test" 'wrong live content type' "fearless-site-web content-type live adversarial test"
  require_pattern "$association_test" 'missing live no-sniff header' "fearless-site-web nosniff live adversarial test"
  require_pattern "$association_test" 'oversized live content length' "fearless-site-web content-length live adversarial test"
  require_pattern "$association_test" 'oversized streamed live body' "fearless-site-web streamed-body live adversarial test"
  require_pattern "$association_test" 'valid but stale live association' "fearless-site-web stale live-contract adversarial test"
  require_pattern "$association_test" 'stale live association reports header drift too' "fearless-site-web aggregate header-and-stale-content adversarial test"
  require_pattern "$association_test" 'bad headers do not hide stale live content' "fearless-site-web bad-header masking adversarial test"
  require_pattern "$association_test" 'insecure live base URL' "fearless-site-web insecure live-base adversarial test"
  require_pattern "$association_test" 'credential-bearing live base URL' "fearless-site-web credential-bearing live-base adversarial test"
  require_pattern "$association_test" 'path-bearing live base URL' "fearless-site-web path-bearing live-base adversarial test"
  require_pattern "$association_test" 'query-bearing live base URL' "fearless-site-web query-bearing live-base adversarial test"
  require_pattern "$association_test" 'fragment-bearing live base URL' "fearless-site-web fragment-bearing live-base adversarial test"
  require_pattern "$association_fetch_mock" 'globalThis\.fetch[[:space:]]*=' "fearless-site-web app-association mocked fetch implementation"
  require_pattern "$association_fetch_mock" "options\\.redirect[[:space:]]*!==[[:space:]]*'error'" "fearless-site-web app-association mocked redirect assertion"
  require_pattern "$association_fetch_mock" "options\\.headers\\?\\.accept[[:space:]]*!==[[:space:]]*'application/json'" "fearless-site-web app-association mocked Accept assertion"
  require_pattern "$association_fetch_mock" 'options\.signal[[:space:]]+instanceof[[:space:]]+AbortSignal' "fearless-site-web app-association mocked timeout assertion"

  require_pattern_between "$nuxt_config" "'/\\.well-known/assetlinks\\.json'" "'/\\.well-known/apple-app-site-association'" "'x-content-type-options':[[:space:]]*'nosniff'" "fearless-site-web Android association Nitro nosniff header"
  require_pattern_between "$nuxt_config" "'/\\.well-known/apple-app-site-association':" "'/\\.well-known/apple-app-site-association\\.json'" "'x-content-type-options':[[:space:]]*'nosniff'" "fearless-site-web extensionless Apple association Nitro nosniff header"
  require_pattern_between "$nuxt_config" "'/\\.well-known/apple-app-site-association\\.json'" '^[[:space:]]*app:' "'x-content-type-options':[[:space:]]*'nosniff'" "fearless-site-web JSON Apple association Nitro nosniff header"

  require_pattern "$association_live_gate" 'schedule:' "fearless-site-web scheduled app-association live gate trigger"
  require_pattern "$association_live_gate" 'ref:[[:space:]]*master' "fearless-site-web app-association live gate releasable-branch pin"
  require_pattern "$association_live_gate" 'verify-app-associations\.mjs --live-base-url https://fearlesswallet\.io' "fearless-site-web production app-association live comparison"

  require_pattern "$dependency_security" 'yarn install --immutable' "fearless-site-web dependency security immutable install"
  require_pattern "$dependency_security" 'yarn audit:dependencies' "fearless-site-web dependency security full audit"
  require_pattern "$dependency_security" 'yarn audit:dependencies:production' "fearless-site-web dependency security production audit"
  require_pattern "$dependency_security" 'yarn typecheck' "fearless-site-web dependency security typecheck"
  require_pattern "$dependency_security" 'yarn build' "fearless-site-web dependency security production build"
  require_pattern "$release" 'yarn audit:dependencies.*yarn audit:dependencies:production' "fearless-site-web release checklist full and production dependency audits"
  require_pattern "$release" 'yarn verify:release-content' "fearless-site-web release checklist release-content verifier"
  require_pattern "$release" 'yarn test:app-associations' "fearless-site-web release checklist app-association adversarial gate"
  require_pattern "$release" 'yarn verify:app-associations' "fearless-site-web release checklist app-association source gate"
  require_pattern "$release" 'yarn verify:app-associations:live' "fearless-site-web release checklist app-association live gate"
  require_pattern "$release" 'yarn typecheck' "fearless-site-web release checklist typecheck"
  require_pattern_i "$release" 'full and production dependency audits' "fearless-site-web release checklist dual-audit CI gate"
}

indexer_checks() {
  local repo_path="$1"
  local label="$2"
  local base_env="$3"
  local production_host="$4"
  local ci_file="$repo_path/.github/workflows/ci.yml"
  local package_json="$repo_path/package.json"
  local release="$repo_path/docs/release-checklist.md"
  local index_source="$repo_path/src/index.ts"
  local openapi_source="$repo_path/src/openapi.ts"
  local routes_source="$repo_path/src/api/routes.ts"
  local api_openapi_source="$repo_path/src/api/openapi.ts"
  local production_smoke="$repo_path/src/scripts/production-smoke.ts"
  local production_smoke_test="$repo_path/src/scripts/production-smoke-adversarial-test.ts"
  local indexer_service_source="$repo_path/src/indexerService.ts"
  local solana_identity_source="$repo_path/src/solanaIdentity.ts"
  local config_source="$repo_path/src/config.ts"
  local config_test="$repo_path/src/scripts/config-test.ts"
  local deployment_manifest_test="$repo_path/src/scripts/deployment-manifest-test.ts"
  local dockerfile="$repo_path/Dockerfile"
  local dockerignore="$repo_path/.dockerignore"
  local deployment_evidence="$repo_path/scripts/production-deployment-evidence.json"
  local deployment_evidence_audit="$repo_path/scripts/audit-deployment-evidence.sh"
  local deployment_evidence_test="$repo_path/scripts/test-deployment-evidence-audit.sh"
  local deployment_evidence_template="$repo_path/scripts/generate-deployment-evidence-template.sh"
  local deployment_evidence_template_test="$repo_path/scripts/test-deployment-evidence-template.sh"
  local docker_image
  local extra_blocker

  case "$production_host" in
    https://ti.soramitsu.io)
      docker_image="ton-indexer"
      extra_blocker="mainnet-registry-placeholders-remain"
      config_source="$repo_path/src/config/index.ts"
      ;;
    https://si.soramitsu.io)
      docker_image="solswap-indexer"
      extra_blocker="production-mainnet-identity-config-mismatch"
      ;;
    *)
      docker_image="indexer"
      extra_blocker="production-deployment-evidence-missing"
      ;;
  esac

  common_release_gate_checks "$repo_path" "$label" "$ci_file"

  require_file "$package_json" "$label package.json"
  require_file "$index_source" "$label index source"
  require_file "$production_smoke" "$label production smoke source"
  require_file "$production_smoke_test" "$label adversarial production-smoke source"
  require_file "$config_source" "$label strict runtime configuration"
  require_file "$config_test" "$label runtime configuration adversarial tests"
  require_file "$deployment_manifest_test" "$label deployment manifest adversarial tests"
  require_file "$dockerfile" "$label production Dockerfile"
  require_file "$dockerignore" "$label Docker context exclusions"
  require_file "$deployment_evidence" "$label production deployment evidence manifest"
  require_executable_file "$deployment_evidence_audit" "$label production deployment evidence audit"
  require_executable_file "$deployment_evidence_test" "$label production deployment evidence audit self-test"
  require_executable_file "$deployment_evidence_template" "$label production deployment evidence template generator"
  require_executable_file "$deployment_evidence_template_test" "$label production deployment evidence template self-test"

  require_pattern "$ci_file" 'npm ci' "$label clean install CI gate"
  require_pattern "$ci_file" 'npm audit --omit=dev' "$label production dependency audit"
  require_pattern "$ci_file" 'npm run test:deployment-evidence-template' "$label deployment evidence template self-test CI gate"
  require_pattern "$ci_file" 'npm run generate:deployment-evidence-template -- --output build/reports/production-deployment-evidence-template\.json' "$label deployment evidence template generation CI gate"
  require_pattern "$ci_file" 'npm run test:deployment-evidence-audit' "$label deployment evidence self-test CI gate"
  require_pattern "$ci_file" 'npm run audit:deployment-evidence' "$label deployment evidence audit CI gate"
  require_pattern "$ci_file" 'npm test' "$label test CI gate"
  require_pattern "$ci_file" 'npm run build' "$label build CI gate"
  require_pattern "$ci_file" 'node-version:[[:space:]]*22' "$label CI Node 22 runtime"
  require_pattern "$ci_file" "docker build -t $docker_image:ci \." "$label CI production Docker build gate"
  require_pattern "$ci_file" 'Development-only dependency leaked into runtime image' "$label CI production dependency-surface gate"

  require_pattern "$package_json" '"license":[[:space:]]*"Apache-2\.0"' "$label Apache-2.0 package metadata"
  require_pattern "$package_json" '"node":[[:space:]]*">=22"' "$label Node 22 package engine"
  require_pattern "$package_json" '"smoke:production"' "$label production smoke script"
  require_pattern "$package_json" '"generate:deployment-evidence-template"' "$label deployment evidence template generator script"
  require_pattern "$package_json" '"audit:deployment-evidence"' "$label deployment evidence audit script"
  require_pattern "$package_json" '"test:deployment-evidence-audit"' "$label deployment evidence self-test script"
  require_pattern "$package_json" '"test:deployment-evidence-template"' "$label deployment evidence template self-test script"
  require_pattern "$package_json" 'production-smoke-adversarial-test' "$label adversarial production-smoke test wired into npm test"
  require_pattern "$package_json" 'src/scripts/config-test\.ts' "$label runtime configuration adversarial tests wired into npm test"
  require_pattern "$package_json" 'src/scripts/deployment-manifest-test\.ts' "$label deployment manifest adversarial tests wired into npm test"
  require_pattern "$config_source" 'CANONICAL_INTEGER_PATTERN' "$label canonical-integer runtime configuration gate"
  require_pattern "$config_source" 'Number\.isSafeInteger' "$label safe-integer runtime configuration gate"
  require_pattern "$config_test" "PORT:[[:space:]]*'0?878[78]'" "$label non-canonical integer adversarial test"
  require_pattern "$config_test" "PORT:[[:space:]]*'-0'" "$label negative-zero integer adversarial test"
  require_pattern "$dockerfile" '^# syntax=docker/dockerfile:1@sha256:[0-9a-f]{64}$' "$label Dockerfile frontend digest pin"
  require_pattern "$dockerfile" '^FROM node:22-bookworm-slim@sha256:[0-9a-f]{64} AS deps$' "$label Docker Node 22 dependency digest pin"
  require_pattern "$dockerfile" '^FROM node:22-bookworm-slim@sha256:[0-9a-f]{64} AS runtime$' "$label Docker Node 22 runtime digest pin"
  require_pattern "$dockerfile" 'npm ci --ignore-scripts' "$label Docker immutable no-lifecycle install"
  reject_pattern "$dockerfile" '\|\|[[:space:]]*npm[[:space:]]+(install|i|ci)' "$label Docker mutable install fallback"
  require_pattern "$dockerfile" 'npm prune --omit=dev --ignore-scripts' "$label Docker production-only no-lifecycle prune"
  require_pattern "$dockerfile" 'USER node' "$label Docker non-root runtime"
  require_pattern "$dockerfile" 'HEALTHCHECK.*api/indexer/v1/health' "$label Docker health check"
  require_pattern "$deployment_manifest_test" 'Dockerfile must pin the Dockerfile frontend by digest' "$label Docker frontend digest adversarial test"
  require_pattern "$deployment_manifest_test" 'Dockerfile must pin the Node 22 dependency image by digest' "$label Docker dependency digest adversarial test"
  require_pattern "$deployment_manifest_test" 'Dockerfile must pin the Node 22 runtime image by digest' "$label Docker runtime digest adversarial test"
  require_pattern "$deployment_manifest_test" 'Node 22 runtime stage' "$label Docker runtime downgrade adversarial test"
  require_pattern "$deployment_manifest_test" 'mutable dependency install' "$label Docker mutable-fallback adversarial test"
  require_pattern "$deployment_manifest_test" 'prune dev dependencies without lifecycle scripts' "$label Docker lifecycle-prune adversarial test"
  require_pattern "$deployment_manifest_test" 'non-root node user' "$label Docker root-runtime adversarial test"
  require_pattern "$deployment_manifest_test" 'Development-only dependency leaked into runtime image' "$label Docker dev-dependency CI adversarial test"

  case "$production_host" in
    https://ti.soramitsu.io)
      require_pattern "$dockerfile" "body\.serviceId!='ti\.soramitsu\.io'|body\.serviceId!==\x27ti\.soramitsu\.io\x27" "$label Docker health strict service identity"
      require_pattern "$dockerfile" "body\.ecosystem!='ton'|body\.ecosystem!==\x27ton\x27" "$label Docker health strict ecosystem identity"
      require_pattern "$dockerfile" "body\.chainId!='ton:mainnet'|body\.chainId!==\x27ton:mainnet\x27" "$label Docker health strict chain identity"
      require_pattern "$dockerfile" "body\.network!='mainnet'|body\.network!==\x27mainnet\x27" "$label Docker health strict network identity"
      require_pattern "$deployment_manifest_test" 'Dockerfile healthcheck must validate strict TI identity marker' "$label Docker strict-health identity adversarial test"
      require_pattern "$deployment_manifest_test" "body\.chainId!='ton:mainnet'|body\.chainId!==\x27ton:mainnet\x27" "$label Docker strict-health mutation target"
      require_pattern "$config_source" 'RATE_LIMIT_ENABLED must be true when INDEXER_MODE=production' "$label production rate limiting fail-closed gate"
      require_pattern "$config_test" "RATE_LIMIT_ENABLED:[[:space:]]*disabled" "$label production rate limiting disabled-form adversarial test"
      require_pattern "$config_source" "healthCacheTtlMs:[[:space:]]*numberFromEnv\('HEALTH_CACHE_TTL_MS',[[:space:]]*1_000,[[:space:]]*\{[[:space:]]*min:[[:space:]]*0,[[:space:]]*max:[[:space:]]*5_000,[[:space:]]*integer:[[:space:]]*true[[:space:]]*\}\)" "$label bounded health-cache TTL configuration"
      require_pattern "$config_test" "HEALTH_CACHE_TTL_MS:[[:space:]]*'5001'" "$label over-limit health-cache TTL adversarial test"
      require_pattern "$indexer_service_source" 'rawLag >= -30 \? Math\.max\(0, rawLag\) : rawLag' "$label materially future checkpoint lag preservation"
      require_pattern "$production_smoke_test" 'indexerLagSec[[:space:]]*=[[:space:]]*-31' "$label future checkpoint lag adversarial test"
