    require_pattern "$production_smoke_test" 'zeroMasterSeqno' "$label production smoke zero TON master-seqno negative test"
    require_pattern "$production_smoke_test" 'staleLag' "$label production smoke stale TON indexer-lag negative test"
    require_pattern "$deployment_evidence_audit" 'mainnet registry contains placeholder values' "$label deployment evidence mainnet registry placeholder gate"
    require_pattern "$deployment_evidence_audit" 'mainnet registry missing required keys' "$label deployment evidence mainnet registry required-key gate"
    require_pattern "$deployment_evidence_audit" 'mainnet registry contains invalid TON address values' "$label deployment evidence mainnet registry address gate"
    require_pattern "$deployment_evidence_audit" "EXPECTED_SERVICE_ID = 'ti\.soramitsu\.io'" "$label deployment evidence exact TI service-id binding"
    require_pattern "$deployment_evidence_audit" 'lastMasterSeqno must be a non-negative integer' "$label deployment evidence TON health fingerprint gate"
    require_pattern "$deployment_evidence_template" "EXPECTED_SERVICE_ID = 'ti\.soramitsu\.io'" "$label deployment evidence template exact TI service-id binding"
    require_pattern "$deployment_evidence_template" 'TODO_LAST_MASTER_SEQNO' "$label deployment evidence template TON health placeholder"
    require_pattern "$deployment_evidence_test" 'cross-service SI manifest substitution' "$label deployment evidence cross-service SI substitution negative test"
    require_pattern "$deployment_evidence_template_test" 'cross-service SI manifest substitution' "$label deployment evidence template cross-service SI substitution negative test"
    require_pattern "$deployment_evidence_test" 'ready evidence with placeholder mainnet registry' "$label deployment evidence placeholder-registry negative test"
    require_pattern "$deployment_evidence_test" 'ready evidence with missing mainnet registry key' "$label deployment evidence missing-registry-key negative test"
    require_pattern "$deployment_evidence_test" 'ready evidence with invalid mainnet registry value' "$label deployment evidence invalid-registry-value negative test"
	    require_pattern "$deployment_evidence_test" 'blocked evidence keeps stale registry placeholder blocker' "$label deployment evidence stale-registry-blocker negative test"
	    require_pattern "$deployment_evidence_test" 'missing health last master seqno evidence' "$label deployment evidence missing TON health seqno negative test"
	    require_pattern "$deployment_evidence_test" 'bad health last master seqno evidence' "$label deployment evidence bad TON health seqno negative test"
	    require_pattern "$deployment_evidence_test" 'solana health field in ton evidence' "$label deployment evidence Solana health-field rejection test"
	    require_pattern "$deployment_evidence_audit" 'commit must not be a placeholder git commit' "$label deployment evidence placeholder commit gate"
    require_pattern "$deployment_evidence_audit" 'imageDigest must not be a placeholder image digest' "$label deployment evidence placeholder image digest gate"
    require_pattern "$deployment_evidence_test" 'placeholder commit evidence' "$label deployment evidence placeholder commit negative test"
    require_pattern "$deployment_evidence_test" 'placeholder image digest evidence' "$label deployment evidence placeholder image digest negative test"
  fi
  if [[ "$production_host" == "https://si.soramitsu.io" ]]; then
    require_file "$openapi_source" "$label OpenAPI source"
    require_file "$indexer_service_source" "$label Solana cluster health source"
    require_file "$solana_identity_source" "$label canonical Solana identity source"
    require_pattern "$solana_identity_source" "SOLANA_MAINNET_GENESIS_HASH = '5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d'" "$label exact Solana mainnet genesis constant"
    require_pattern_multiline "$index_source" "app\\.get\\('/api/indexer/v1/health'[^{]*\\{[\\s\\S]*\\.\\.\\.serviceIdentity" "$label health route service identity implementation"
    require_pattern "$index_source" "serviceId:[[:space:]]*'si\\.soramitsu\\.io'" "$label health identity service-id implementation"
    require_pattern "$index_source" "ecosystem:[[:space:]]*'solana'" "$label health identity ecosystem implementation"
    require_pattern "$index_source" "chainId:[[:space:]]*'solana:mainnet'" "$label health identity chain-id implementation"
    require_pattern "$openapi_source" 'HealthResponse' "$label OpenAPI health response schema"
    require_pattern_between "$openapi_source" 'HealthResponse' 'ServiceInfoResponse' 'serviceId:.*si\.soramitsu\.io' "$label OpenAPI health service-id schema"
    require_pattern_between "$openapi_source" 'HealthResponse' 'ServiceInfoResponse' 'chainId:.*solana:mainnet' "$label OpenAPI health chain-id schema"
    require_pattern_between "$openapi_source" 'HealthResponse' 'ServiceInfoResponse' "required:.*'genesisHash'.*'latestSlot'.*'syncedAt'" "$label OpenAPI Solana live health required fields"
    require_pattern_between "$openapi_source" 'HealthResponse' 'ServiceInfoResponse' 'genesisHash:.*SOLANA_MAINNET_GENESIS_HASH' "$label OpenAPI exact Solana mainnet genesis"
    require_pattern_between "$openapi_source" 'HealthResponse' 'ServiceInfoResponse' 'latestSlot:.*minimum:[[:space:]]*1' "$label OpenAPI positive Solana latest slot"
    require_pattern "$indexer_service_source" 'getGenesisHash' "$label live Solana genesis RPC read"
    require_pattern "$indexer_service_source" "getSlot\('confirmed'\)" "$label confirmed Solana slot RPC read"
    require_pattern "$indexer_service_source" "genesisHash !== SOLANA_MAINNET_GENESIS_HASH" "$label live Solana mainnet genesis gate"
    require_pattern "$indexer_service_source" 'unexpected_solana_genesis_hash' "$label unexpected Solana genesis fail-closed error"
    require_pattern "$indexer_service_source" 'Number\.isSafeInteger\(latestSlot\).*latestSlot <= 0' "$label live Solana positive safe latest-slot gate"
    require_pattern "$indexer_service_source" 'invalid_solana_latest_slot' "$label invalid Solana latest-slot fail-closed error"
    require_pattern "$indexer_service_source" 'syncedAt:[[:space:]]*Math\.floor\(Date\.now\(\) / 1000\)' "$label live Solana health observation timestamp"
    require_pattern "$index_source" 'await service\.getClusterHealth' "$label public health route live Solana cluster read"
    require_pattern "$dockerfile" "body\.genesisHash!='5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d'|body\.genesisHash!==\x275eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d\x27" "$label Docker health exact Solana mainnet genesis"
    require_pattern "$dockerfile" 'Number\.isSafeInteger\(body\.latestSlot\).*body\.latestSlot<=0' "$label Docker health positive safe Solana latest slot"
    require_pattern "$dockerfile" 'Number\.isSafeInteger\(body\.syncedAt\)' "$label Docker health integer Solana sync timestamp"
    require_pattern "$dockerfile" 'age < -30.*age > 120' "$label Docker health Solana sync freshness window"
    require_pattern "$deployment_manifest_test" "body\.genesisHash!='5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d'|body\.genesisHash!==\x275eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d\x27" "$label Docker exact-genesis mutation target"
    require_pattern "$deployment_manifest_test" 'age > 120' "$label Docker stale-health mutation target"
    require_pattern "$production_smoke" 'health serviceId must be si\.soramitsu\.io' "$label production smoke health service-id gate"
    require_pattern "$production_smoke" 'health ecosystem must be solana' "$label production smoke health ecosystem gate"
    require_pattern "$production_smoke" 'health chainId must be solana:mainnet' "$label production smoke health chain-id gate"
    require_pattern "$production_smoke" 'health genesisHash must be' "$label production smoke exact Solana genesis gate"
    require_pattern "$production_smoke" 'health latestSlot must be a positive safe integer' "$label production smoke positive safe Solana latest-slot gate"
    require_pattern "$production_smoke" 'health syncedAt must be within' "$label production smoke Solana health freshness gate"
    require_pattern "$production_smoke" 'Production health must expose ok=true, serviceId=si\.soramitsu\.io' "$label production smoke old-health deployment diagnostic"
    require_pattern "$production_smoke" 'Production service-info must expose schemaVersion=1, serviceId=si\.soramitsu\.io' "$label production smoke service-info deployment diagnostic"
    require_pattern "$production_smoke" 'Production OpenAPI must expose title Solswap Indexer API' "$label production smoke OpenAPI deployment diagnostic"
    require_pattern "$production_smoke" 'SI production routing points at a TON indexer contract' "$label production smoke wrong-indexer diagnostic"
    require_pattern "$production_smoke" 'deploy the current solswap-indexer image to si\.soramitsu\.io' "$label production smoke stale-deployment diagnostic"
    require_pattern "$production_smoke_test" 'wrongHealthIdentity' "$label production smoke wrong-health-identity negative test"
    require_pattern "$production_smoke_test" 'health serviceId must be si\\\.soramitsu\\\.io' "$label production smoke health service-id negative test"
	    require_pattern "$production_smoke_test" 'oldDeployedHealth' "$label production smoke old-health deployment negative test"
	    require_pattern "$production_smoke_test" 'SI production routing does not expose the Solswap health contract' "$label production smoke generic-health negative test"
	    require_pattern "$production_smoke_test" 'deploy the current solswap-indexer image' "$label production smoke missing-service-info negative test"
	    require_pattern "$production_smoke_test" 'service-info schemaVersion must be 1; received <missing>' "$label production smoke service-info deployment negative test"
	    require_pattern "$production_smoke_test" 'service-info serviceId must be si.*received ti.*Deploy the current solswap-indexer image' "$label production smoke wrong-service-info-identity negative test"
	    require_pattern "$production_smoke_test" 'service-info returned HTTP 503.*Body preview: deploy in progress' "$label production smoke service-info HTTP body-preview negative test"
	    require_pattern "$production_smoke_test" 'openapi.*returned invalid JSON.*Body preview' "$label production smoke OpenAPI invalid-JSON body-preview negative test"
	    require_pattern "$production_smoke_test" 'OpenAPI is missing .*api.*indexer.*v1.*tokens.*metadata.*Deploy the current solswap-indexer image' "$label production smoke OpenAPI missing-path deployment negative test"
	    require_pattern "$production_smoke_test" 'OpenAPI title must be Solswap Indexer API; received <missing>' "$label production smoke OpenAPI missing-title deployment negative test"
	    require_pattern "$production_smoke_test" 'OpenAPI title must be Solswap Indexer API; received TONSWAP Indexer API' "$label production smoke OpenAPI wrong-title deployment negative test"
	    require_pattern "$production_smoke_test" 'wrongGenesis' "$label production smoke wrong Solana genesis negative test"
	    require_pattern "$production_smoke_test" 'invalidLatestSlot' "$label production smoke invalid Solana latest-slot negative test"
	    require_pattern "$production_smoke_test" 'staleHealth' "$label production smoke stale Solana health negative test"
	    require_pattern "$production_smoke_test" 'futureHealth' "$label production smoke future Solana health negative test"
	    require_pattern "$deployment_evidence_test" 'missing health ok evidence' "$label deployment evidence missing Solana health ok negative test"
	    require_pattern "$deployment_evidence_test" 'ton health field in solana evidence' "$label deployment evidence TON health-field rejection test"
	    require_pattern "$deployment_evidence_audit" 'genesisHash must be' "$label deployment evidence exact Solana mainnet genesis gate"
	    require_pattern "$deployment_evidence_audit" 'latestSlot must be a positive safe integer' "$label deployment evidence positive safe Solana latest-slot gate"
	    require_pattern "$deployment_evidence_audit" 'syncedAt must be a positive Unix timestamp in seconds' "$label deployment evidence integer Solana sync timestamp gate"
	    require_pattern "$deployment_evidence_audit" 'healthInfo\.syncedAt must be within 120 seconds before smokePassedAt' "$label deployment evidence stale Solana sync gate"
    require_pattern "$deployment_evidence_audit" 'healthInfo\.syncedAt must not be more than 30 seconds after smokePassedAt' "$label deployment evidence future Solana sync gate"
    require_pattern "$deployment_evidence_audit" "EXPECTED_SERVICE_ID = 'si\.soramitsu\.io'" "$label deployment evidence exact SI service-id binding"
    require_pattern "$deployment_evidence_audit" 'ok must be true' "$label deployment evidence Solana health fingerprint gate"
	    require_pattern "$deployment_evidence_test" 'wrong health genesis evidence' "$label deployment evidence wrong Solana genesis negative test"
	    require_pattern "$deployment_evidence_test" 'invalid health latest slot evidence' "$label deployment evidence invalid Solana latest-slot negative test"
	    require_pattern "$deployment_evidence_test" 'unsafe health latest slot evidence' "$label deployment evidence unsafe Solana latest-slot negative test"
	    require_pattern "$deployment_evidence_test" 'string health sync evidence' "$label deployment evidence string Solana sync timestamp negative test"
	    require_pattern "$deployment_evidence_test" 'stale health sync evidence' "$label deployment evidence stale Solana sync timestamp negative test"
	    require_pattern "$deployment_evidence_test" 'future health sync evidence' "$label deployment evidence future Solana sync timestamp negative test"
	    require_pattern "$deployment_evidence_test" 'si-release-health-old-boundary' "$label deployment evidence lower Solana sync freshness boundary test"
	    require_pattern "$deployment_evidence_test" 'si-release-health-future-boundary' "$label deployment evidence upper Solana sync freshness boundary test"
	    require_pattern "$deployment_evidence_template" "SOLANA_MAINNET_GENESIS_HASH = '5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d'|5eykt4UsFv8P8NJdTREpY1vzqKqZKvdpKuc147dw2N9d" "$label deployment evidence template exact Solana mainnet genesis"
	    require_pattern "$deployment_evidence_template" 'TODO_POSITIVE_LATEST_SLOT' "$label deployment evidence template Solana latest-slot placeholder"
    require_pattern "$deployment_evidence_template" 'TODO_UNIX_TIMESTAMP_SECONDS' "$label deployment evidence template Solana sync timestamp placeholder"
    require_pattern "$deployment_evidence_template" "EXPECTED_SERVICE_ID = 'si\.soramitsu\.io'" "$label deployment evidence template exact SI service-id binding"
    require_pattern "$deployment_evidence_test" 'cross-service TI manifest substitution' "$label deployment evidence cross-service TI substitution negative test"
    require_pattern "$deployment_evidence_template_test" 'cross-service TI manifest substitution' "$label deployment evidence template cross-service TI substitution negative test"
	    require_pattern "$deployment_evidence_audit" 'commit must not be a placeholder git commit' "$label deployment evidence placeholder commit gate"
    require_pattern "$deployment_evidence_audit" 'imageDigest must not be a placeholder image digest' "$label deployment evidence placeholder image digest gate"
    require_pattern "$deployment_evidence_test" 'placeholder commit evidence' "$label deployment evidence placeholder commit negative test"
    require_pattern "$deployment_evidence_test" 'placeholder image digest evidence' "$label deployment evidence placeholder image digest negative test"
  fi

  require_pattern "$release" 'npm audit --omit=dev' "$label release checklist production dependency audit"
  require_pattern "$release" 'test:deployment-evidence-template' "$label release checklist deployment evidence template self-test"
  require_pattern "$release" 'generate:deployment-evidence-template -- --output' "$label release checklist deployment evidence template generator"
  require_pattern "$release" 'test:deployment-evidence-audit' "$label release checklist deployment evidence self-test"
  require_pattern "$release" 'audit:deployment-evidence -- --require-ready' "$label release checklist deployment evidence ready audit"
  require_pattern "$release" 'scripts/production-deployment-evidence\.json' "$label release checklist deployment evidence manifest"
  require_pattern "$release" 'DEPLOYMENT_EVIDENCE_EXPECTED_COMMIT' "$label release checklist expected release commit override"
  require_pattern "$release" 'releaseEnabled: true' "$label release checklist deployment release-enabled requirement"
  require_pattern "$release" "$base_env=$production_host npm run smoke:production" "$label release checklist live production smoke"
  require_pattern_i "$release" 'OpenAPI smoke' "$label release checklist OpenAPI smoke"
}

polkaswap_indexer_checks() {
  local repo_path="$1"
  local label="../polkaswap-indexer"
  local ci_file="$repo_path/.github/workflows/ci.yml"
  local package_json="$repo_path/package.json"
  local env_example="$repo_path/.env.example"
  local readme="$repo_path/README.md"
  local schema_source="$repo_path/src/graphql/schema.ts"
  local resolver_source="$repo_path/src/graphql/resolvers.ts"
  local sora_identity_source="$repo_path/src/soraIdentity.ts"
  local identity_preflight_source="$repo_path/src/worker/identityPreflight.ts"
  local worker_entrypoint="$repo_path/src/worker/index.ts"
  local chain_source="$repo_path/src/worker/chain.ts"
  local production_smoke="$repo_path/src/scripts/production-smoke.ts"
  local production_smoke_test="$repo_path/tests/production-smoke.spec.ts"
  local identity_preflight_test="$repo_path/tests/identity-preflight.spec.ts"
  local chain_identity_test="$repo_path/tests/chain-identity.spec.ts"
  local chain_connection_timeout_test="$repo_path/tests/chain-connection-timeout.spec.ts"
  local finalized_identity_test="$repo_path/tests/finalized-identity.spec.ts"
  local archive_consistency_test="$repo_path/tests/archive-consistency.spec.ts"
  local worker_health_source="$repo_path/src/scripts/worker-health.ts"
  local worker_health_test="$repo_path/tests/worker-health.spec.ts"
  local health_identity_test="$repo_path/tests/health-identity.spec.ts"
  local schema_test="$repo_path/tests/schema.spec.ts"
  local config_source="$repo_path/src/config.ts"
  local config_test="$repo_path/tests/config.spec.ts"
  local dockerfile="$repo_path/Dockerfile"
  local production_compose="$repo_path/docker-compose.production.yml"
  local deployment_manifest_audit="$repo_path/scripts/audit-deployment-manifest.sh"
  local deployment_manifest_test="$repo_path/scripts/test-deployment-manifest.sh"
  local release_checklist="$repo_path/docs/release-checklist.md"
  local deployment_evidence="$repo_path/scripts/production-deployment-evidence.json"
  local deployment_audit="$repo_path/scripts/audit-deployment-evidence.sh"
  local deployment_audit_test="$repo_path/scripts/test-deployment-evidence-audit.sh"
  local deployment_template="$repo_path/scripts/generate-deployment-evidence-template.sh"
  local deployment_template_test="$repo_path/scripts/test-deployment-evidence-template.sh"

  common_release_gate_checks "$repo_path" "$label" "$ci_file"

  require_file "$ci_file" "$label CI workflow"
  require_file "$package_json" "$label package.json"
  require_file "$env_example" "$label environment example"
  require_file "$readme" "$label README"
  require_file "$schema_source" "$label GraphQL schema source"
  require_file "$resolver_source" "$label GraphQL resolver source"
  require_file "$sora_identity_source" "$label canonical SORA identity source"
  require_file "$identity_preflight_source" "$label database-free SORA identity preflight"
  require_file "$worker_entrypoint" "$label worker entrypoint"
  require_file "$chain_source" "$label chain identity and block ingestion source"
  require_file "$production_smoke" "$label production smoke source"
  require_file "$production_smoke_test" "$label production smoke adversarial tests"
  require_file "$identity_preflight_test" "$label identity preflight adversarial tests"
  require_file "$chain_identity_test" "$label chain identity adversarial tests"
  require_file "$chain_connection_timeout_test" "$label chain connection timeout adversarial tests"
  require_file "$finalized_identity_test" "$label finalized-head identity adversarial tests"
  require_file "$archive_consistency_test" "$label primary/archive raw-payload agreement tests"
  require_file "$worker_health_source" "$label standalone compiled worker health source"
  require_file "$worker_health_test" "$label standalone worker health adversarial tests"
  require_file "$health_identity_test" "$label GraphQL health identity adversarial tests"
  require_file "$schema_test" "$label health schema tests"
  require_file "$config_source" "$label strict runtime configuration"
  require_file "$config_test" "$label runtime configuration adversarial tests"
  require_file "$dockerfile" "$label production Dockerfile"
  require_file "$production_compose" "$label production Compose manifest"
  require_executable_file "$deployment_manifest_audit" "$label deployment manifest audit"
  require_executable_file "$deployment_manifest_test" "$label deployment manifest adversarial self-test"
  require_file "$release_checklist" "$label release checklist"
  require_file "$deployment_evidence" "$label production deployment evidence manifest"
  require_executable_file "$deployment_audit" "$label deployment evidence audit"
  require_executable_file "$deployment_audit_test" "$label deployment evidence audit self-test"
  require_executable_file "$deployment_template" "$label deployment evidence template generator"
  require_executable_file "$deployment_template_test" "$label deployment evidence template self-test"

  require_pattern "$ci_file" 'branches:' "$label CI branch triggers"
  require_pattern "$ci_file" 'develop' "$label CI develop target"
  require_pattern "$ci_file" 'master' "$label CI master target"
  require_pattern "$ci_file" 'node-version:[[:space:]]*24' "$label CI Node 24 runtime"
  require_pattern "$ci_file" 'corepack enable' "$label CI Corepack setup"
  require_pattern "$ci_file" 'yarn install --immutable' "$label CI immutable Yarn install"
  require_pattern "$ci_file" 'yarn audit:dependencies:production' "$label CI production dependency audit"
  require_pattern "$ci_file" 'yarn test:deployment-evidence-template([[:space:]]|$)' "$label CI deployment evidence template self-test"
  require_pattern "$ci_file" 'yarn generate:deployment-evidence-template --output build/reports/production-deployment-evidence-template\.json' "$label CI deployment evidence template generation"
  require_pattern "$ci_file" 'yarn test:deployment-evidence-audit' "$label CI deployment evidence audit self-test"
  require_pattern "$ci_file" 'yarn audit:deployment-evidence' "$label CI deployment evidence audit"
  require_pattern "$ci_file" 'yarn test:production-smoke' "$label CI production-smoke contract tests"
  require_pattern "$ci_file" 'yarn test:deployment-manifest([[:space:]]|$)' "$label CI deployment manifest adversarial gate"
  require_pattern "$ci_file" 'docker build -t polkaswap-indexer:ci \.' "$label CI production Docker build gate"
  require_pattern "$ci_file" 'Development-only dependency leaked into runtime image' "$label CI production dependency-surface gate"
  require_pattern "$ci_file" 'yarn build' "$label CI build gate"
  require_pattern "$ci_file" 'yarn test' "$label CI full test gate"

  require_pattern "$package_json" '"smoke:production"' "$label production smoke script"
  require_pattern "$package_json" '"test:production-smoke"' "$label production smoke test script"
  require_pattern "$package_json" '"audit:deployment-evidence"' "$label deployment evidence package audit script"
  require_pattern "$package_json" '"generate:deployment-evidence-template"' "$label deployment evidence template package script"
  require_pattern "$package_json" '"test:deployment-evidence-audit"' "$label deployment evidence audit package self-test script"
  require_pattern "$package_json" '"test:deployment-evidence-template"' "$label deployment evidence template package self-test script"
  require_pattern "$package_json" '"test:deployment-manifest"' "$label deployment manifest package self-test script"
  require_pattern "$package_json" '"license":[[:space:]]*"Apache-2\.0"' "$label Apache-2.0 package metadata"
  require_pattern "$package_json" '"node":[[:space:]]*">=24"' "$label Node 24 package engine"
  require_pattern "$package_json" '"ws":[[:space:]]*"8\.21\.0"' "$label ws security update"
  require_pattern "$env_example" 'POLKASWAP_INDEXER_BASE_URL=https://pi\.soramitsu\.io/graphql' "$label canonical PI environment example"
  require_pattern "$readme" 'POLKASWAP_INDEXER_BASE_URL=https://pi\.soramitsu\.io/graphql yarn smoke:production' "$label README live smoke command"
  require_pattern "$readme" 'serviceId=pi\.soramitsu\.io' "$label README service identity contract"
  require_pattern "$readme" 'ecosystem=sora2' "$label README ecosystem contract"
  require_pattern "$readme" 'chainId=sora:mainnet' "$label README chain identity contract"
  require_pattern "$readme" 'scripts/production-deployment-evidence\.json' "$label README deployment evidence manifest"
  require_pattern "$readme" 'yarn generate:deployment-evidence-template --output build/reports/production-deployment-evidence-template\.json' "$label README deployment evidence template generation"
  require_pattern "$readme" 'yarn audit:deployment-evidence --require-ready' "$label README deployment evidence ready audit"
  require_pattern "$readme" 'TON or Solana indexer contracts' "$label README wrong-indexer routing warning"
  require_pattern "$readme" 'DATABASE_URL.*required|rejects the development database fallback' "$label README fail-closed production database configuration"
  require_pattern "$config_source" 'DATABASE_URL is required when NODE_ENV=production' "$label production database fail-closed gate"
  require_pattern "$config_source" 'NODE_ENV must be development, test, or production' "$label NODE_ENV allow-list gate"
  require_pattern "$config_source" 'PORT.*65_535' "$label bounded strict port gate"
  require_pattern "$config_source" 'GRAPHQL_PATH must be an absolute URL path' "$label GraphQL path validation gate"
  require_pattern "$config_source" 'must not contain URL credentials' "$label SORA endpoint credential rejection"
  require_pattern "$config_source" 'must use TLS outside localhost' "$label SORA endpoint TLS gate"
  require_pattern "$config_source" 'readSoraArchiveWsEndpoint\(requireConfigured = false\)' "$label explicit production archive endpoint reader"
  require_pattern "$config_source" 'SORA_ARCHIVE_WS_ENDPOINT is required for the production worker' "$label production archive endpoint fail-closed gate"
  require_pattern "$config_source" 'assertIndependentSoraRpcEndpoints' "$label primary/archive host independence validator"
  require_pattern "$config_source" 'primaryUrl\.hostname\.toLowerCase\(\) === archiveUrl\.hostname\.toLowerCase\(\)' "$label case-insensitive primary/archive host equality rejection"
  require_pattern "$config_source" 'must use different reviewed hosts' "$label distinct reviewed primary/archive host gate"
  require_pattern "$config_test" 'missing production database configuration' "$label production database adversarial test"
  require_pattern "$config_test" 'non-canonical|04350' "$label non-canonical integer adversarial test"
  require_pattern "$config_test" '0x|4e3' "$label ambiguous numeric adversarial test"
  require_pattern "$config_test" 'GRAPHQL_PATH.*%2e%2e|/%2e%2e/graphql' "$label encoded path traversal adversarial test"
  require_pattern "$config_test" 'ws://sora\.example\.invalid' "$label insecure remote SORA endpoint adversarial test"
  require_pattern "$config_test" 'requires it for production worker startup' "$label missing production archive endpoint adversarial test"
  require_pattern "$config_test" 'must use different reviewed hosts' "$label same primary/archive host adversarial test"

  require_pattern "$sora_identity_source" '0x7e4e32d0feafd4f9c9414b0be86373f9a1efa904809b683453a9af6856d38ad5' "$label exact SORA mainnet genesis identity"
  require_pattern "$sora_identity_source" 'block:[[:space:]]*26_872_383' "$label audited legacy identity anchor height"
  require_pattern "$sora_identity_source" '0x28dd415867e637e5c70056a564cfa4e81f0f3df3a18d1132ccc61fe5025c762c' "$label audited legacy identity anchor hash"
  require_pattern "$sora_identity_source" 'timestamp:[[:space:]]*1_783_716_432' "$label audited legacy identity anchor timestamp"
  require_pattern "$sora_identity_source" 'isCanonicalSubstrateHash' "$label canonical lowercase 32-byte SORA hash parser"
  require_pattern "$sora_identity_source" 'isNonzeroCanonicalSubstrateHash' "$label nonzero SORA hash parser"
  require_pattern "$sora_identity_source" 'SORA_MAX_BLOCK_NUMBER = 0xffff_ffff' "$label bounded SORA u32 block-number contract"
  require_pattern "$sora_identity_source" 'hasExactKeys' "$label stored identity exact-key parser"
  require_pattern "$sora_identity_source" 'parseStoredSoraChainIdentity' "$label stored immutable chain identity parser"
  require_pattern "$sora_identity_source" 'parseStoredSoraChainState' "$label stored chain checkpoint parser"
  require_pattern "$sora_identity_source" 'record\.migration !== .fresh-database. && record\.migration !== .legacy-production-anchor-v1.' "$label stored identity migration allow-list"
