  require_pattern "$chain_source" 'requireReviewedMainnetAnchor\(this\.api, .primary SORA endpoint., true\)' "$label primary endpoint reviewed anchor hash/timestamp proof"
  require_pattern "$chain_source" 'for \(const name of ALL_INDEXER_COLLECTIONS\)' "$label all-collection nonempty database guard"
