  require_pattern "$chain_connection_timeout_test" 'bounds the primary API connection and disconnects a completion that arrives after timeout' "$label primary connection deadline and late cleanup test"
  require_pattern "$chain_connection_timeout_test" 'bounds the archive API connection and disconnects a completion that arrives after timeout' "$label archive connection deadline and late cleanup test"
  require_pattern "$chain_connection_timeout_test" 'bounds all never-resolving chain disconnects and leaves no deadline timers behind' "$label chain cleanup deadline test"
  require_pattern "$finalized_identity_test" 'does not let a subscription .* poison pending finalized state' "$label finalized subscription poisoning adversarial table"
  require_pattern "$finalized_identity_test" 'does not let a polled .* poison pending finalized state' "$label finalized polling poisoning adversarial table"
  require_pattern "$finalized_identity_test" 'requested/header hash mismatch' "$label finalized polling requested-header hash mismatch test"
  require_pattern "$archive_consistency_test" 'accepts independently decoded payloads only when block SCALE, events SCALE, and timestamp agree' "$label dual-RPC exact raw payload positive control"
  require_pattern "$archive_consistency_test" 'rejects raw timestamp millisecond divergence even within the same persisted second' "$label dual-RPC same-second raw timestamp divergence test"
  require_pattern "$archive_consistency_test" 'BLOCK_TIMESTAMP \* 1_000 \+ 999' "$label dual-RPC 999-millisecond divergence fixture"
