  require_pattern_multiline "$worker_health_source" 'identity\.verificationBlock !== SORA_LEGACY_IDENTITY_ANCHOR\.block[\s\S]*identity\.verificationBlockHash !== SORA_LEGACY_IDENTITY_ANCHOR\.hash[\s\S]*identity\.verificationBlockTimestamp !== SORA_LEGACY_IDENTITY_ANCHOR\.timestamp' "$label worker health fixed audited identity anchor"
