  require_pattern "$deployment_audit_test" 'valid[-_ ]leap[-_ ]day' "$label deployment evidence valid leap-day control"
  require_pattern "$deployment_audit_test" 'wrong health identity' "$label deployment evidence wrong-health negative test"
  require_pattern "$deployment_audit_test" 'wrong but well-formed genesis hash' "$label deployment evidence wrong-genesis negative test"
  require_pattern "$deployment_audit_test" 'zero indexed block' "$label deployment evidence zero indexed-block negative test"
  require_pattern "$deployment_audit_test" 'unsafe indexed block' "$label deployment evidence unsafe indexed-block negative test"
  require_pattern "$deployment_audit_test" 'uppercase indexed block hash' "$label deployment evidence uppercase indexed-block-hash negative test"
  require_pattern "$deployment_audit_test" 'zero indexed block hash' "$label deployment evidence zero indexed-block-hash negative test"
  require_pattern "$deployment_audit_test" 'millisecond indexed timestamp' "$label deployment evidence millisecond timestamp negative test"
  require_pattern "$deployment_audit_test" 'indexed timestamp one second stale' "$label deployment evidence stale checkpoint negative test"
  require_pattern "$deployment_audit_test" 'indexed timestamp one second too far ahead' "$label deployment evidence future checkpoint negative test"
  # The reviewed matrix has 90 literal call sites. Its seven exact loops add 21
  # executions, yielding 111 runtime negative assertions without double-counting
  # the pre-existing cases as a separate suite.
  require_min_pattern_count "$deployment_audit_test" '^[[:space:]]*expect_failure[[:space:]]+"' 90 "$label deployment evidence 90 declared negative-test call sites"
  require_pattern "$deployment_audit_test" 'for container_value in .*null.*\[\].*invalid' "$label deployment evidence three invalid RPC-control containers"
  require_pattern "$deployment_audit_test" 'for field in primaryEndpoint archiveEndpoint' "$label deployment evidence both RPC endpoint omission mutations"
  require_pattern "$deployment_audit_test" 'for field in primaryNodeControl archiveNodeControl distinctHosts exactIdentityPreflight rawPayloadAgreement' "$label deployment evidence all five fixed RPC control omission mutations"
  require_pattern "$deployment_audit_test" 'for field in distinctHosts exactIdentityPreflight' "$label deployment evidence both boolean RPC control mutation groups"
  require_pattern "$deployment_audit_test" 'for bad_value in .*false.*true.*1' "$label deployment evidence three invalid boolean RPC control values"
  require_pattern "$deployment_audit_test" 'for public_host in ws\.mof\.sora\.org mof2\.sora\.org mof3\.sora\.org' "$label deployment evidence all public convenience RPC host mutations"
  require_pattern "$deployment_audit_test" "for bad_scheme in 'ws://sora-primary-rpc\.prod\.internal/ws' 'https://sora-primary-rpc\.prod\.internal/ws' 'http://sora-primary-rpc\.prod\.internal/ws'" "$label deployment evidence three non-WSS RPC scheme mutations"
  require_pattern "$deployment_audit_test" 'for placeholder_url in' "$label deployment evidence placeholder RPC hostname mutation group"
  require_pattern "$deployment_audit_test" "'wss://TODO_PRIMARY_RPC\.prod\.internal/ws'" "$label deployment evidence TODO RPC hostname mutation"
  require_pattern "$deployment_audit_test" "'wss://primary-rpc\.example\.com/ws'" "$label deployment evidence example RPC hostname mutation"
  require_pattern "$deployment_audit_test" "'wss://192\.0\.2\.10/ws'" "$label deployment evidence documentation-address RPC mutation"
  require_pattern "$deployment_audit_test" "'wss://localhost/ws'" "$label deployment evidence localhost RPC mutation"
  require_pattern "$deployment_audit_test" "'wss://test/ws'" "$label deployment evidence test-host RPC mutation"
  require_pattern "$deployment_audit_test" "'wss://invalid/ws'" "$label deployment evidence invalid-host RPC mutation"
  require_pattern "$deployment_audit_test" 'same RPC host behind different ports and paths' "$label deployment evidence same-host alternate-port/path mutation"
  require_pattern "$deployment_audit_test" 'incomplete raw RPC payload agreement' "$label deployment evidence incomplete raw-payload agreement mutation"
  require_pattern "$deployment_audit_test" 'secret token in RPC endpoint' "$label deployment evidence secret-bearing RPC endpoint mutation"
  require_pattern "$deployment_audit_test" 'secret-like deployment evidence key' "$label deployment evidence secret-like negative test"
  require_pattern "$deployment_audit_test" 'placeholder operator evidence' "$label deployment evidence placeholder operator negative test"
  require_pattern "$deployment_audit_test" 'dummy operator evidence' "$label deployment evidence dummy operator negative test"
  require_pattern "$deployment_audit_test" 'multiline operator evidence' "$label deployment evidence operator single-line negative test"
  require_pattern "$deployment_audit_test" 'secret-like operator evidence' "$label deployment evidence operator secret-like negative test"
  require_pattern "$deployment_audit_test" 'secret-like deployment evidence value' "$label deployment evidence secret-like value negative test"
  require_pattern "$deployment_audit_test" 'missing deployment evidence template command' "$label deployment evidence missing template command negative test"
  require_pattern "$deployment_audit_test" 'missing TLS edge controls attestation' "$label deployment evidence missing TLS-edge attestation negative test"
  require_pattern "$deployment_audit_test" 'TLS edge preserves spoofable forwarding headers' "$label deployment evidence forwarded-header preservation negative test"
  require_pattern "$deployment_audit_test" 'permissive TLS edge HTTP rate limit' "$label deployment evidence permissive TLS-edge HTTP negative test"
  require_pattern "$deployment_audit_test" 'permissive TLS edge WebSocket connection limit' "$label deployment evidence permissive TLS-edge WebSocket negative test"
  require_pattern "$deployment_audit_test" 'unsupported TLS edge limit field' "$label deployment evidence unsupported TLS-edge field negative test"
  require_pattern "$deployment_template" 'TODO_40_HEX_GIT_COMMIT' "$label deployment evidence template commit placeholder"
  require_pattern "$deployment_template" 'TODO_64_HEX_IMAGE_DIGEST' "$label deployment evidence template image digest placeholder"
  require_pattern "$deployment_template" 'TODO_UTC_SMOKE_TIMESTAMP_SECONDS' "$label deployment evidence template smoke timestamp placeholder"
  require_pattern "$deployment_template" 'TODO_POSITIVE_SAFE_INTEGER_INDEXED_BLOCK' "$label deployment evidence template indexed-block placeholder"
  require_pattern "$deployment_template" 'TODO_0X_64_LOWERCASE_HEX_INDEXED_BLOCK_HASH' "$label deployment evidence template indexed-block-hash placeholder"
  require_pattern "$deployment_template" 'TODO_UNIX_SECONDS_WITHIN_300_BEFORE_OR_30_AFTER_SMOKE' "$label deployment evidence template indexed-at placeholder"
  require_pattern "$deployment_template" 'live-production-smoke-failing' "$label deployment evidence template live-smoke blocker contract"
  require_pattern "$deployment_template" 'tlsEdgeControls:[[:space:]]*contract\.tlsEdgeControls' "$label deployment evidence template TLS-edge controls contract"
  require_pattern "$deployment_template" 'soraRpcControls:[[:space:]]*contract\.soraRpcControls' "$label deployment evidence template exact SORA RPC controls contract"
  require_pattern "$deployment_template" 'TODO_CANONICAL_WSS_LOCALLY_CONTROLLED_PRIMARY_RPC_ENDPOINT' "$label deployment evidence template controlled primary RPC placeholder"
  require_pattern "$deployment_template" 'TODO_CANONICAL_WSS_INDEPENDENT_ARCHIVE_RPC_ENDPOINT' "$label deployment evidence template independent archive RPC placeholder"
  require_pattern "$deployment_template" "primaryNodeControl:[[:space:]]*'locally-controlled-verifying-archive'" "$label deployment evidence template primary control role"
  require_pattern "$deployment_template" "archiveNodeControl:[[:space:]]*'independently-operated-verifying-archive'" "$label deployment evidence template archive control role"
  require_pattern "$deployment_template" 'distinctHosts:[[:space:]]*true' "$label deployment evidence template distinct RPC hosts"
  require_pattern "$deployment_template" 'exactIdentityPreflight:[[:space:]]*true' "$label deployment evidence template exact identity preflight"
  require_pattern "$deployment_template" "rawPayloadAgreement:[[:space:]]*'height-hash-scale-block-events-timestamp'" "$label deployment evidence template raw payload agreement"
  require_pattern "$deployment_template" 'must not be read from public deployment evidence manifest' "$label deployment evidence template secret-like manifest gate"
  require_pattern "$deployment_template" 'committed deployment evidence manifest must not contain prefilled deployment evidence' "$label deployment evidence template prefilled gate"
  require_pattern "$deployment_template_test" 'template cannot pass ready audit with TODO placeholders' "$label deployment evidence template ready-audit negative test"
  require_pattern "$deployment_template_test" 'secret-like manifest key' "$label deployment evidence template secret-like manifest negative test"
  require_pattern "$deployment_template_test" 'prefilled deployment evidence' "$label deployment evidence template prefilled negative test"
  require_pattern "$deployment_template_test" 'TLS edge evidence field required by generator' "$label deployment evidence template TLS-edge field negative test"
  require_pattern "$deployment_template_test" 'exact SORA mainnet genesis hash missing' "$label deployment evidence template exact-genesis test"
  require_pattern "$deployment_template_test" 'indexed block placeholder missing' "$label deployment evidence template indexed-block placeholder test"
  require_pattern "$deployment_template_test" 'indexed block hash placeholder missing' "$label deployment evidence template indexed-block-hash placeholder test"
  require_pattern "$deployment_template_test" 'indexed checkpoint timestamp placeholder missing' "$label deployment evidence template indexed-at placeholder test"
  require_pattern "$deployment_template_test" 'live production smoke blocker missing' "$label deployment evidence template live-smoke blocker positive assertion"
  require_pattern "$deployment_template_test" 'missing smoke blocker rejected by generator' "$label deployment evidence template missing live-smoke blocker negative test"
  require_min_pattern_count "$deployment_template_test" '^[[:space:]]*expect_failure[[:space:]]+"' 12 "$label deployment evidence template declared negative-test coverage"
  require_pattern "$deployment_template_test" 'template rejects TODO primary RPC endpoint' "$label deployment evidence template TODO RPC rejection test"
  require_pattern "$deployment_template_test" 'template rejects wrong primary RPC role' "$label deployment evidence template wrong RPC role rejection test"
  require_pattern "$deployment_template_test" 'template rejects extra RPC control' "$label deployment evidence template unsupported RPC field rejection test"
  require_pattern "$deployment_template_test" 'template rejects public SORA RPC host' "$label deployment evidence template public convenience RPC rejection test"
  require_pattern "$deployment_template_test" 'SORA RPC controls required by generator' "$label deployment evidence template required RPC field rejection test"
  require_pattern_multiline "$release_checklist" 'TLS-edge controls delegated[\s\S]*600 HTTP requests[\s\S]*600 WebSocket upgrades[\s\S]*16[[:space:]]+concurrent WebSockets' "$label release checklist TLS-edge delegated limits attestation"

  require_pattern "$schema_source" 'serviceId:[[:space:]]*String!' "$label health serviceId schema"
  require_pattern "$schema_source" 'schemaVersion:[[:space:]]*Int!' "$label health schemaVersion schema"
  require_pattern "$schema_source" 'ecosystem:[[:space:]]*String!' "$label health ecosystem schema"
  require_pattern "$schema_source" 'chainId:[[:space:]]*String!' "$label health chainId schema"
  require_pattern "$schema_source" 'publicBaseUrl:[[:space:]]*String!' "$label health publicBaseUrl schema"
  require_pattern "$schema_source" 'readOnly:[[:space:]]*Boolean!' "$label health readOnly schema"
  require_pattern "$schema_source" 'genesisHash:[[:space:]]*String' "$label health exact genesis field schema"
  require_pattern "$schema_source" 'latestIndexedBlock:[[:space:]]*Int' "$label health indexed-block field schema"
  require_pattern "$schema_source" 'latestIndexedBlockHash:[[:space:]]*String' "$label health indexed-block-hash field schema"
  require_pattern "$schema_source" 'latestIndexedAt:[[:space:]]*Int' "$label health indexed-at field schema"

  require_pattern "$resolver_source" "POLKASWAP_SERVICE_ID = 'pi\\.soramitsu\\.io'" "$label resolver service identity"
  require_pattern "$resolver_source" "POLKASWAP_PUBLIC_BASE_URL = 'https://pi\\.soramitsu\\.io/graphql'" "$label resolver public base URL"
  require_pattern "$resolver_source" "ecosystem:[[:space:]]*'sora2'" "$label resolver ecosystem identity"
  require_pattern "$resolver_source" "chainId:[[:space:]]*'sora:mainnet'" "$label resolver chain identity"
  require_pattern "$resolver_source" 'readOnly:[[:space:]]*true' "$label resolver read-only identity"
  require_pattern "$resolver_source" 'MAX_HEALTH_AGE_SECONDS = 300' "$label resolver 300-second checkpoint freshness bound"
  require_pattern "$resolver_source" 'MAX_HEALTH_FUTURE_SKEW_SECONDS = 30' "$label resolver 30-second future checkpoint bound"
  require_pattern "$resolver_source" "repository\.get\('updatesStreams', 'chainIdentity'\)" "$label resolver immutable identity lookup"
  require_pattern "$resolver_source" "repository\.get\('updatesStreams', 'chainState'\)" "$label resolver chain checkpoint lookup"
  require_pattern "$resolver_source" 'parseStoredSoraChainIdentity' "$label resolver strict stored identity parser"
  require_pattern "$resolver_source" 'parseStoredSoraChainState' "$label resolver strict stored checkpoint parser"
  require_pattern "$resolver_source" 'stateAge >= -MAX_HEALTH_FUTURE_SKEW_SECONDS && stateAge <= MAX_HEALTH_AGE_SECONDS' "$label resolver bounded checkpoint clock gate"
  require_pattern "$resolver_source" 'genesisHash:[[:space:]]*identityValid \? SORA_MAINNET_GENESIS_HASH : null' "$label resolver exact SORA genesis output"
  require_pattern "$resolver_source" 'latestIndexedBlockHash' "$label resolver indexed-block-hash output"
  require_pattern "$resolver_source" 'latestIndexedAt' "$label resolver indexed-at output"
  require_pattern "$health_identity_test" 'is healthy only for the exact persisted SORA identity and coherent checkpoint' "$label health exact identity positive control"
  require_pattern "$health_identity_test" 'accepts the inclusive.*boundary' "$label health inclusive freshness-boundary controls"
  require_pattern "$health_identity_test" 'one second too stale' "$label health stale checkpoint negative test"
  require_pattern "$health_identity_test" 'one second too far in the future' "$label health future checkpoint negative test"
  require_pattern "$health_identity_test" 'wrong/testnet identity genesis' "$label health wrong-genesis negative test"
  require_pattern "$health_identity_test" 'unsupported identity field' "$label health exact-key parser negative test"

  require_pattern "$production_smoke" "DEFAULT_GRAPHQL_URL = 'https://pi\\.soramitsu\\.io/graphql'" "$label production smoke default URL"
  require_pattern "$production_smoke" 'DEFAULT_TIMEOUT_MS = 10_000' "$label production smoke bounded default deadline"
  require_pattern "$production_smoke" 'DEFAULT_MAX_RESPONSE_BYTES = 1_048_576' "$label production smoke bounded default response size"
  require_pattern "$production_smoke" 'MAX_RESPONSE_BYTES = 5_242_880' "$label production smoke maximum response size ceiling"
  require_pattern "$production_smoke" 'JSON_CONTENT_TYPE' "$label production smoke strict JSON media-type parser"
  require_pattern "$production_smoke" 'ResponseTooLargeError' "$label production smoke oversized-response error"
  require_pattern "$production_smoke" 'readBoundedBody' "$label production smoke bounded body reader"
  require_pattern "$production_smoke" 'withinDeadline' "$label production smoke total request deadline"
  require_pattern "$production_smoke" "redirect:[[:space:]]*'manual'" "$label production smoke redirect refusal transport"
  require_pattern "$production_smoke" 'redactSecrets' "$label production smoke secret redaction"
  require_pattern "$production_smoke" 'DIAGNOSTIC_SCAN_LIMIT = 4_096' "$label production smoke bounded diagnostic scan"
  require_pattern "$production_smoke" 'must not contain credentials' "$label production smoke credential rejection"
  require_pattern "$production_smoke" 'must not contain query strings or fragments' "$label production smoke query-fragment rejection"
  require_pattern "$production_smoke" "url\\.username = ''" "$label production smoke credential log username redaction"
  require_pattern "$production_smoke" "url\\.password = ''" "$label production smoke credential log password redaction"
  require_pattern "$production_smoke" "url\\.search = ''" "$label production smoke query log redaction"
  require_pattern "$production_smoke" "url\\.hash = ''" "$label production smoke fragment log redaction"
  require_pattern "$production_smoke" 'did not return JSON' "$label production smoke non-JSON diagnostic"
  require_pattern "$production_smoke" 'formatFailureCause' "$label production smoke fetch-cause diagnostic"
  require_pattern "$production_smoke" 'PI_GRAPHQL_DEPLOYMENT_HINT' "$label production smoke GraphQL deployment diagnostic"
  require_pattern "$production_smoke" 'Production routing must serve the polkaswap-indexer GraphQL API' "$label production smoke GraphQL routing diagnostic"
  require_pattern "$production_smoke" 'returned invalid JSON' "$label production smoke invalid-JSON diagnostic"
  require_pattern "$production_smoke" 'did not return data\._health' "$label production smoke missing-health diagnostic"
  require_pattern "$production_smoke" 'PI_HEALTH_DEPLOYMENT_HINT' "$label production smoke health deployment diagnostic"
  require_pattern "$production_smoke" 'PI production GraphQL schema is missing _health identity fields' "$label production smoke old-schema diagnostic"
  require_pattern "$production_smoke" 'points at a TON indexer contract' "$label production smoke TON misrouting diagnostic"
  require_pattern "$production_smoke" 'points at a Solswap indexer contract' "$label production smoke Solswap misrouting diagnostic"
  require_pattern "$production_smoke" 'health serviceId must be pi\.soramitsu\.io' "$label production smoke service-id gate"
  require_pattern "$production_smoke" 'health ecosystem must be sora2' "$label production smoke ecosystem gate"
  require_pattern "$production_smoke" 'health chainId must be sora:mainnet' "$label production smoke chain-id gate"
  require_pattern "$production_smoke" 'health readOnly must be true' "$label production smoke read-only gate"
  require_pattern "$production_smoke" 'chainIdentity: updatesStream\(id: "chainIdentity"\)' "$label production smoke immutable chainIdentity alias"
  require_pattern "$production_smoke" 'chainState: updatesStream\(id: "chainState"\)' "$label production smoke coherent chainState alias"
  require_pattern "$production_smoke" 'networkSnapshots\(first: 1, orderBy: \["TIMESTAMP_DESC"\], filter: \{ type: \{ equalTo: "BLOCK" \} \}\)' "$label production smoke filtered BLOCK snapshot query"
  require_pattern "$production_smoke" '!parsed \|\| typeof parsed !== .object. \|\| Array\.isArray\(parsed\)' "$label production smoke top-level JSON object gate"
  require_pattern "$production_smoke" 'health genesisHash must be the reviewed SORA mainnet genesis' "$label production smoke exact SORA genesis gate"
  require_pattern "$production_smoke" 'chainIdentity must exactly prove the reviewed SORA mainnet checkpoint' "$label production smoke immutable chain identity proof"
  require_pattern "$production_smoke" 'chainState must contain an exact SORA mainnet block identity' "$label production smoke exact chain checkpoint proof"
  require_pattern "$production_smoke" 'chainState is incoherent with its immutable chainIdentity checkpoint' "$label production smoke identity/checkpoint coherence gate"
  require_pattern "$production_smoke" 'health latestIndexedBlock must match chainState' "$label production smoke health indexed-block coherence gate"
  require_pattern "$production_smoke" 'health latestIndexedBlockHash must match chainState' "$label production smoke health block-hash coherence gate"
  require_pattern "$production_smoke" 'health latestIndexedAt must match chainState' "$label production smoke health indexed-at coherence gate"
  require_pattern "$production_smoke" 'freshness probe must be the BLOCK snapshot matching chainState' "$label production smoke filtered BLOCK snapshot coherence gate"
  require_pattern "$production_smoke" 'DEFAULT_MAX_INDEXER_AGE_SEC = 300' "$label production smoke 300-second checkpoint age bound"
  require_pattern "$production_smoke" 'FUTURE_TIMESTAMP_TOLERANCE_SEC = 30' "$label production smoke 30-second checkpoint future bound"
  require_pattern "$production_smoke" 'worker checkpoint must be within' "$label production smoke worker checkpoint freshness gate"

  require_pattern "$production_smoke_test" 'rejects credentialed endpoints before making requests' "$label production smoke credential negative test"
  require_pattern "$production_smoke_test" 'redacts credentialed endpoints in CLI failure logs' "$label production smoke credential log redaction negative test"
  require_pattern "$production_smoke_test" 'rejects endpoints with query strings or fragments before making requests' "$label production smoke query-fragment negative test"
  require_pattern "$production_smoke_test" 'redacts query strings and fragments in CLI failure logs' "$label production smoke query-fragment log redaction negative test"
  require_pattern "$production_smoke_test" 'ENOTFOUND' "$label production smoke fetch-cause negative test"
  require_pattern "$production_smoke_test" 'rejects old production health schemas missing identity fields' "$label production smoke old-schema negative test"
  require_pattern "$production_smoke_test" 'rejects deployed health objects missing identity fields with a deployment hint' "$label production smoke old-health-object negative test"
  require_pattern "$production_smoke_test" 'rejects non-JSON production responses' "$label production smoke non-JSON negative test"
  require_pattern "$production_smoke_test" 'rejects invalid JSON production responses with a body preview and routing hint' "$label production smoke invalid-JSON negative test"
  require_pattern "$production_smoke_test" 'rejects HTTP failures with a body preview and routing hint' "$label production smoke HTTP body-preview negative test"
  require_pattern "$production_smoke_test" 'rejects successful responses missing data\._health with a routing hint' "$label production smoke missing-health negative test"
  require_pattern "$production_smoke_test" 'rejects TON indexer routing by contract shape' "$label production smoke TON routing negative test"
  require_pattern "$production_smoke_test" 'rejects Solswap indexer routing by service identity' "$label production smoke Solswap routing negative test"
  require_pattern "$production_smoke_test" 'rejects schema version drift' "$label production smoke schema-version negative test"
  require_pattern "$production_smoke_test" 'rejects non-read-only production contracts' "$label production smoke read-only negative test"
  require_pattern "$production_smoke_test" 'rejects redirects without following' "$label production smoke redirect refusal negative test"
  require_pattern "$production_smoke_test" 'total request deadline for slow and non-cooperative fetches' "$label production smoke non-cooperative transport deadline test"
  require_pattern "$production_smoke_test" 'oversized response bodies' "$label production smoke oversized decoded-body negative test"
  require_pattern "$production_smoke_test" 'misleading JSON content type' "$label production smoke misleading JSON media-type negative test"
  require_pattern "$production_smoke_test" 'redacts and bounds secrets' "$label production smoke secret transport diagnostic test"
  require_pattern "$production_smoke_test" 'redacts token, password, API-key, and bearer' "$label production smoke secret response diagnostic test"
  require_pattern "$production_smoke_test" 'rejects non-object top-level JSON payload' "$label production smoke top-level object negative test"
  require_pattern "$production_smoke_test" 'rejects missing and internally inconsistent worker checkpoints' "$label production smoke checkpoint structure negative tests"
  require_pattern "$production_smoke_test" 'rejects stale or future coherent worker checkpoint timestamps' "$label production smoke checkpoint clock negative tests"
  require_pattern "$production_smoke_test" 'accepts the inclusive.*checkpoint boundary' "$label production smoke checkpoint boundary positive controls"
  require_pattern "$production_smoke_test" 'rejects a fresh unrelated snapshot instead of using it to hide stale chainState' "$label production smoke unrelated-snapshot negative test"
  require_pattern "$production_smoke_test" 'rejects health checkpoint fields that do not exactly match chainState' "$label production smoke health/checkpoint mismatch test"
  require_pattern "$production_smoke_test" 'rejects a chainIdentity record with a wrong genesis despite correct labels' "$label production smoke wrong-genesis identity test"
  require_pattern "$schema_test" "serviceId:[[:space:]]*'pi\\.soramitsu\\.io'" "$label schema test service identity"
  require_pattern "$schema_test" "publicBaseUrl:[[:space:]]*'https://pi\\.soramitsu\\.io/graphql'" "$label schema test public base URL"
}

iroha_sccp_v1_and_kagemusha_checks() {
  local repo_path="$1"
  local retired_ton_deploy="$repo_path/scripts/sccp_ton_taira_xor_deploy.mjs"
  local retired_ton_deploy_test="$repo_path/scripts/sccp_ton_taira_xor_deploy.test.mjs"
  local retired_kagemusha_test="$repo_path/javascript/iroha_js/test/kagemushaRecursiveSpend.test.js"
  local retired_kagemusha_parity_test="$repo_path/javascript/iroha_js/test/kagemushaFfiContractParity.test.js"
  local retired_csharp_kagemusha_test="$repo_path/csharp/tests/Hyperledger.Iroha.Sdk.Tests/KagemushaRecursiveSpendNativeTests.cs"
  local sccp_src="$repo_path/javascript/iroha_js/src/sccp.js"
  local sccp_dist="$repo_path/javascript/iroha_js/dist/sccp.js"
  local sccp_exact_test="$repo_path/javascript/iroha_js/test/sccpExact.test.js"
  local declarations="$repo_path/javascript/iroha_js/index.d.ts"
  local release_common="$repo_path/scripts/sccp_release_common.py"
  local release_bundle="$repo_path/scripts/sccp_release_bundle.py"
  local release_verifier="$repo_path/scripts/sccp_verify_release_bundle.py"
  local readiness_report="$repo_path/scripts/sccp_release_readiness_report.py"
  local release_tooling_test="$repo_path/pytests/scripts/sccp_release_tooling_test.py"
  local production_corridor="$repo_path/scripts/check_sccp_production_corridor.sh"
  local crypto_src="$repo_path/javascript/iroha_js/src/crypto.js"
  local crypto_dist="$repo_path/javascript/iroha_js/dist/crypto.js"
  local crypto_browser_src="$repo_path/javascript/iroha_js/src/crypto.browser.js"
  local crypto_browser_dist="$repo_path/javascript/iroha_js/dist/crypto.browser.js"
  local package_dist_test="$repo_path/javascript/iroha_js/test/package_dist.test.js"

  require_file "$sccp_src" "../iroha SCCP V1 JavaScript source"
  require_file "$sccp_dist" "../iroha SCCP V1 JavaScript dist"
  require_file "$sccp_exact_test" "../iroha exact SCCP V1 JavaScript tests"
  require_file "$declarations" "../iroha JS declarations"
  require_file "$release_common" "../iroha SCCP V1 release evidence primitives"
  require_file "$release_bundle" "../iroha SCCP V1 deterministic release bundle builder"
  require_file "$release_verifier" "../iroha SCCP V1 independent release bundle verifier"
  require_file "$readiness_report" "../iroha SCCP V1 readiness renderer"
  require_file "$release_tooling_test" "../iroha SCCP V1 release tooling adversarial tests"
  require_executable_file "$production_corridor" "../iroha SCCP V1 production corridor"
  require_file "$crypto_src" "../iroha JS Kagemusha crypto source"
  require_file "$crypto_dist" "../iroha JS Kagemusha crypto dist"
  require_file "$crypto_browser_src" "../iroha browser Kagemusha crypto source"
  require_file "$crypto_browser_dist" "../iroha browser Kagemusha crypto dist"
  require_file "$package_dist_test" "../iroha package dist tests"

  # The current SCCP V1 surface deliberately retired the earlier TON route
  # manifest deploy/query helpers. Keep that retirement fail closed and bind the
  # replacement to the externally signed ETH/BSC/TRON release corridor.
  reject_path "$retired_ton_deploy" "../iroha retired TON SCCP deploy script"
  reject_path "$retired_ton_deploy_test" "../iroha retired TON SCCP deploy script test"
  # The f47 retirement removed the language-specific Kagemusha lifecycle SDKs.
  # Their absence is intentional; the ABI-21 bridge and current native/mobile
  # policy checks below are the maintained contract.
  reject_path "$retired_kagemusha_test" "../iroha retired JavaScript Kagemusha lifecycle test"
  reject_path "$retired_kagemusha_parity_test" "../iroha retired JavaScript ABI-17 Kagemusha parity test"
  reject_path "$retired_csharp_kagemusha_test" "../iroha retired C# Kagemusha lifecycle test"
  require_pattern "$release_common" 'contains no signing or deployment code' "../iroha SCCP release tooling non-deployment boundary"
  require_pattern_multiline "$release_common" 'RELEASE_CIRCUIT_IDS = \([\s\S]*sccp-sora-taira-to-ethereum-mainnet-groth16-bn254-v1[\s\S]*sccp-sora-taira-to-bsc-mainnet-groth16-bn254-v1[\s\S]*sccp-sora-taira-to-tron-mainnet-groth16-bn254-v1[\s\S]*\)' "../iroha exact SCCP V1 release circuit inventory"
  require_pattern_multiline "$release_common" 'PROFILE_ORDER = \([\s\S]*"ethereum-mainnet"[\s\S]*"bsc-mainnet"[\s\S]*"tron-mainnet"[\s\S]*\)' "../iroha exact SCCP V1 release profile order"
  require_pattern "$readiness_report" 'Solana and TON are outside SCCP V1 and are rejected\.' "../iroha SCCP V1 readiness explicit Solana/TON retirement"
  require_pattern "$release_bundle" 'verify_production_semantic_artifacts' "../iroha SCCP release bundle semantic-artifact verification"
  require_pattern "$release_bundle" 'verify_rust_release_signatures' "../iroha SCCP release bundle detached-signature verification"
  require_pattern "$release_verifier" 'bundle file inventory does not exactly match bundle\.json' "../iroha SCCP release bundle exact inventory verification"
  require_pattern "$release_verifier" 'verify_rust_semantic_proofs' "../iroha SCCP release bundle independent semantic-proof verification"
  require_pattern_multiline "$production_corridor" 'phase_evidence_scripts\(\)[\s\S]*sccp_release_tooling_test\.py[\s\S]*sccp_release_fixture\.py[\s\S]*--rust-validator[\s\S]*validate[\s\S]*build --output-dir[\s\S]*verify' "../iroha SCCP production corridor release-evidence phase"
  require_pattern_multiline "$production_corridor" 'phase_js_sdk\(\)[\s\S]*javascript/iroha_js/test/sccpExact\.test\.js[\s\S]*javascript/iroha_js/test/package_dist\.test\.js' "../iroha SCCP production corridor exact JavaScript phase"
  require_pattern "$release_tooling_test" 'test_production_entrypoints_expose_no_test_policy_or_signing_switch' "../iroha SCCP production CLI test-policy/signing-switch rejection"
  require_pattern "$release_tooling_test" 'test_production_tooling_has_no_private_key_api_or_signing_call' "../iroha SCCP production tooling private-key/signing rejection"
  require_pattern "$sccp_exact_test" 'closed SCCP inventory exposes exact ETH, BSC, Solana testnet, and TRON profiles' "../iroha closed Solana-aware SCCP V1 inventory regression"
  require_pattern "$sccp_exact_test" 'closed codecs accept exact layouts and reject retired tags and textual aliases' "../iroha retired SCCP codec regression"
  require_pattern_multiline "$sccp_exact_test" 'Object\.keys\(SCCP_NETWORK_PROFILES\)[\s\S]*"solana-testnet"[\s\S]*Object\.keys\(SCCP_CODEC_KEYS\)[\s\S]*\["1", "2", "5", "6"\][\s\S]*SCCP_PAYLOAD_KINDS[\s\S]*\["transfer"\]' "../iroha exact Solana-aware SCCP V1 profile/codec/payload inventory"
  require_pattern_multiline "$sccp_exact_test" 'for \(const retired of \[[\s\S]*"SCCP_DOMAIN_SOL"[\s\S]*"SCCP_DOMAIN_TON"[\s\S]*"SCCP_CODEC_SOLANA_BASE58"[\s\S]*"SCCP_CODEC_TON_ACCOUNT36"[\s\S]*retired in exports[\s\S]*false' "../iroha SCCP legacy-Solana/TON public export rejection"
  for retired_pattern in \
    'SCCP_DOMAIN_(SOL|TON)([^A-Z0-9_]|$)' \
    'SCCP_CODEC_(SOLANA_BASE58|TON_ACCOUNT36)' \
    'sccpBuildTonMessageBundleSourceProofWithDeployment' \
    'sccpTonFixtureValidatorSetHash'; do
    reject_pattern "$sccp_src" "$retired_pattern" "../iroha SCCP source retired legacy-Solana/TON surface"
    reject_pattern "$sccp_dist" "$retired_pattern" "../iroha SCCP dist retired legacy-Solana/TON surface"
    reject_pattern "$declarations" "$retired_pattern" "../iroha SCCP declarations retired legacy-Solana/TON surface"
  done
  require_pattern "$sccp_src" 'export const SCCP_DOMAIN_SOLANA = 3' "../iroha SCCP source canonical Solana domain"
  require_pattern "$sccp_dist" 'export const SCCP_DOMAIN_SOLANA = 3' "../iroha SCCP dist canonical Solana domain"
  require_pattern "$declarations" 'SCCP_DOMAIN_SOLANA: 3' "../iroha SCCP declaration canonical Solana domain"
  require_pattern "$sccp_src" 'export const SCCP_CODEC_SOLANA_PUBKEY32 = 6' "../iroha SCCP source canonical Solana codec"
  require_pattern "$sccp_dist" 'export const SCCP_CODEC_SOLANA_PUBKEY32 = 6' "../iroha SCCP dist canonical Solana codec"
  require_pattern "$declarations" 'SCCP_CODEC_SOLANA_PUBKEY32: 6' "../iroha SCCP declaration canonical Solana codec"
  reject_pattern "$declarations" 'kind:[[:space:]]*"ton_internal_message"' "../iroha retired TON platform-submission declaration"
  require_pattern_multiline "$package_dist_test" 'package SCCP exports expose the exact Solana-aware inventory[\s\S]*SCCP_DOMAIN_SOLANA[\s\S]*SCCP_CODEC_SOLANA_PUBKEY32[\s\S]*solana-testnet' "../iroha package SCCP exact Solana-aware export guard"
  require_pattern_multiline "$package_dist_test" 'package SCCP exports reject retired TON and diagnostic helper surfaces[\s\S]*SCCP_DOMAIN_TON[\s\S]*SCCP_CODEC_TON_ACCOUNT36[\s\S]*sccpBuildTonMessageBundleSourceProofWithDeployment[\s\S]*sccpTonFixtureValidatorSetHash' "../iroha package SCCP exact retired-TON/helper guard"

  for crypto_file in "$crypto_src" "$crypto_dist" "$crypto_browser_src" "$crypto_browser_dist"; do
    reject_pattern "$crypto_file" 'isSupportedKagemushaRecursiveSpendAppendOutputProofCircuitId' "../iroha retired JavaScript Kagemusha selector support surface"
    reject_pattern "$crypto_file" 'canProveKagemushaRecursiveSpendAppendOutputProofCircuitId' "../iroha retired JavaScript Kagemusha selector proving surface"
  done
  reject_pattern "$package_dist_test" 'isSupportedKagemushaRecursiveSpendAppendOutputProofCircuitId' "../iroha package retired Kagemusha selector support test"
  reject_pattern "$package_dist_test" 'canProveKagemushaRecursiveSpendAppendOutputProofCircuitId' "../iroha package retired Kagemusha selector proving test"
  reject_pattern "$package_dist_test" 'KAGEMUSHA_RECURSIVE_SPEND_LINEAGE_APPEND_PROOF_CIRCUIT_ID_V1' "../iroha package retired Kagemusha lineage-selector test"
}

iroha_kagemusha_abi21_v4_policy_closure_checks() {
  local repo_path="$1"
  local policy="$repo_path/ci/check_kagemusha_recursive_spend_policy.sh"
  local payload_bench="$repo_path/ci/check_kagemusha_recursive_spend_payload_bench.sh"
  local production_readiness="$repo_path/ci/check_kagemusha_production_readiness.sh"
  local sdk_contract="$repo_path/ci/check_kagemusha_recursive_spend_v4_sdk_contract.sh"
  local reviewed_lock_guard="$repo_path/ci/check_kagemusha_reviewed_cargo_lock.sh"
  local reviewed_lock_secure_reader="$repo_path/ci/kagemusha_secure_read.py"
  local reviewed_lock="$repo_path/fixtures/kagemusha/cargo-lock.reviewed.v2"
  local reviewed_lock_legacy="$repo_path/fixtures/kagemusha/cargo-lock.reviewed.v1"
  local reviewed_lock_receipt="$repo_path/fixtures/kagemusha/cargo-lock.reviewed.v2.receipt.json"
  local reviewed_lock_inputs="$repo_path/fixtures/kagemusha/cargo-lock.reviewed.v2.inputs"
  local reviewed_lock_seed="$repo_path/fixtures/kagemusha/cargo-lock.reviewed.v2.seed"
  local payload_generator="$repo_path/crates/iroha_data_model/src/bin/kagemusha_peer_transport_fixtures.rs"
  local payload_factory="$repo_path/crates/iroha_data_model/src/offline/peer_transport_fixtures.rs"
  local payload_fixture="$repo_path/fixtures/kagemusha/peer_transport_measurements_v1.json"
  local data_model_manifest="$repo_path/crates/iroha_data_model/Cargo.toml"
  local data_model_offline="$repo_path/crates/iroha_data_model/src/offline/mod.rs"
  local workflow="$repo_path/.github/workflows/pr_kagemusha_payload_bench.yml"
  local csharp_workflow="$repo_path/.github/workflows/pr_csharp.yml"
  local bridge_header_guard="$repo_path/ci/check_connect_norito_bridge_header.sh"
  local swift_v2_native="$repo_path/IrohaSwift/Sources/IrohaSwift/KagemushaRecursiveSpendV2Native.swift"
  local swift_v2_tests="$repo_path/IrohaSwift/Tests/IrohaSwiftTests/KagemushaRecursiveSpendV2Tests.swift"
  local openapi_check="$repo_path/ci/check_openapi_spec.sh"
  local torii_issuer="$repo_path/crates/iroha_torii/src/offline_commands.rs"
  local torii_openapi="$repo_path/crates/iroha_torii/src/openapi.rs"
  local torii_smoke="$repo_path/crates/iroha_torii/tests/offline_redeem_contract.rs"
  local core_offline="$repo_path/crates/iroha_core/src/smartcontracts/isi/offline.rs"
  local core_overlay="$repo_path/crates/iroha_core/src/pipeline/overlay.rs"
  local contract_doc="$repo_path/specs/offline_kagemusha_v2_contract.md"
  local readiness_doc="$repo_path/specs/offline_kagemusha.md"
  local openapi_root="$repo_path/artifacts/openapi/torii.json"
  local openapi_current="$repo_path/artifacts/openapi/versions/current/torii.json"
  local manifest_root="$repo_path/artifacts/openapi/manifest.json"
  local manifest_current="$repo_path/artifacts/openapi/versions/current/manifest.json"
  local versions="$repo_path/artifacts/openapi/versions.json"

  for required in \
    "$policy" "$production_readiness" "$sdk_contract" "$reviewed_lock_guard" \
    "$reviewed_lock_secure_reader" "$reviewed_lock" "$reviewed_lock_legacy" \
    "$reviewed_lock_receipt" "$reviewed_lock_inputs" "$reviewed_lock_seed" \
    "$payload_generator" "$payload_factory" "$payload_fixture" \
    "$data_model_manifest" "$data_model_offline" "$workflow" "$csharp_workflow" "$bridge_header_guard" \
    "$swift_v2_native" "$swift_v2_tests" \
    "$openapi_check" "$torii_issuer" "$torii_openapi" "$torii_smoke" \
    "$core_offline" "$core_overlay" "$contract_doc" "$readiness_doc" "$openapi_root" \
    "$openapi_current" "$manifest_root" "$manifest_current" "$versions"; do
    require_file "$required" "../iroha Kagemusha ABI-21/V4 policy/Torii/OpenAPI closure artifact"
  done
  require_executable_file "$payload_bench" "../iroha Kagemusha serialization-derived payload gate"
  require_executable_file "$production_readiness" "../iroha Kagemusha production-candidate readiness gate"
  require_executable_file "$sdk_contract" "../iroha Kagemusha ABI-21/V4 SDK contract gate"
  require_executable_file "$reviewed_lock_guard" "../iroha reviewed Kagemusha Cargo lock gate"
  require_exact_file_size "$reviewed_lock" 319284 "../iroha reviewed Kagemusha Cargo lock v2 artifact"
  require_exact_file_size "$reviewed_lock_legacy" 315548 "../iroha reviewed Kagemusha Cargo lock v1 provenance artifact"
  require_exact_file_size "$reviewed_lock_receipt" 3912 "../iroha reviewed Kagemusha Cargo lock v2 receipt"
  require_exact_file_size "$reviewed_lock_inputs" 3555 "../iroha reviewed Kagemusha Cargo lock v2 input inventory"
  require_exact_file_size "$reviewed_lock_seed" 321889 "../iroha reviewed Kagemusha Cargo lock v2 seed"
  require_exact_file_size "$reviewed_lock_secure_reader" 48947 "../iroha reviewed Kagemusha secure-reader helper"

  for test_name in \
    transaction_recovery_uses_the_authorized_nonzero_id_and_exact_matching_instruction \
    unauthorized_outer_authority_cannot_poison_offline_recovery \
    terminal_recovery_binds_the_exact_operation_and_preserves_both_outcomes \
    submission_claim_deduplicates_and_binds_the_complete_typed_request \
    unavailable_abi21_release_fails_closed_with_stable_service_error \
    operation_binding_covers_the_full_typed_request_and_route \
    terminal_finality_requires_nonzero_exact_identity_hash_height_and_time; do
    require_pattern "$torii_issuer" "$test_name" "../iroha durable Torii Kagemusha ABI-21/V4 focused test $test_name"
  done
  require_pattern "$torii_smoke" 'fn production_source\(source: &str\) -> &str' "../iroha Kagemusha ABI-21/V4 smoke test production-source gate"
  require_pattern "$torii_smoke" 'typed_offline_redeem_route_accepts_only_the_direct_v2_request' "../iroha direct typed Kagemusha redeem smoke test"
  require_pattern "$torii_smoke" 'offline_operation_polling_preserves_redeem_identity_and_finality_integrity' "../iroha Kagemusha polling identity/finality smoke test"
  require_pattern "$torii_openapi" 'generated_spec_documents_strict_typed_offline_request_schemas_and_states' "../iroha strict typed-offline OpenAPI schema test"
  require_pattern "$torii_openapi" 'generated_spec_includes_documented_paths' "../iroha documented OpenAPI paths test"

  require_pattern "$core_offline" 'kagemusha_v4_operation_marker_is_global_while_other_markers_are_authority_scoped' "../iroha global Kagemusha ABI-21/V4 operation-id test"
  require_pattern "$core_offline" 'kagemusha_v4_cross_authority_operation_conflict_preserves_all_state' "../iroha cross-authority Kagemusha ABI-21/V4 rollback test"
  require_pattern "$core_offline" 'kagemusha_v4_unavailable_release_fails_closed_without_state_mutation' "../iroha Kagemusha ABI-21/V4 fail-closed dispatch test"
  require_pattern "$core_overlay" 'submitted contract bytecode does not exactly match the artifact stored for bound instance' "../iroha bound-contract exact stored-artifact bytecode gate"
  require_pattern "$core_overlay" 'raw_and_proved_ivm_reject_header_substitution_for_bound_contract' "../iroha raw/proved IVM header-substitution regression"
  require_pattern "$core_overlay" 'the canonical contract hash must authenticate the execution header' "../iroha full-artifact header-authentication negative control"
  require_pattern "$contract_doc" 'global namespace across authorities and operation kinds' "../iroha global Kagemusha ABI-21/V4 operation-id contract"
  require_pattern "$contract_doc" 'markers remain authority-scoped' "../iroha authority-scoped Kagemusha ABI-21/V4 replay-marker contract"
  require_pattern_multiline "$readiness_doc" 'KAGEMUSHA_RECURSIVE_SPEND_PROOF_BACKEND_AVAILABLE[\s\S]*kagemusha-production-enabled[\s\S]*safety gate[\s\S]*exact[[:space:]]+authenticated ABI-21/V4 material referenced by that transaction' "../iroha compile-time Kagemusha ABI-21/V4 production safety boundary"

  # The current policy exposes one aggregate --self-test. Require a named,
  # auditable mutation catalog behind that aggregate for every destructive
  # surface that the former one-mode-per-command checker covered.
  for mutation_case in \
    torii_redeem_surface_mutation \
    torii_route_inventory_mutation \
    model_exact_field_inventory_mutation \
    archive_field_shape_mutation \
    retired_model_fields_mutation \
    retired_redeem_aliases_mutation \
    auxiliary_field_inventory_mutation \
    openapi_contract_mutation; do
    require_pattern_multiline "$policy" "POLICY_SELF_TEST_CASES = \\{[\\s\\S]*\"$mutation_case\"" "../iroha Kagemusha policy self-test case $mutation_case"
  done
  require_pattern_multiline "$policy" 'POLICY_SELF_TEST_CASES = \{[\s\S]*"smoke_contract_mutation"[\s\S]*for self_test_name in sorted\(POLICY_SELF_TEST_CASES\)' "../iroha Kagemusha policy self-test case smoke_contract_mutation and aggregate runner"

  require_pattern "$policy" 'ci/check_kagemusha_production_readiness\.sh" candidate' "../iroha Kagemusha policy production-candidate prerequisite"
  require_pattern "$policy" 'ci/check_kagemusha_recursive_spend_v4_sdk_contract\.sh' "../iroha Kagemusha policy ABI-21/V4 SDK-contract prerequisite"
  require_pattern "$policy" 'ci/check_kagemusha_recursive_spend_payload_bench\.sh' "../iroha Kagemusha policy payload-benchmark prerequisite"
  require_pattern_multiline "$policy" 'if \[\[ "\$\{MODE\}" == "--self-test" \]\]; then[\s\S]*check_kagemusha_production_readiness\.sh" candidate --self-test[\s\S]*check_kagemusha_recursive_spend_v4_sdk_contract\.sh" --self-test[\s\S]*check_kagemusha_recursive_spend_payload_bench\.sh" --self-test[\s\S]*else[\s\S]*check_kagemusha_production_readiness\.sh" candidate[\s\S]*check_kagemusha_recursive_spend_v4_sdk_contract\.sh"[\s\S]*check_kagemusha_recursive_spend_payload_bench\.sh"' "../iroha Kagemusha policy exact positive/self-test prerequisite delegation"
  require_pattern "$workflow" 'check_connect_norito_bridge_header\.sh --self-test' "../iroha workflow aggregate ABI-21 bridge self-test"
  require_pattern "$workflow" 'check_kagemusha_recursive_spend_policy\.sh --self-test' "../iroha workflow aggregate Kagemusha policy self-test"

  # The payload evidence must come from live canonical Norito serialization.
  # Source/fixture digests alone are circular after a serializer dependency
  # changes, so the maintained gate first regenerates and byte-compares the
  # checked-in fixture before applying the reviewed release pins.
  require_pattern_multiline "$payload_bench" 'cargo run --quiet --locked --manifest-path[\s\S]*-p iroha_data_model --features test-fixtures[\s\S]*--bin kagemusha_peer_transport_fixtures -- --check' "../iroha live Kagemusha canonical serializer fixture check"
  require_pattern_multiline "$payload_bench" 'ROOT_KEYS = \{[\s\S]*"generator_dependency"[\s\S]*"generator_sha256"[\s\S]*"cargo_lock"[\s\S]*"cargo_lock_sha256"[\s\S]*"proof_bytes"[\s\S]*"records"[\s\S]*\}' "../iroha payload fixture exact reviewed-lock-bound root-key contract"
  require_pattern "$payload_bench" 'json\.loads\(raw, object_pairs_hook=reject_duplicate_keys\)' "../iroha payload fixture duplicate-JSON-key rejection"
  require_pattern "$payload_bench" 'reviewed_cargo_lock_relative = "fixtures/kagemusha/cargo-lock\.reviewed\.v2"' "../iroha payload gate reviewed Cargo lock v2 path"
  require_pattern "$payload_bench" 'CARGO_LOCK_SHA256 = "467a0003a7a3c2c132fd8a1f1cbc366db4029972f972a955071e30d77fe870f3"' "../iroha payload gate reviewed Cargo lock digest pin"
  require_pattern "$payload_bench" 'bash "\$\{ROOT_DIR\}/ci/check_kagemusha_reviewed_cargo_lock\.sh" --verify' "../iroha payload gate reviewed Cargo lock verification"
  require_pattern "$payload_bench" 'ambient != reviewed' "../iroha payload gate ambient/reviewed Cargo lock byte identity"
  require_pattern "$payload_bench" 'if \(archive_bytes, digest\) != \(reviewed_bytes, reviewed_digest\)' "../iroha payload reviewed byte-size and digest binding"
  require_pattern "$payload_bench" 'if digest in archive_digests or archive in archive_values' "../iroha payload duplicate serialized-archive rejection"
  require_pattern "$payload_bench" 'factory_source \+ b"\\n"' "../iroha payload generator-dependency drift negative control"
  require_pattern "$payload_bench" 'live serializer check accepted a stale canonical fixture' "../iroha live serializer stale-fixture rejection"

  while IFS='|' read -r archive_label gate_bytes fixture_bytes archive_digest; do
    require_pattern_multiline "$payload_bench" "\"${archive_label}\":[[:space:]]*\\([\\s\\S]*${gate_bytes},[\\s\\S]*\"${archive_digest}\"" "../iroha reviewed payload gate archive ${archive_label} size/digest"
    require_pattern_multiline "$payload_fixture" "\"label\":[[:space:]]*\"${archive_label}\"[\\s\\S]*\"archive_bytes\":[[:space:]]*${fixture_bytes},[\\s\\S]*\"archive_sha256\":[[:space:]]*\"${archive_digest}\"" "../iroha canonical payload fixture archive ${archive_label} size/digest"
  done <<'KAGEMUSHA_ARCHIVES'
request|614|614|03c308b70ca7d7eb0016249f404ecb5aca5effdf92b66e00bb97aac688d8fcc9
acknowledgement|370|370|10df2bf6b39e6a962573c910dd823381220dbdaef1f8e77a7b62fc44045a91ef
payment-depth-1-hop-1|16_863|16863|0e919555969feaa5368308341573f93350ea8f768738e83c2210efe5e5bb7e91
payment-depth-8-hop-8|17_034|17034|b9a5c359853f2c8ae6528d8c619f17d38154d5a5f9694f8eb7ca8959f1a306f6
payment-depth-16-hop-8|17_226|17226|a8d93e9ca015115c53f15305dde48754e2fe206859e36f9ad7899cd31e4ab0df
payment-depth-32-hop-8|17_610|17610|c3aa58a4aabeabe48803e4a8cdae2c245aa48fd721a400c33248c6fe1f7c11ef
payment-depth-64-hop-8|18_378|18378|71816aa146287f28a4f2e9a29381aab94d6612f589a3bce9009f5651b4c62e53
KAGEMUSHA_ARCHIVES
  require_exact_pattern_count "$payload_fixture" '"label"[[:space:]]*:' 7 "../iroha exact seven-record canonical payload fixture inventory"
  require_pattern "$payload_fixture" '"schema"[[:space:]]*:[[:space:]]*"iroha\.kagemusha\.peer_transport_measurements\.v1"' "../iroha canonical payload fixture schema"
  require_pattern "$payload_fixture" '"generator_sha256"[[:space:]]*:[[:space:]]*"3e1153d1b5a7341e7a53d376046c8b064716cb12738251c48405b09e2a2f080c"' "../iroha canonical ABI-21/V4 payload generator/factory digest"
  require_pattern "$payload_fixture" '"cargo_lock"[[:space:]]*:[[:space:]]*"fixtures/kagemusha/cargo-lock\.reviewed\.v2"' "../iroha canonical payload reviewed Cargo lock path"
  require_pattern "$payload_fixture" '"cargo_lock_sha256"[[:space:]]*:[[:space:]]*"467a0003a7a3c2c132fd8a1f1cbc366db4029972f972a955071e30d77fe870f3"' "../iroha canonical payload reviewed Cargo lock digest"
  require_pattern "$payload_fixture" '"proof_bytes"[[:space:]]*:[[:space:]]*4096' "../iroha canonical payload proof byte count"

  for self_test_name in \
    archive-byte-tamper \
    malformed-odd-hex \
    serializer-drift-with-rebound-digest \
    dishonest-size \
    duplicate-record \
    duplicate-archive \
    missing-release-profile \
    generator-digest-drift \
    extra-root-field \
    duplicate-json-key \
    generator-source-drift \
    generator-dependency-source-drift \
    reviewed-cargo-lock-byte-drift \
    ambient-cargo-lock-mismatch \
    live-serializer-rejects-stale-fixture; do
    require_pattern "$payload_bench" "$self_test_name" "../iroha Kagemusha payload adversarial self-test $self_test_name"
  done

  require_pattern "$payload_generator" 'include_bytes!\("\.\./offline/peer_transport_fixtures\.rs"\)' "../iroha payload generator factory-source binding"
  require_pattern_multiline "$payload_generator" 'source_hasher\.update\(GENERATOR_SOURCE\);[\s\S]*source_hasher\.update\(\[0\]\);[\s\S]*source_hasher\.update\(FACTORY_SOURCE\)' "../iroha payload generator unambiguous source/dependency digest"
  require_pattern "$payload_generator" 'kagemusha_peer_transport_fixture_records_v1\(\)' "../iroha payload generator canonical factory invocation"
  require_pattern_multiline "$payload_factory" 'archive:[[:space:]]*to_bytes\(&request\)[\s\S]*payment\.validate_public_binding\(\)\?[\s\S]*archive:[[:space:]]*to_bytes\(&payment\)\?' "../iroha canonical request/payment serialization factory"
  require_pattern "$payload_factory" 'archive:[[:space:]]*acknowledgement\.canonical_archive_for_payment_v4\(request, bundle\)\?' "../iroha canonical ABI-21/V4 acknowledgement serialization factory"
  require_pattern_multiline "$data_model_manifest" '\[\[bin\]\][\s\S]*name = "kagemusha_peer_transport_fixtures"[\s\S]*path = "src/bin/kagemusha_peer_transport_fixtures\.rs"[\s\S]*required-features = \["test-fixtures"\]' "../iroha feature-gated canonical payload generator binary"
  require_pattern_multiline "$data_model_offline" '#\[cfg\(feature = "test-fixtures"\)\][[:space:]]*mod peer_transport_fixtures;[\s\S]*#\[cfg\(feature = "test-fixtures"\)\][[:space:]]*pub use peer_transport_fixtures' "../iroha test-fixture-only canonical payload factory exposure"

  for workflow_path in \
    'Cargo\.lock' \
    'fixtures/kagemusha/cargo-lock\.reviewed\.v1' \
    'fixtures/kagemusha/cargo-lock\.reviewed\.v2' \
    'fixtures/kagemusha/cargo-lock\.reviewed\.v2\.inputs' \
    'fixtures/kagemusha/cargo-lock\.reviewed\.v2\.seed' \
    'fixtures/kagemusha/cargo-lock\.reviewed\.v2\.receipt\.json' \
    'ci/check_kagemusha_\*\.sh' \
    'crates/iroha_crypto/\*\*' \
    'crates/iroha_data_model/src/\*\*' \
    'crates/iroha_data_model/Cargo\.toml' \
    'crates/iroha_data_model_derive/\*\*' \
    'crates/iroha_primitives/\*\*' \
    'crates/iroha_schema/\*\*' \
    'crates/norito/\*\*' \
    'crates/norito_derive/\*\*' \
    'fixtures/kagemusha/peer_transport_measurements_v1\.json' \
    'IrohaSwift/\*\*'; do
    require_pattern "$workflow" "^[[:space:]]*-[[:space:]]*\"${workflow_path}\"$" "../iroha Kagemusha workflow serializer/transport dependency path ${workflow_path}"
  done
  require_exact_pattern_count "$workflow" '^[[:space:]]*- uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4$' 6 "../iroha exact pinned Kagemusha workflow checkout actions"
  require_exact_pattern_count "$workflow" '^[[:space:]]*- uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6$' 2 "../iroha exact pinned Kagemusha workflow Python actions"
  require_exact_pattern_count "$workflow" '^[[:space:]]*- uses: dtolnay/rust-toolchain@4be7066ada62dd38de10e7b70166bc74ed198c30 # stable$' 4 "../iroha exact pinned Kagemusha workflow Rust toolchain actions"
  require_exact_pattern_count "$workflow" '^[[:space:]]*- uses: Swatinem/rust-cache@e18b497796c12c097a38f9edb9d0641fb99eee32 # v2$' 4 "../iroha exact pinned Kagemusha workflow Rust cache actions"
  require_exact_pattern_count "$workflow" 'run: ci/check_kagemusha_reviewed_cargo_lock\.sh --materialize$' 4 "../iroha exact four reviewed Cargo lock materializations"
  require_exact_pattern_count "$workflow" 'run: ci/check_kagemusha_reviewed_cargo_lock\.sh --self-test$' 1 "../iroha exact reviewed Cargo lock workflow self-test"
  require_exact_pattern_count "$workflow" '^[[:space:]]*- run: cargo test --locked -p ' 22 "../iroha exact 22 locked Kagemusha Rust test commands"
