  require_pattern_multiline "$csharp_workflow" '- name: Materialize the exact reviewed Cargo dependency lock[\s\S]{0,160}run: ci/check_kagemusha_reviewed_cargo_lock\.sh --materialize[\s\S]{0,160}- uses: actions-rust-lang/setup-rust-toolchain@166cdcfd11aee3cb47222f9ddb555ce30ddb9659[\s\S]{0,100}target: \$\{\{ matrix\.target \}\}[\s\S]{0,80}cache: false' "../iroha exact C# native reviewed-lock-before-uncached-Rust setup"
  require_pattern_multiline "$csharp_workflow" 'if \[\[ -e target \]\]; then[\s\S]{0,160}C# native release build requires a fresh target directory[\s\S]{0,1200}target_rustflags_key="CARGO_TARGET_\$\(printf[\s\S]{0,1200}env -u "\$target_rustflags_key" -u CARGO_ENCODED_RUSTFLAGS -u CARGO_BUILD_RUSTFLAGS -u RUSTFLAGS cargo build --locked --release -p connect_norito_bridge --target "\$target"' "../iroha C# native release fresh-target and ambient-Rustflags invariant"

