  require_pattern "$reviewed_lock_guard" '^EXPECTED_BYTES=319284$' "../iroha reviewed Cargo lock exact byte pin"
  require_pattern "$reviewed_lock_guard" '^EXPECTED_SHA256="467a0003a7a3c2c132fd8a1f1cbc366db4029972f972a955071e30d77fe870f3"$' "../iroha reviewed Cargo lock exact digest pin"
  require_pattern "$reviewed_lock_guard" '^REVIEWED_LOCK="\$\{ROOT_DIR\}/fixtures/kagemusha/cargo-lock\.reviewed\.v2"$' "../iroha reviewed Cargo lock v2 path pin"
  require_pattern "$reviewed_lock_guard" '^LEGACY_EXPECTED_BYTES=315548$' "../iroha reviewed Cargo lock v1 provenance byte pin"
  require_pattern "$reviewed_lock_guard" '^LEGACY_EXPECTED_SHA256="ff773ee12a07de45d0e9df9ed29620142d884f365adb5e83d372e15dbedcd409"$' "../iroha reviewed Cargo lock v1 provenance digest pin"
  require_pattern "$reviewed_lock_guard" '^LEGACY_REVIEWED_LOCK="\$\{ROOT_DIR\}/fixtures/kagemusha/cargo-lock\.reviewed\.v1"$' "../iroha reviewed Cargo lock v1 provenance path pin"
  require_pattern "$reviewed_lock_guard" '^RECEIPT_EXPECTED_BYTES=3912$' "../iroha reviewed Cargo lock v2 receipt byte pin"
  require_pattern "$reviewed_lock_guard" '^RECEIPT_EXPECTED_SHA256="a9fc5d64780ae00a381b7d1ca40e123c3ed024ccc48568551ce70c6c47e244e3"$' "../iroha reviewed Cargo lock v2 receipt digest pin"
  require_pattern "$reviewed_lock_guard" '^RECEIPT="\$\{ROOT_DIR\}/fixtures/kagemusha/cargo-lock\.reviewed\.v2\.receipt\.json"$' "../iroha reviewed Cargo lock v2 receipt path pin"
  require_pattern "$reviewed_lock_guard" '^INPUTS_EXPECTED_BYTES=3555$' "../iroha reviewed Cargo lock v2 input-inventory byte pin"
  require_pattern "$reviewed_lock_guard" '^INPUTS_EXPECTED_SHA256="2de438363be7a1166d5545b5fff50f2c2071cca6ad266b4bb171103c452d9421"$' "../iroha reviewed Cargo lock v2 input-inventory digest pin"
  require_pattern "$reviewed_lock_guard" '^INPUTS="\$\{ROOT_DIR\}/fixtures/kagemusha/cargo-lock\.reviewed\.v2\.inputs"$' "../iroha reviewed Cargo lock v2 input-inventory path pin"
  require_pattern "$reviewed_lock_guard" '^SEED_EXPECTED_BYTES=321889$' "../iroha reviewed Cargo lock v2 seed byte pin"
  require_pattern "$reviewed_lock_guard" '^SEED_EXPECTED_SHA256="4f59dc1fae8d5aee0dcc6d46531a5a009a041193771f75ee1444420a59532b9c"$' "../iroha reviewed Cargo lock v2 seed digest pin"
  require_pattern "$reviewed_lock_guard" '^SEED="\$\{ROOT_DIR\}/fixtures/kagemusha/cargo-lock\.reviewed\.v2\.seed"$' "../iroha reviewed Cargo lock v2 seed path pin"
  require_pattern_multiline "$reviewed_lock_guard" 'verify_reviewed_evidence\(\) \{[\s\S]*verify_lock "\$\{REVIEWED_LOCK\}"[\s\S]*verify_lock "\$\{LEGACY_REVIEWED_LOCK\}"[\s\S]*verify_receipt[\s\S]*verify_lock "\$\{INPUTS\}"[\s\S]*verify_lock "\$\{SEED\}"' "../iroha reviewed Cargo lock complete v2/v1/receipt/input/seed verification"
  require_pattern_multiline "$reviewed_lock_guard" 'verify_pair\(\) \{[\s\S]*verify_reviewed_evidence[\s\S]*verify_lock "\$\{WORKSPACE_LOCK\}"' "../iroha reviewed Cargo lock evidence-before-workspace verification order"
  require_exact_pattern_count "$reviewed_lock_guard" '^def load_secure_reader\(\) -> dict\[str, object\]:$' 3 "../iroha exact three reviewed-lock secure-reader authentication boundaries"
  require_exact_pattern_count "$reviewed_lock_guard" 'getattr\(os, "O_BINARY", 0\)' 3 "../iroha exact three Windows binary-mode secure-reader descriptor bindings"
  require_pattern_multiline "$reviewed_lock_guard" 'before_identity = \([\s\S]*before\.st_nlink[\s\S]*before\.st_mtime_ns[\s\S]*after_identity = \([\s\S]*after\.st_nlink[\s\S]*after\.st_mtime_ns[\s\S]*before_identity != after_identity' "../iroha reviewed Cargo lock secure-reader stable identity/time snapshot"
  require_pattern_multiline "$reviewed_lock_guard" 'hashlib\.sha256\(source\)\.hexdigest\(\) != helper_expected_sha256[\s\S]*exec\(compile\(source, str\(helper_path\), "exec"\), namespace\)[\s\S]*lacks stable_read' "../iroha reviewed Cargo lock authenticated stable-reader loading"
  require_pattern_multiline "$reviewed_lock_guard" 'hashlib\.sha256\(helper_source\)\.hexdigest\(\) != helper_expected_sha256[\s\S]*exec\(compile\(helper_source, str\(helper_path\), "exec"\), namespace\)[\s\S]*lacks atomic_materialize' "../iroha reviewed Cargo lock authenticated no-replace writer loading"
  require_pattern "$reviewed_lock_guard" 'workspace Kagemusha Cargo\.lock is not byte-identical to its reviewed artifact' "../iroha reviewed/workspace Cargo lock byte identity"
  require_pattern_multiline "$reviewed_lock_guard" 'secure_reader\["atomic_materialize"\]\([\s\S]*source,[\s\S]*destination,[\s\S]*expected_bytes,[\s\S]*expected_sha256,[\s\S]*destination_collision_for_test=collision_for_test' "../iroha reviewed Cargo lock authenticated no-replace materialization delegation"
  require_pattern_multiline "$reviewed_lock_guard" '--materialize\|--self-test-materialize\)[\s\S]*verify_reviewed_evidence[\s\S]*materialize_reviewed_lock[\s\S]*verify_pair' "../iroha reviewed Cargo lock evidence-materialize-reverify order"
  reject_pattern "$reviewed_lock_guard" '^[[:space:]]*if cmp -s -- "\$\{REVIEWED_LOCK\}" "\$\{WORKSPACE_LOCK\}"; then$' "../iroha forbidden MSYS text-mode Cargo lock classifier"
  require_pattern "$reviewed_lock_secure_reader" '^def stable_read\($' "../iroha reviewed Cargo lock descriptor-pinned stable-reader entrypoint"
  require_pattern "$reviewed_lock_secure_reader" '^def atomic_materialize\($' "../iroha reviewed Cargo lock descriptor-pinned no-replace writer entrypoint"
  require_pattern_multiline "$reviewed_lock_secure_reader" 'not stat\.S_ISREG\(metadata\.st_mode\)[\s\S]*metadata\.st_nlink != 1[\s\S]*metadata\.st_mode & 0o111' "../iroha reviewed Cargo lock regular singly-linked non-executable admission"
  require_pattern_multiline "$reviewed_lock_secure_reader" 'output_flags = \([\s\S]*os\.O_EXCL[\s\S]*os\.O_NOFOLLOW[\s\S]*getattr\(os, "O_NONBLOCK", 0\)[\s\S]*getattr\(os, "O_BINARY", 0\)' "../iroha reviewed Cargo lock exclusive no-follow publication descriptor"
  require_pattern_multiline "$reviewed_lock_secure_reader" 'os\.link\([\s\S]*temporary_name,[\s\S]*leaf_name,[\s\S]*src_dir_fd=parent_fd,[\s\S]*dst_dir_fd=parent_fd,[\s\S]*follow_symlinks=False' "../iroha reviewed Cargo lock descriptor-relative atomic no-replace publication"
  require_pattern "$reviewed_lock_secure_reader" 'rename\.replace_if_exists = 0' "../iroha reviewed Cargo lock Windows no-replace rename"
  require_pattern "$reviewed_lock_secure_reader" 'Kagemusha secure-reader and parent-pinned no-replace writer controls passed' "../iroha reviewed Cargo lock secure-reader/writer adversarial completion"
  require_pattern "$reviewed_lock_guard" 'v2/v1/receipt/root missing' "../iroha reviewed Cargo lock receipt/root absence negative inventory"
  require_pattern "$reviewed_lock_guard" 'resolution inventory/seed/source-closure drift' "../iroha reviewed Cargo lock input/seed/source negative inventory"
  require_pattern "$reviewed_lock_guard" 'atomic no-replace publish collision' "../iroha reviewed Cargo lock atomic no-replace adversarial inventory"

  require_pattern "$bridge_header_guard" '^SELF_TESTS=\(' "../iroha ABI-21 bridge self-test catalog"
  require_exact_pattern_count "$bridge_header_guard" '^  --self-test-[a-z0-9-]+$' 27 "../iroha exact ABI-21 bridge self-test inventory"
  require_pattern "$bridge_header_guard" 'for control in "\$\{SELF_TESTS\[@\]\}"' "../iroha aggregate ABI-21 bridge self-test runner"
  require_pattern "$policy" 'SWIFT_SOURCE = "IrohaSwift/Sources/IrohaSwift/KagemushaRecursiveSpendV2\.swift"' "../iroha policy current Swift Kagemusha contract dependency"
  require_pattern "$policy" 'SWIFT_TEST_SOURCE = "IrohaSwift/Tests/IrohaSwiftTests/ToriiClientTests\.swift"' "../iroha policy current Swift Torii test dependency"
  require_pattern "$workflow" 'IrohaSwift/Sources/IrohaSwift/KagemushaRecursiveSpendV2Native\.swift' "../iroha workflow Swift ABI-21 native path filter"
  require_pattern "$swift_v2_native" 'typealias KagemushaV2FreeFn = @convention\(c\) \(UnsafeMutablePointer<UInt8>\?\) -> Void' "../iroha Swift exact connect_norito_free ABI signature"
  require_exact_pattern_count "$swift_v2_tests" '^[[:space:]]*func test' 30 "../iroha exact Swift ABI-21/V4 focused test inventory"

  require_identical_files "$openapi_root" "$openapi_current" "../iroha root/current canonical OpenAPI JSON synchronization"
  require_pattern "$manifest_root" '"signature"[[:space:]]*:[[:space:]]*null' "../iroha root unsigned OpenAPI manifest truth"
  require_pattern "$manifest_current" '"signature"[[:space:]]*:[[:space:]]*null' "../iroha current unsigned OpenAPI manifest truth"
  require_pattern "$versions" '"label"[[:space:]]*:[[:space:]]*"current"' "../iroha current OpenAPI version index"
  require_pattern "$versions" '"signed"[[:space:]]*:[[:space:]]*false' "../iroha unsigned OpenAPI version-index truth"
  require_pattern "$openapi_check" '--allow-unsigned' "../iroha documented unsigned OpenAPI verification fallback"
}

