    "$native_verification_test" "$package_types_test" "$readme" "$recipes_readme"; do
    require_file "$required" "../iroha full-artifact IVM/release hardening artifact"
  done

  require_identical_files "$ivm_src" "$ivm_dist" "../iroha IVM-artifact source/dist parity"
  require_identical_files "$transaction_src" "$transaction_dist" "../iroha IVM transaction source/dist parity"
  require_identical_files "$torii_src" "$torii_dist" "../iroha bounded Torii source/dist parity"
  require_identical_files "$browser_src" "$browser_dist" "../iroha IVM browser aggregate source/dist parity"
  require_identical_files "$index_src" "$index_dist" "../iroha IVM root aggregate source/dist parity"
  require_identical_files "$crypto_src" "$crypto_dist" "../iroha portable/native crypto source/dist parity"
  require_identical_files "$native_src" "$native_dist" "../iroha native loader source/dist parity"

  require_pattern "$ivm_src" 'export const IVM_PROGRAM_HEADER_LENGTH = 49' "../iroha IVM fixed full-artifact program-header length"
  require_pattern "$ivm_src" 'export const IVM_ARTIFACT_MAX_BYTES = 4 \* 1024 \* 1024' "../iroha IVM 4 MiB full-artifact cap"
  require_pattern "$ivm_src" 'const arrayBufferByteLengthGetter = Object\.getOwnPropertyDescriptor' "../iroha captured ArrayBuffer byte-length getter"
  require_pattern "$ivm_src" 'const typedArrayBufferGetter = Object\.getOwnPropertyDescriptor' "../iroha captured typed-array buffer getter"
  require_pattern "$ivm_src" 'const typedArrayByteOffsetGetter = Object\.getOwnPropertyDescriptor' "../iroha captured typed-array byte-offset getter"
  require_pattern "$ivm_src" 'const typedArrayByteLengthGetter = Object\.getOwnPropertyDescriptor' "../iroha captured typed-array byte-length getter"
  require_pattern "$ivm_src" 'const dataViewBufferGetter = Object\.getOwnPropertyDescriptor' "../iroha captured DataView buffer getter"
  require_pattern "$ivm_src" 'const sharedArrayBufferByteLengthGetter =' "../iroha captured SharedArrayBuffer byte-length getter"
  require_pattern "$ivm_src" 'sharedArrayBufferByteLengthGetter\.call\(value\)' "../iroha intrinsic shared-buffer detection"
  require_pattern "$ivm_src" 'artifact must not be backed by SharedArrayBuffer' "../iroha IVM shared-memory rejection"
  require_pattern "$ivm_src" 'const byteLength = arrayBufferByteLengthGetter\.call\(value\)' "../iroha IVM ArrayBuffer intrinsic bound-before-copy gate"
  require_pattern "$ivm_src" 'assertArtifactByteLength\(view\.byteLength\)' "../iroha IVM view-window bound-before-copy gate"
  require_pattern "$ivm_src" 'function copyArrayBufferBytes\(buffer, byteOffset, byteLength\)' "../iroha IVM intrinsic snapshot helper"
  require_pattern "$ivm_src" 'Reflect\.apply\(typedArraySet, copy, \[source\]\)' "../iroha IVM captured intrinsic copy gate"
  reject_pattern "$ivm_src" 'value\.(buffer|byteOffset|byteLength)|copy\.set\(source\)' "../iroha shadowable IVM artifact accessor/copy"
  require_pattern "$ivm_src" 'bytes\[0\] !== 0x49' "../iroha IVM exact magic-byte gate"
  require_pattern_multiline "$ivm_src" 'const CONTRACT_CODE_HASH_DOMAIN = new TextEncoder\(\)\.encode\([\s\S]*"iroha:ivm:contract-artifact:v1\\0"[\s\S]*const codeHashInput = new Uint8ArrayIntrinsic\([\s\S]*CONTRACT_CODE_HASH_DOMAIN\.length \+ byteLength' "../iroha IVM domain-separated full-artifact hash input"
  require_pattern_multiline "$ivm_src" 'Reflect\.apply\(typedArraySet, codeHashInput, \[CONTRACT_CODE_HASH_DOMAIN\]\)[\s\S]*Reflect\.apply\(typedArraySet, codeHashInput, \[bytes, CONTRACT_CODE_HASH_DOMAIN\.length\]\)[\s\S]*const rawCodeHash = blake2b256\(codeHashInput\)' "../iroha IVM ledger full-artifact hash domain"
  require_pattern "$ivm_src" 'codeHash\[codeHash\.length - 1\] \|= 1' "../iroha IVM code-hash Iroha marker bit"
  require_pattern "$ivm_src" 'artifactSha256Hex: bytesToHex\(sha256\(bytes\)\)' "../iroha IVM full-artifact SHA-256 binding"

  require_pattern "$declarations" 'IVM_PROGRAM_HEADER_LENGTH: 49' "../iroha IVM standalone declaration header constant"
  require_pattern "$declarations" 'IVM_ARTIFACT_MAX_BYTES: 4194304' "../iroha IVM standalone declaration size constant"
  require_pattern "$declarations" 'interface IvmArtifactHashes' "../iroha IVM standalone hash-result declaration"
  reject_pattern "$declarations" 'reference types="node"|from "node:|from "buffer"|\bBuffer\b' "../iroha IVM standalone declaration ambient Node dependency"

  for aggregate in "$browser_src" "$index_src"; do
    require_pattern "$aggregate" 'computeIvmArtifactHashes' "../iroha aggregate IVM hash-helper export"
    require_pattern "$aggregate" 'IVM_ARTIFACT_MAX_BYTES' "../iroha aggregate IVM artifact-cap export"
    require_pattern "$aggregate" 'IVM_PROGRAM_HEADER_LENGTH' "../iroha aggregate IVM header-length export"
  done
  require_pattern_multiline "$package_json" '"\./ivm-artifact"[\s\S]{0,320}"browser"[[:space:]]*:[[:space:]]*"\./dist/ivmArtifact\.js"[\s\S]{0,220}"import"[[:space:]]*:[[:space:]]*"\./dist/ivmArtifact\.js"[\s\S]{0,220}"types"[[:space:]]*:[[:space:]]*"\./ivm-artifact\.d\.ts"' "../iroha packaged IVM browser/import/type export"
  require_pattern_multiline "$package_json" '"ivm-artifact"[[:space:]]*:[[:space:]]*\[[[:space:]]*"\./ivm-artifact\.d\.ts"' "../iroha packaged IVM typesVersions mapping"
  require_pattern "$package_json" '"ivm-artifact\.d\.ts"' "../iroha packaged IVM standalone declaration inclusion"

  require_min_pattern_count "$ivm_test" '^test\(' 4 "../iroha IVM artifact focused test floor"
  require_pattern "$ivm_test" 'distinguishes header and body substitution' "../iroha IVM header/body substitution regression"
  require_pattern "$ivm_test" 'bounds input before copying and rejects shared memory' "../iroha IVM pre-copy-cap/shared-memory regression"
  require_min_pattern_count "$ivm_package_test" '^test\(' 2 "../iroha packed IVM browser/type test floor"
  require_pattern "$ivm_package_test" 'packed entrypoints expose identical browser-safe IVM artifact identities' "../iroha packed IVM aggregate/subpath identity regression"
  require_pattern "$ivm_package_test" 'packed ivm-artifact subpath bundles and compiles without ambient Node types' "../iroha packed IVM browser/strict-DOM regression"
  require_pattern "$ivm_package_test" 'contents\.byteLength <= 12 \* 1024' "../iroha packed IVM 12 KiB cap assertion"
  require_pattern "$ivm_package_test" 'must not be backed by SharedArrayBuffer' "../iroha packed IVM shared-memory regression"
  require_min_pattern_count "$ivm_types_test" '^test\(' 1 "../iroha IVM proved strict-type test floor"

  require_pattern "$transaction_src" 'IVM_ARTIFACT_MAX_BASE64_LENGTH' "../iroha IVM base64 pre-decode cap"
  require_pattern "$transaction_src" 'hasExactStandardBase64Shape' "../iroha IVM canonical base64 gate"
  require_pattern "$transaction_src" 'expectedArtifactSha256Hex' "../iroha caller-trusted full-artifact hash input"
  require_pattern "$transaction_src" 'expected_artifact_sha256_hex' "../iroha caller-trusted snake-case full-artifact hash alias"
  require_pattern "$transaction_src" 'actualArtifactSha256Hex !== expectedArtifactSha256Hex' "../iroha fetched full-artifact hash comparison"
  require_pattern "$transaction_src" 'assertIvmProvedBytecodeBinding' "../iroha derived/proved exact bytecode binding"
  require_pattern "$transaction_src" 'assertIvmProofAttachmentBinding' "../iroha proof/backend/verifying-key attachment binding"
  require_pattern "$transaction_src" 'prover returned an IvmProved payload different from the authoritative derived payload' "../iroha proved/derived canonical payload equality"
  require_pattern "$transaction_test" 'submitIvmProvedContractCall rejects code and proof substitution before signing' "../iroha IVM substitution-before-signing regression"
  require_pattern "$transaction_test" 'rejects ambiguous code-byte response shapes before derive' "../iroha IVM authoritative-code DTO-shape regression"

  require_pattern "$torii_src" 'CONTRACT_CODE_BYTES_JSON_MAX_BYTES' "../iroha contract-code response byte cap"
  require_pattern_multiline "$torii_src" 'getContractCodeBytes[\s\S]{0,1300}_maybeBoundedJson\([\s\S]{0,260}CONTRACT_CODE_BYTES_JSON_MAX_BYTES' "../iroha contract-code bounded JSON routing"
  require_pattern "$torii_src" 'requires a byte-stream response body so its size can be bounded' "../iroha bounded-response fail-closed stream requirement"
  require_pattern "$torii_src" 'body stream must not use SharedArrayBuffer-backed chunks' "../iroha bounded-response shared-memory rejection"
  require_pattern_multiline "$torii_src" 'chunkByteLength = typedArrayByteLengthGetter\.call\(value\)[\s\S]{0,2200}byteLength > maxBytes[\s\S]{0,900}chunks\.push\(copyArrayBufferBytes\(buffer, byteOffset, chunkByteLength\)\)' "../iroha bounded-response immediate intrinsic chunk snapshot"
  require_pattern "$torii_src" 'new TextDecoder\("utf-8", \{ fatal: true \}\)' "../iroha bounded-response fatal UTF-8 gate"
  require_pattern "$torii_src" 'must contain exactly the code_b64 field' "../iroha exact contract-code response DTO gate"
  require_pattern "$torii_src" 'code_b64 must be an enumerable data property' "../iroha contract-code active-descriptor rejection"
  require_pattern_multiline "$torii_src" 'function normalizeContractCodeBytesResponse\([\s\S]{0,1600}normalizeIvmArtifactBase64String\([\s\S]{0,180}descriptor\.value,[\s\S]{0,180}"contractCodeBytes\.code_b64"' "../iroha contract-code descriptor-value normalization routing"
  require_pattern_multiline "$torii_src" 'function normalizeBoundedCanonicalBase64String\([\s\S]{0,500}typeof value !== "string"[\s\S]{0,300}\$\{name\} must be a base64 string' "../iroha contract-code non-string rejection"
  require_pattern "$torii_test" 'getContractCodeBytes rejects oversized declared bodies before reading' "../iroha declared response-size adversarial test"
  require_pattern "$torii_test" 'getContractCodeBytes bounds actual streamed bytes with absent or lying headers' "../iroha streamed response-size adversarial test"
  require_pattern "$torii_test" 'getContractCodeBytes rejects shared and snapshots reused stream chunks' "../iroha response chunk race/shared-memory test"
  require_pattern "$torii_test" 'getContractCodeBytes rejects oversized base64 before decoding' "../iroha base64 pre-decode cap test"
  require_pattern "$torii_test" 'getContractCodeBytes rejects non-string code_b64 JSON values' "../iroha contract-code non-string DTO test"
  require_pattern "$torii_test" 'getContractCodeBytes rejects ambiguous or active DTO shapes' "../iroha contract-code Proxy/accessor DTO test"

  require_pattern_multiline "$crypto_src" 'function resolveOptionalNativeBinding\(\)[\s\S]{0,700}error\?\.code === "ERR_IROHA_NATIVE_BINDING"[\s\S]{0,240}error\?\.nativeStatus === "missing_file"[\s\S]{0,180}return null;[\s\S]{0,500}throw error;' "../iroha optional native binding missing-file-only fallback"
  require_pattern_multiline "$crypto_src" 'export function generateKeyPair\([\s\S]{0,1400}const native = resolveOptionalNativeBinding\(\)[\s\S]{0,500}native\?\.ed25519Keypair[\s\S]{0,900}privateKeyFromSeed\(privateKey\)' "../iroha portable Ed25519 key-generation fallback"
  require_pattern_multiline "$crypto_src" 'export function publicKeyFromPrivate\([\s\S]{0,1200}const native = resolveOptionalNativeBinding\(\)[\s\S]{0,500}native\?\.ed25519PublicKeyFromPrivate[\s\S]{0,700}privateKeyFromSeed\(seed\)' "../iroha portable Ed25519 public-key fallback"
  require_pattern "$crypto_test" 'Ed25519 key generation and derivation remain available without the native host' "../iroha portable Ed25519 no-host regression"
  require_pattern "$crypto_test" 'missing native files use the portable Ed25519 path' "../iroha missing-native portable Ed25519 regression"
  require_pattern "$crypto_test" 'a present native file with a bad checksum never falls back' "../iroha invalid-native no-fallback regression"

  require_pattern_multiline "$native_src" 'function nativeBindingError\([\s\S]{0,500}code:[\s\S]{0,160}"ERR_IROHA_NATIVE_BINDING"[\s\S]{0,300}nativeStatus:[\s\S]{0,160}value: status[\s\S]{0,160}enumerable: true' "../iroha structured native binding error status"
  require_pattern_multiline "$native_src" 'function formatForceNativeVerificationError\([\s\S]{0,500}case "missing_file"[\s\S]{0,1200}case "hash_mismatch"[\s\S]{0,500}verification\.status' "../iroha native verification status preservation"
  require_pattern_multiline "$native_verification_test" 'getNativeBinding rejects checksum mismatches[\s\S]{0,1800}error\.code, "ERR_IROHA_NATIVE_BINDING"[\s\S]{0,300}error\.nativeStatus, "hash_mismatch"' "../iroha native checksum structured-error regression"
  require_pattern_multiline "$native_verification_test" 'getNativeBinding throws when binding is missing[\s\S]{0,1600}error\.code, "ERR_IROHA_NATIVE_BINDING"[\s\S]{0,300}error\.nativeStatus, "missing_file"' "../iroha missing-native structured-error regression"

  require_pattern "$recipes_production_test" 'source documentation uses canonical, curve-valid I105 account samples' "../iroha canonical curve-valid I105 documentation regression"
  require_pattern_multiline "$recipes_production_test" 'occurrences\.length >= 50[\s\S]{0,900}AccountAddress\.parseEncoded\(literal\)[\s\S]{0,500}parsed\.address\.toI105\(parsed\.chainDiscriminant\)' "../iroha canonical curve-valid I105 sample validation"
  require_pattern "$recipes_production_test" 'the source-checkout batching recipe runs offline end to end' "../iroha source-checkout batching recipe smoke"
  require_pattern_multiline "$recipes_production_test" 'recipes", "batching\.mjs"[\s\S]{0,900}Manual batch hash:[\s\S]{0,400}Register \+ mint \+ transfer hash:' "../iroha batching recipe deterministic output gate"
  require_pattern "$recipes_production_test" 'live recipes reject ambiguous security flags before I/O' "../iroha live recipe ambiguous-flag pre-I/O regression"
  require_pattern_multiline "$recipes_production_test" 'TORII_REQUIRE_PERMISSIONS: "yes"[\s\S]{0,500}TORII_REQUIRE_PERMISSIONS must be exactly 0 or 1[\s\S]{0,1800}TORII_ALLOW_INSECURE: "yes"[\s\S]{0,500}TORII_ALLOW_INSECURE must be exactly 0 or 1[\s\S]{0,500}ECONNREFUSED\|fetch failed' "../iroha live recipe strict security-flag pre-I/O gate"

  require_pattern "$package_types_test" 'every public export has a safe runtime target and an explicit declaration target' "../iroha all-export runtime/declaration target regression"
  require_pattern "$package_types_test" 'the registry package allowlists only clean-install portable recipes' "../iroha portable registry recipe allowlist regression"
  require_pattern "$package_types_test" 'published recipe documentation exactly matches the portable allowlist' "../iroha published recipe documentation allowlist regression"
  require_pattern "$package_types_test" 'package smoke rejects every non-portable or missing required recipe' "../iroha package-smoke recipe allowlist adversarial regression"
  require_pattern "$package_types_test" 'runtime namespace declarations expose exactly their module exports' "../iroha runtime namespace declaration parity regression"
  require_pattern "$package_types_test" 'strict NodeNext resolves the root and every public subpath from a packed layout' "../iroha packed all-export NodeNext type regression"
  require_pattern "$package_types_test" 'dedicated browser declarations compile without ambient Node types' "../iroha packed browser declaration regression"
  require_pattern_multiline "$package_types_test" 'const PORTABLE_RECIPES = \[[\s\S]{0,220}"recipes/iso_bridge_builder\.mjs"[\s\S]{0,160}"recipes/nexus_app_transfer\.mjs"' "../iroha exact portable recipe allowlist"
  require_pattern_multiline "$package_types_test" 'rootContract = /The registry artifact includes only[\s\S]{0,700}recipeContract = /The portable registry\\s\+tarball includes only[\s\S]{0,1200}rootRecipes\.sort\(\), \[\.\.\.PORTABLE_RECIPES\]\.sort\(\)[\s\S]{0,300}recipeRecipes\.sort\(\), \[\.\.\.PORTABLE_RECIPES\]\.sort\(\)' "../iroha README-derived portable recipe allowlist parity"
  require_pattern_multiline "$package_json" '"\./norito"[[:space:]]*:[[:space:]]*\{[\s\S]{0,160}"import"[[:space:]]*:[[:space:]]*"\./dist/norito\.js"[\s\S]{0,160}"types"[[:space:]]*:[[:space:]]*"\./index\.d\.ts"' "../iroha Norito runtime/declaration export"
  require_pattern "$package_json" '"recipes/iso_bridge_builder\.mjs"' "../iroha packaged portable ISO recipe"
  require_pattern "$package_json" '"recipes/nexus_app_transfer\.mjs"' "../iroha packaged portable Nexus recipe"
  reject_pattern "$package_json" '^[[:space:]]*"recipes"[[:space:]]*,?[[:space:]]*$' "../iroha broad source-only recipe packaging"
  require_pattern_multiline "$readme" 'registry artifact includes only two portable,[[:space:]]*offline examples: `recipes/iso_bridge_builder\.mjs` and[[:space:]]*`recipes/nexus_app_transfer\.mjs`[\s\S]{0,180}wider recipe catalog is kept in the[[:space:]]*source repository' "../iroha root README exact portable recipe allowlist"
  require_pattern_multiline "$recipes_readme" 'portable registry[[:space:]]*tarball includes only `iso_bridge_builder\.mjs` and `nexus_app_transfer\.mjs`;[[:space:]]*examples that require the Cargo workspace, verified native host, credentials,[[:space:]]*or a live Torii endpoint remain source-checkout tools' "../iroha recipes README exact portable recipe allowlist"

  require_pattern_multiline "$bundle_check" 'label:[[:space:]]*"ivmArtifact\.js \(browser\)"[^}]*entryPoint:[[:space:]]*join\(ROOT, "dist", "ivmArtifact\.js"\)[^}]*limitKb:[[:space:]]*12[^}]*forbidNodeInputs:[[:space:]]*true[^}]*forbidGlobalBuffer:[[:space:]]*true' "../iroha IVM 12 KiB browser-leaf bundle gate"
  require_pattern "$bundle_check" 'checkDistExport\(pkg, "\./ivm-artifact", "browser"\)' "../iroha IVM bundle export-target gate"
  require_min_pattern_count "$bundle_test" '^test\(' 9 "../iroha bundle-gate test floor including IVM"
  require_pattern "$bundle_test" 'bundle-size check gates the IVM artifact helper as a browser leaf' "../iroha IVM bundle-target regression"
  require_pattern "$bundle_test" 'IVM artifact browser leaf stays below 12 KiB without Node or Buffer shims' "../iroha IVM bundle runtime regression"

  require_pattern_multiline "$build_dist" 'REQUIRED_OUTPUTS = \[[\s\S]{0,260}"ivmArtifact\.js"' "../iroha build-dist required IVM output"
  require_pattern "$build_dist" 'recoverInterruptedPublication' "../iroha build-dist interrupted-publication recovery"
  require_pattern "$build_dist" 'directoryDigest' "../iroha build-dist full-tree digest gate"
  require_pattern "$build_dist" 'publishStagingTree' "../iroha build-dist atomic staging publication"
  require_pattern "$build_dist" 'after-backup' "../iroha build-dist post-backup rollback failpoint"
  require_pattern "$build_dist" 'after-publish' "../iroha build-dist post-publish rollback failpoint"
  require_pattern "$build_dist" 'symbolic link' "../iroha build-dist symlink rejection"
  require_min_pattern_count "$build_dist_test" '^test\(' 7 "../iroha build-dist concurrency/recovery test floor"
  require_pattern "$package_smoke" '"dist/ivmArtifact\.js"' "../iroha pack-install IVM runtime requirement"
  require_pattern "$package_smoke" '"ivm-artifact\.d\.ts"' "../iroha pack-install IVM declaration requirement"
  require_pattern "$package_smoke" 'package smoke requires exact src/dist parity' "../iroha pack-install exact source/dist digest gate"
  require_pattern "$package_smoke" '"pack", "--ignore-scripts"' "../iroha pack-install lifecycle-safe pack"
  require_pattern_multiline "$package_smoke" '"install",[\s\S]*"--ignore-scripts"' "../iroha pack-install lifecycle-disabled clean install"
  require_pattern "$package_smoke" '@iroha/iroha-js/ivm-artifact' "../iroha installed IVM subpath smoke import"
  require_pattern "$package_smoke" 'root and ivm-artifact subpath exports differ' "../iroha installed IVM root/subpath identity gate"
  require_pattern_multiline "$package_smoke" 'const ALLOWED_RECIPE_PATHS = new Set\(\[[\s\S]{0,260}"recipes/iso_bridge_builder\.mjs"[\s\S]{0,180}"recipes/nexus_app_transfer\.mjs"[\s\S]{0,180}"recipes/README\.md"' "../iroha package-smoke exact recipe allowlist"
  require_pattern "$package_smoke" 'package smoke found forbidden non-portable recipe' "../iroha package-smoke non-portable recipe rejection"
  require_pattern_multiline "$package_smoke" 'installedRecipe[\s\S]{0,900}nexus_app_transfer\.mjs[\s\S]{0,900}final status: Applied' "../iroha packed Nexus recipe deterministic execution"
  require_pattern_multiline "$package_smoke" 'installedIsoBuilderRecipe[\s\S]{0,900}iso_bridge_builder\.mjs[\s\S]{0,1500}<InstrId>package-smoke-instruction</InstrId>' "../iroha packed ISO recipe deterministic execution"
  require_pattern "$package_json" '"prepublishOnly"[[:space:]]*:[[:space:]]*"npm run check:changelog && npm run build:dist && npm run lint:test && npm run bundle:check && npm run test:pack-install && npm run release:provenance"' "../iroha exact release prepublish command order"
  require_pattern "$package_json" '"release:publish"[[:space:]]*:[[:space:]]*"npm publish --access public --provenance"' "../iroha provenance-enabled public publish command"
  reject_pattern "$package_json" '"prepare"[[:space:]]*:' "../iroha recursive prepare lifecycle hook"
  require_min_pattern_count "$release_test" '^test\(' 1 "../iroha release lifecycle test floor"
  require_pattern "$release_test" 'publish lifecycle builds dist before tests and verifies the immutable packed install' "../iroha release lifecycle exact-order regression"
  require_min_pattern_count "$release_tar_test" '^test\(' 2 "../iroha release tarball verification test floor"
}

