  require_pattern "$iroha_wallet_audit" 'Android staged Taira bridge metadata rejection guard' "root Iroha wallet coverage Android cross-network metadata guard"
  require_pattern "$iroha_wallet_audit" 'iOS wallet-smoke route rejection test' "root Iroha wallet coverage iOS exact-route metadata guard"
  require_pattern "$iroha_wallet_audit" 'web browser Iroha signing fail-closed smoke' "root Iroha wallet coverage browser fail-closed guard"
  require_pattern "$iroha_wallet_audit" 'transfer enablement with pinned old package still blocked without reviewed codec artifact' "root Iroha wallet reviewed-codec blocker guard"
  require_pattern "$iroha_wallet_audit" 'browser_transaction_codec_unpublished_source_only' "root Iroha wallet unpublished-source diagnostic guard"
  require_pattern "$iroha_wallet_test" 'missing web Nexus SDK transfer test' "root Iroha wallet coverage web adversarial fixture"
  require_pattern "$iroha_wallet_test" 'missing Android Nexus transfer test' "root Iroha wallet coverage Android adversarial fixture"
  require_pattern "$iroha_wallet_test" 'missing iOS Nexus transfer test' "root Iroha wallet coverage iOS adversarial fixture"
  require_pattern "$iroha_wallet_test" 'missing web operator-only wallet-smoke proof' "root Iroha wallet coverage web signed-metadata adversarial fixture"
  require_pattern "$iroha_wallet_test" 'missing Android Taira bridge metadata guard' "root Iroha wallet coverage Android cross-network metadata adversarial fixture"
  require_pattern "$iroha_wallet_test" 'missing iOS route rejection proof' "root Iroha wallet coverage iOS exact-route metadata adversarial fixture"
  require_pattern "$iroha_wallet_test" 'missing web reviewed-codec blocker test' "root Iroha wallet reviewed-codec blocker adversarial fixture"
  require_pattern "$iroha_wallet_test" 'stale web browser codec absence diagnostic' "root Iroha wallet stale-absence adversarial fixture"
  require_pattern "$iroha_wallet_audit" 'audit-iroha-production-send-readiness\.sh' "root Iroha wallet coverage production-send aggregate gate"
  require_pattern "$iroha_wallet_audit" 'test-iroha-production-send-readiness-audit\.sh' "root Iroha wallet coverage production-send aggregate self-test gate"
  require_pattern "$iroha_wallet_test" 'missing aggregate Iroha production-send audit' "root Iroha wallet production-send missing-gate adversarial fixture"
  require_pattern "$iroha_send_audit" 'run_platform "android"' "root Iroha production-send Android aggregate gate"
  require_pattern "$iroha_send_audit" 'run_platform "ios"' "root Iroha production-send iOS aggregate gate"
  require_pattern "$iroha_send_audit" 'run_platform "browser-extension"' "root Iroha production-send browser aggregate gate"
  require_pattern "$iroha_send_audit" 'adversarial self-test' "root Iroha production-send per-platform self-test gate"
  require_pattern "$iroha_send_audit" 'blocked-readiness audit' "root Iroha production-send per-platform blocker gate"
  require_pattern_multiline "$iroha_send_audit" 'run_gate\(\)[\s\S]*local repo="\$2"[\s\S]*cd "\$repo" \|\| exit 1[\s\S]*IROHA_SEND_AUDIT_ROOT="\$repo" bash "\$path"' "root Iroha production-send exact per-platform root handoff"
  require_pattern "$iroha_send_test" 'expected all six platform gates to run' "root Iroha production-send complete aggregation assertion"
  require_pattern_multiline "$iroha_send_test" 'aggregate did not bind exact platform root[\s\S]*aggregate did not enter exact platform working directory[\s\S]*IROHA_SEND_AUDIT_ROOT="\$TMP_DIR/forged-ambient-root" run_audit' "root Iroha production-send platform-root handoff fixture"
  require_pattern "$iroha_send_test" 'missing platform audit was not rejected' "root Iroha production-send missing-audit fixture"
  require_pattern "$iroha_send_test" 'non-executable platform self-test was not rejected' "root Iroha production-send non-executable fixture"
}

