  local solana_rpc_client="$android/common/src/main/java/jp/co/soramitsu/common/data/network/solana/SolanaRpcClient.kt"
  local solana_rpc_test="$android/common/src/test/java/jp/co/soramitsu/common/wallet/SolanaRpcClientTest.kt"
  local pool_reward_test="$android/feature-staking-impl/src/test/java/jp/co/soramitsu/staking/impl/presentation/staking/main/scenarios/PoolRewardCalculationTest.kt"
  local staking_network_test="$android/feature-staking-impl/src/test/java/jp/co/soramitsu/staking/impl/presentation/staking/main/StakingNetworkInfoStateMapperTest.kt"
  local non_pool_test="$android/feature-staking-impl/src/test/java/jp/co/soramitsu/staking/impl/presentation/staking/main/scenarios/NonPoolStakingStateTest.kt"
  local stake_info_test="$android/feature-staking-impl/src/test/java/jp/co/soramitsu/staking/impl/presentation/staking/main/compose/StakeInfoViewStateTest.kt"

  require_file "$giantsquid_source" "fearless-Android bounded Giantsquid history source"
  require_file "$giantsquid_request" "fearless-Android bounded Giantsquid GraphQL request"
  require_file "$giantsquid_source_test" "fearless-Android Giantsquid history adversarial tests"
  require_file "$giantsquid_request_test" "fearless-Android Giantsquid request adversarial tests"
  require_pattern_multiline "$giantsquid_source" 'pageSize !in 1\.\.MAX_PAGE_SIZE \|\| filters\.isEmpty\(\)[\s\S]*cursor\.toIntOrNull\(\)\?\.takeIf \{ it >= 0 \}[\s\S]*filters = filters' "fearless-Android Giantsquid bounded request/cursor gate"
  require_pattern_multiline "$giantsquid_source" 'slashes[\s\S]*bonds[\s\S]*sortedWith\(canonicalOperationOrder\)[\s\S]*distinctBy\(Operation::id\)' "fearless-Android Giantsquid slash/bond deterministic deduplication"
  require_pattern_multiline "$giantsquid_source" 'isLenient = false[\s\S]*GIANTSQUID_TIMESTAMP\.matchEntire[\s\S]*any \{ it !in '\''0'\''\.\.'\''9'\'' \}[\s\S]*MAX_AMOUNT_DIGITS = 256[\s\S]*GIANTSQUID_TIMESTAMP = Regex' "fearless-Android Giantsquid strict timestamp/amount parsing"
  require_pattern_multiline "$giantsquid_source" 'selectedPageSizes[\s\S]*any \{ it >= pageSize \}[\s\S]*offset <= Int\.MAX_VALUE - pageSize' "fearless-Android Giantsquid bounded pagination cursor"
  require_pattern_multiline "$giantsquid_request" 'accountAddress\.isNotBlank\(\)[\s\S]*accountAddress\.length <= MAX_ACCOUNT_ADDRESS_LENGTH[\s\S]*limit in 1\.\.MAX_PAGE_SIZE[\s\S]*offset >= 0[\s\S]*filters\.isNotEmpty\(\)' "fearless-Android Giantsquid GraphQL input bounds"
  require_pattern "$giantsquid_request" 'JsonPrimitive\(accountAddress\)\.toString\(\)' "fearless-Android Giantsquid GraphQL string escaping"
  require_pattern_multiline "$giantsquid_request" 'TransactionFilter\.TRANSFER in filters[\s\S]*TransactionFilter\.REWARD in filters[\s\S]*TransactionFilter\.EXTRINSIC in filters' "fearless-Android Giantsquid selected query roots"
  require_pattern "$giantsquid_source_test" 'includes slash bond and bond-and-nominate exactly once in deterministic order' "fearless-Android Giantsquid slash/bond inclusion regression"
  require_pattern "$giantsquid_source_test" 'deduplicates globally by id using newest canonical record independent of response order' "fearless-Android Giantsquid response-order adversarial regression"
  require_pattern "$giantsquid_source_test" 'honors filters and fails malformed amounts timestamps and nullable success closed' "fearless-Android Giantsquid malformed-value regression"
  require_pattern "$giantsquid_source_test" 'rejects empty requests and malformed cursors without network calls' "fearless-Android Giantsquid no-network invalid-input regression"
  require_pattern "$giantsquid_source_test" 'advances a bounded offset only when a selected root fills the page' "fearless-Android Giantsquid pagination regression"
  require_pattern "$giantsquid_request_test" 'escaped account literal' "fearless-Android Giantsquid GraphQL injection regression"
  require_pattern "$giantsquid_request_test" 'rejects empty or invalid query bounds and filters' "fearless-Android Giantsquid query-bound regression"
  reject_pattern "$android/config/todo-debt-baseline.tsv" 'StartStakingPoolViewModel\.kt.*hardcoded returns for demo|StakingPoolViewModel\.kt.*hardcoded returns for demo|GiantsquidHistorySource\.kt.*complete history parse|StakingViewModel\.kt.*todo it|StakingViewModel\.kt.*shouldn.t be nullable' "fearless-Android resolved wallet/staking TODO baseline debt"

  require_file "$start_pool" "fearless-Android start-pool reward mapping"
  require_file "$staking_fragment" "fearless-Android staking network-info UI binding"
  require_file "$staking_main" "fearless-Android staking scenario state mapping"
  require_file "$staking_pool" "fearless-Android pool reward mapping"
  require_file "$pool_reward_test" "fearless-Android pool reward adversarial tests"
