  local non_pool_file
  for non_pool_file in "$stake_info_state" "$stake_status" "$staking_info_item" "$parachain_staking" "$relay_staking" "$delegation_options" "$staking_layout" "$common_timer" "$common_timer_test" "$solana_rpc_client" "$solana_rpc_test" "$non_pool_test" "$stake_info_test"; do
    require_file "$non_pool_file" "fearless-Android non-pool staking and bounded timer contract"
  done
  reject_pattern "$start_pool" '51cdb4b3101904a9d234d126656d33cd17518249819b510a03d6c90d0a019611|4f77f65b21b1f396c1555850be6f21e2b1f36c26b94dbcbfec976901c9f08bf3|polkadotChainId|todo hardcoded returns' "fearless-Android start-pool demo chain alias"
  reject_pattern "$staking_pool" '51cdb4b3101904a9d234d126656d33cd17518249819b510a03d6c90d0a019611|4f77f65b21b1f396c1555850be6f21e2b1f36c26b94dbcbfec976901c9f08bf3|polkadotChainId|todo hardcoded returns' "fearless-Android pool demo chain alias"
  require_pattern_multiline "$start_pool" 'calculatePoolStakingReturns\([\s\S]*chain\.id' "fearless-Android start-pool selected-chain reward binding"
  require_pattern_multiline "$staking_pool" 'calculatePoolStakingReturns\(amount, PERIOD_MONTH, id\)[\s\S]*calculatePoolStakingReturns\(amount, PERIOD_YEAR, id\)' "fearless-Android pool selected-chain reward binding"
  require_pattern_multiline "$staking_main" 'mapStakingNetworkInfoState[\s\S]*StakingType\.POOL[\s\S]*StakingType\.RELAYCHAIN[\s\S]*StakingType\.PARACHAIN[\s\S]*combine\([[:space:]]*stakingSharedState\.selectionItem,[[:space:]]*networkInfo' "fearless-Android all-scenario network-state binding"
  require_pattern_multiline "$staking_main" 'Flow<StakingAssetInfoViewState>[\s\S]*networkInfoState: StakingAssetInfoViewState,' "fearless-Android non-null staking network-info state"
  require_pattern "$staking_fragment" 'StakingAssetInfo\(it\.networkInfoState\)' "fearless-Android direct non-null staking network-info rendering"
  reject_pattern "$staking_main" 'selection\.type != StakingType\.POOL\) return@map null|todo it' "fearless-Android pool-only network-info stub"
  require_pattern "$pool_reward_test" 'former demo ids are not aliased to Polkadot' "fearless-Android retired demo-alias regression"
  require_pattern "$pool_reward_test" 'calculator failures propagate without a fallback chain retry' "fearless-Android reward fallback negative regression"
  require_pattern "$pool_reward_test" 'cancellation propagates without a fallback chain retry' "fearless-Android reward cancellation regression"
  require_pattern "$pool_reward_test" 'pathological inputs are forwarded without trimming clamping or substitution' "fearless-Android pathological chain-ID pass-through regression"
  require_pattern "$pool_reward_test" 'production pool screens contain no demo chain remapping' "fearless-Android production-source closure regression"
  require_pattern "$staking_network_test" 'stale models cannot leak across any scenario boundary' "fearless-Android stale scenario-state regression"
  require_pattern "$staking_network_test" 'missing or mistyped defaults fail with a deterministic invariant error' "fearless-Android malformed scenario-default regression"
  require_pattern "$staking_network_test" 'staking body state accepts only the selected scenario family' "fearless-Android stale staking-body family regression"
  require_pattern_multiline "$staking_main" 'mapStakingBodyState[\s\S]*StakingType\.POOL -> state as\? StakingViewState\.Pool[\s\S]*StakingType\.RELAYCHAIN -> state as\? StakingViewState\.RelayChain[\s\S]*StakingType\.PARACHAIN -> state as\? StakingViewState\.Parachain' "fearless-Android selected-scenario staking body fence"
  require_pattern_multiline "$staking_main" 'selectionItem\.distinctUntilChanged\(\)\.onEach[\s\S]*availableManageStakeActions = emptySet\(\)' "fearless-Android selected-scenario manage-action reset"
  require_pattern_multiline "$staking_main" 'onManageStakeActionChosen[\s\S]*if \(action !in availableManageStakeActions\) return[\s\S]*availableManageStakeActions = emptySet\(\)' "fearless-Android one-shot manage-action allowlist fence"
  require_pattern_multiline "$staking_fragment" 'nonPoolStakingBody[\s\S]*NonPoolStakingBody[\s\S]*StakingViewState\.RelayChain\.Welcome[\s\S]*StakingViewState\.RelayChain\.Stake[\s\S]*StakingViewState\.Parachain\.Welcome[\s\S]*StakingViewState\.Parachain\.Delegator' "fearless-Android RelayChain/Parachain Compose body binding"
  require_pattern "$staking_layout" 'android:id="@\+id/nonPoolStakingBody"' "fearless-Android non-pool Compose view layout"
  reject_pattern "$relay_staking" 'return emptyFlow\(\)' "fearless-Android relay staking Compose stub"
  reject_pattern "$parachain_staking" 'return emptyFlow\(\)' "fearless-Android parachain staking Compose stub"
  require_pattern_multiline "$relay_staking" 'getStakingViewStateFlow[\s\S]*StakingState\.NonStash -> welcomeStateFlow\(\)[\s\S]*StakingState\.Stash\.Nominator[\s\S]*StakingState\.Stash\.Validator[\s\S]*StakingState\.Stash\.None[\s\S]*relayManageActions[\s\S]*syncStakingRewards' "fearless-Android complete relay welcome/stake/status/action mapping"
  require_pattern_multiline "$parachain_staking" 'getStakingViewStateFlow[\s\S]*StakingState\.Parachain\.None -> welcomeStateFlow\(\)[\s\S]*StakingState\.Parachain\.Delegator[\s\S]*reportCollatorDataIssues[\s\S]*attachCandidateInfoPreservingDelegations' "fearless-Android recoverable parachain welcome/delegator mapping"
  require_pattern_multiline "$parachain_staking" 'calculateRoundTimeLeftMillis[\s\S]*currentRound\.length\.signum\(\) <= 0[\s\S]*currentBlock\.signum\(\) < 0[\s\S]*coerceAtLeast\(BigInteger\.ZERO\)[\s\S]*coerceAtMost\(currentRound\.length\)[\s\S]*toBoundedStakingTimerMillis' "fearless-Android overflow-safe bounded parachain round timer"
  require_pattern_multiline "$parachain_staking" 'calculateLeavingTimeLeftMillis[\s\S]*leavingRound == null[\s\S]*leaveDelay < 0[\s\S]*BigInteger\.valueOf\(leavingRound\)[\s\S]*toBoundedStakingTimerMillis' "fearless-Android overflow-safe bounded parachain leaving timer"
  require_pattern_multiline "$parachain_staking" 'isReadyToUnlock -> StakeStatus\.ReadyToUnlockCollator[\s\S]*status == null -> StakeStatus\.UnavailableCollator[\s\S]*status == CandidateInfoStatus\.ACTIVE[\s\S]*status is CandidateInfoStatus\.LEAVING[\s\S]*CandidateInfoStatus\.EMPTY \|\| status == CandidateInfoStatus\.IDLE' "fearless-Android complete fail-closed collator status precedence"
  require_pattern_multiline "$stake_info_state" 'CollatorStakeInfoViewState[\s\S]*val collator: CandidateInfo\?' "fearless-Android recoverable missing-candidate view state"
  require_pattern_multiline "$delegation_options" 'onYourCollator: \(\(\) -> Unit\)\?[\s\S]*onStakingBalance\(\)[\s\S]*onYourCollator\?\.let' "fearless-Android missing-candidate recovery-only delegation actions"
  require_pattern_multiline "$stake_status" 'MAX_STAKING_TIMER_MILLIS = 315_360_000_000L[\s\S]*value\.coerceIn\(0L, MAX_STAKING_TIMER_MILLIS\)[\s\S]*UnavailableCollator[\s\S]*interface WithTimer' "fearless-Android nonnegative ten-year timer/status bounds"
  require_pattern_multiline "$staking_info_item" 'this is StakeStatus\.WithTimer -> StakeStatusTrailingContent\.Countdown[\s\S]*sanitizeStakingTimerMillis\(timeLeft\)[\s\S]*is StakeStatusTrailingContent\.Countdown -> Timer\([\s\S]*extraMessage = trailingContent\.extraMessage[\s\S]*hideZeroTimer = trailingContent\.hideZeroTimer' "fearless-Android countdown-first staking status rendering"
  require_pattern_multiline "$common_timer" 'rememberUpdatedState\(onFinish\)[\s\S]*DisposableEffect\([\s\S]*TimerCompletion[\s\S]*onFinish = completion::finish[\s\S]*onDispose\(newTimer::cancel\)[\s\S]*if \(finished\) return[\s\S]*onFinish\(\)' "fearless-Android exactly-once lifecycle-safe Compose timer completion"
  require_pattern "$common_timer_test" 'completion callback is delivered exactly once' "fearless-Android timer completion adversarial regression"
  require_pattern "$non_pool_test" 'relay manage actions preserve every legacy role and payout capability rule' "fearless-Android relay manage-action matrix regression"
  require_pattern "$non_pool_test" 'ready to unlock dominates every adversarial collator status' "fearless-Android ready-to-unlock precedence regression"
  require_pattern "$non_pool_test" 'collator statuses clamp adversarial timers and recover from absent timing data' "fearless-Android collator timer clamp regression"
  require_pattern "$non_pool_test" 'missing candidate info remains a visible non-clickable delegation state' "fearless-Android missing-candidate visibility regression"
  require_pattern "$non_pool_test" 'round timer uses big integer arithmetic and bounds huge durations' "fearless-Android round-timer overflow regression"
  require_pattern "$non_pool_test" 'leaving timer handles past huge and invalid round data without long overflow' "fearless-Android leaving-timer overflow regression"
  require_pattern "$stake_info_test" 'timer statuses always select countdown content before their extra message' "fearless-Android countdown rendering regression"
  require_pattern "$stake_info_test" 'countdown content clamps zero and negative values while non-timers keep message routing' "fearless-Android countdown negative-value regression"
  reject_pattern "$solana_rpc_client" 'intValueExact\(' "fearless-Android API-31-only Solana RPC integer conversion"
  require_pattern_multiline "$solana_rpc_client" 'val parsed = BigInteger\(text\)[\s\S]*parsed < INT_MIN \|\| parsed > INT_MAX[\s\S]*return parsed\.toInt\(\)[\s\S]*INT_MIN = BigInteger\.valueOf\(Int\.MIN_VALUE\.toLong\(\)\)[\s\S]*INT_MAX = BigInteger\.valueOf\(Int\.MAX_VALUE\.toLong\(\)\)' "fearless-Android min-SDK-safe bounded Solana RPC error code"
  require_pattern "$solana_rpc_test" 'accepts only signed int range rpc error codes' "fearless-Android Solana RPC integer-boundary regression"
  local connected_locale
  for connected_locale in in ja pt ru tr vi zh; do
    local connected_strings="$android/common/src/main/res/values-$connected_locale/strings.xml"
    require_file "$connected_strings" "fearless-Android $connected_locale connected-account localization"
    require_exact_pattern_count "$connected_strings" 'name="connected_accounts_bitcoin_title"' 1 "fearless-Android $connected_locale Bitcoin connected-account localization"
    require_exact_pattern_count "$connected_strings" 'name="connected_accounts_solana_title"' 1 "fearless-Android $connected_locale Solana connected-account localization"
    require_exact_pattern_count "$connected_strings" 'name="connected_accounts_iroha_title"' 1 "fearless-Android $connected_locale Iroha connected-account localization"
  done

  local analytics_factory="$ios/fearless/Modules/Staking/Analytics/Validators/ViewModel/AnalyticsValidatorsViewModelFactory.swift"
  local analytics_test="$ios/fearlessTests/Modules/AnalyticsValidators/AnalyticsValidatorsTests.swift"
  require_file "$analytics_factory" "fearless-iOS validator analytics reward allocation"
  require_file "$analytics_test" "fearless-iOS validator analytics adversarial tests"
  reject_pattern "$analytics_factory" 'TODO in next release' "fearless-iOS analytics placeholder title"
  require_pattern "$analytics_factory" 'stakingAnalyticsReceivedRewards' "fearless-iOS localized received-rewards title"
  local analytics_locale
  for analytics_locale in en id ja pt-PT pt ru tr vi zh-Hans; do
    require_file "$ios/fearless/$analytics_locale.lproj/Localizable.strings" "fearless-iOS $analytics_locale analytics localization"
    require_exact_pattern_count "$ios/fearless/$analytics_locale.lproj/Localizable.strings" '^"staking\.analytics\.received\.rewards"[[:space:]]*=' 1 "fearless-iOS $analytics_locale received-rewards localization"
  done
  require_pattern_multiline "$analytics_factory" 'createRewardAllocation[\s\S]*reward\.isReward[\s\S]*reward\.stashAddress == stashAddress[\s\S]*validatorAddressSet\.contains\(reward\.validatorAddress\)[\s\S]*seenEventIds\.insert\(eventId\)\.inserted' "fearless-iOS attributable unique reward allocation"
  require_pattern_multiline "$analytics_factory" 'finiteDouble[\s\S]*value\.isFinite[\s\S]*rewardShare[\s\S]*totalAmount > \.zero[\s\S]*min\(max\(value, 0\.0\), 1\.0\)' "fearless-iOS finite zero-safe reward percentages"
  require_pattern_multiline "$analytics_factory" 'validEraValidatorInfos = eraValidatorInfos\.filter[\s\S]*\$0\.era >= eraRange\.start && \$0\.era <= eraRange\.end' "fearless-iOS bounded analytics era attribution"
  require_pattern "$analytics_test" 'UsesOnlyUniqueAttributableRewardEvents' "fearless-iOS duplicate/foreign reward regression"
  require_pattern "$analytics_test" 'MissingAndMalformedValidatorAttributionFailsClosed' "fearless-iOS missing-validator attribution regression"
  require_pattern "$analytics_test" 'ExtremeRewardAmountFailsClosedWithoutNaNOrInfinity' "fearless-iOS extreme reward regression"
  require_pattern "$analytics_test" 'UnsupportedAssetPrecisionFailsClosed' "fearless-iOS precision-bound regression"
  require_pattern "$analytics_test" 'OutOfRangeEraDataIsExcludedFromActivityPercentages' "fearless-iOS out-of-range era regression"
  require_pattern "$analytics_test" 'MalformedTargetsAndEraRangeBoundariesDoNotCrashOrProduceInvalidValues' "fearless-iOS malformed target/range regression"
  require_pattern "$analytics_test" 'ReceivedRewardsTitleIsLocalized' "fearless-iOS reward-title localization regression"
  reject_pattern "$analytics_test" 'contains\("TODO"\)' "fearless-iOS analytics test TODO marker"
  reject_pattern "$ios/config/todo-debt-baseline.tsv" 'AnalyticsValidatorsViewModelFactory\.swift.*TODO in next release' "fearless-iOS resolved analytics TODO baseline debt"

  local reward_protocol="$ios/fearless/CoreLayer/OperationFactory/BlockExplorer/Rewards/RewardOperationFactory.swift"
  local subquery_reward_factory="$ios/fearless/CoreLayer/OperationFactory/BlockExplorer/Rewards/SubqueryRewardOperationFactory.swift"
  local subsquid_reward_factory="$ios/fearless/CoreLayer/OperationFactory/BlockExplorer/Rewards/SubsquidRewardOperationFactory.swift"
  local subquery_reward_item="$ios/fearless/Common/Network/BlockExplorer/Subquery/Data/SubqueryDelegatorHistoryItem.swift"
  local subquery_reward_response="$ios/fearless/Common/Network/BlockExplorer/Subquery/Data/SubqueryDelegatorHistoryData.swift"
  local subquery_reward_data="$ios/fearless/Common/Network/BlockExplorer/Subquery/Data/SubqueryRewardData.swift"
  local subsquid_reward_response="$ios/fearless/Common/Network/BlockExplorer/Subsquid/ParachainSubsquidRewardResponse.swift"
  local subquery_reward_source="$ios/fearless/Common/DataProvider/Sources/Rewards/SubqueryRewardsSource.swift"
  local weekly_reward_source="$ios/fearless/Common/DataProvider/Sources/Rewards/WeaklyAnalyticsRewardSource.swift"
  local reward_source_test="$ios/fearlessTests/Common/DataProvider/RewardDataSourceTests.swift"
  local ios_reward_file
  for ios_reward_file in "$reward_protocol" "$subquery_reward_factory" "$subsquid_reward_factory" "$subquery_reward_item" "$subquery_reward_response" "$subquery_reward_data" "$subsquid_reward_response" "$subquery_reward_source" "$weekly_reward_source" "$reward_source_test"; do
    require_file "$ios_reward_file" "fearless-iOS live validator reward attribution contract"
  done
  require_pattern_multiline "$reward_protocol" 'maximumAddressLength = 128[\s\S]*address\.unicodeScalars[\s\S]*case 48 \.\.\. 57, 65 \.\.\. 90, 97 \.\.\. 122[\s\S]*startTimestamp < 0 \|\| startTimestamp > maximumTimestamp[\s\S]*endTimestamp < 0 \|\| endTimestamp > maximumTimestamp[\s\S]*startTimestamp > endTimestamp' "fearless-iOS bounded injection-safe reward query inputs"
  require_pattern_multiline "$reward_protocol" 'maximumDecimalDigits = 78[\s\S]*value\.utf8[\s\S]*bytes\.count <= maximumDecimalDigits[\s\S]*bytes\.allSatisfy[\s\S]*bytes\.count == 1 \|\| bytes\.first != 48[\s\S]*BigUInt\(value, radix: 10\)' "fearless-iOS canonical bounded reward amount parsing"
  require_pattern_multiline "$reward_protocol" 'struct RewardHistoryAttribution[\s\S]*validatorAddress == validatorAddress\.trimmingCharacters[\s\S]*!validatorAddress\.isEmpty[\s\S]*EraIndex\(exactly: era\)[\s\S]*var attribution: RewardHistoryAttribution\? \{ get \}' "fearless-iOS strict live reward attribution model"
  require_pattern_multiline "$subquery_reward_factory" 'SubqueryDelegationAction\.reward\.rawValue[\s\S]*\n[[:blank:]]+delegatorId\n[[:blank:]]+collatorId\n[[:blank:]]+roundId' "fearless-iOS Subquery live reward query attribution fields"
  require_pattern_multiline "$subquery_reward_factory" 'createDelegatorRewardsOperation[\s\S]*RewardHistoryRequestValidator\.isValid[\s\S]*RewardHistoryRequestError\.invalidParameters[\s\S]*prepareDelegatorHistoryRequest' "fearless-iOS Subquery pre-network reward request validation"
  require_pattern_multiline "$subsquid_reward_factory" 'historyElements\([\s\S]*reward_isNull: false[\s\S]*blockHeight[\s\S]*reward \{[\s\S]*amount[\s\S]*era[\s\S]*stash[\s\S]*validator' "fearless-iOS Arrowsquid live history reward schema"
  require_pattern_multiline "$subsquid_reward_factory" 'createDelegatorRewardsOperation[\s\S]*maximumTimestamp: Int64\(Int32\.max\)[\s\S]*RewardHistoryRequestError\.invalidParameters[\s\S]*prepareDelegatorHistoryRequest' "fearless-iOS Arrowsquid GraphQL-Int request bounds"
  reject_pattern "$subsquid_reward_factory" '^[[:space:]]*rewards\(' "fearless-iOS retired Arrowsquid rewards root"
  require_pattern_multiline "$subquery_reward_item" 'case timestampInSeconds = "timestamp"[\s\S]*case delegatorId[\s\S]*case collatorId[\s\S]*case roundId[\s\S]*RewardHistoryAttribution[\s\S]*RewardAmountParser\.parse\(amountString\)' "fearless-iOS Subquery decoded live attribution and bounded amount"
  require_pattern_multiline "$subquery_reward_response" 'element\.id == address[\s\S]*item\.delegatorId == address' "fearless-iOS exact Subquery delegator response binding"
  require_pattern_multiline "$subsquid_reward_response" 'RewardAmountParser\.parse\(amountString\)[\s\S]*value >= 0 \? UInt64\(value\) : nil[\s\S]*RewardHistoryAttribution[\s\S]*item\.address == address && item\.reward\.stash == address' "fearless-iOS exact Arrowsquid stash attribution binding"
  require_pattern_multiline "$subquery_reward_data" 'rewardHistoryItem\.attribution[\s\S]*validatorAddress: attribution\?\.validatorAddress \?\? ""[\s\S]*era: attribution\?\.era \?\? 0' "fearless-iOS aggregate-compatible fail-closed attribution mapping"
  require_pattern_multiline "$subquery_reward_source" 'rewardHistory\(for: address\)\.compactMap[\s\S]*SubqueryRewardItemData[\s\S]*stashAddress: address' "fearless-iOS main analytics live attribution source"
  require_pattern_multiline "$weekly_reward_source" 'rewardHistory\(for: address\)\.compactMap[\s\S]*SubqueryRewardItemData[\s\S]*stashAddress: address' "fearless-iOS weekly analytics live attribution source"
  require_pattern "$reward_source_test" 'testSubqueryRequestAndResponseThreadCollatorAttributionEndToEnd' "fearless-iOS Subquery end-to-end attribution regression"
  require_pattern "$reward_source_test" 'testHostileAddressesAndInvalidTimestampBoundsAreRejectedBeforeNetworking' "fearless-iOS hostile reward query regression"
  require_pattern "$reward_source_test" 'testSubsquidResponseThreadsValidatorAttributionEndToEnd' "fearless-iOS Arrowsquid end-to-end attribution regression"
  require_pattern "$reward_source_test" 'testSubsquidMalformedAttributionAndForeignRowsFailClosed' "fearless-iOS foreign reward attribution regression"
  require_pattern "$reward_source_test" 'testNonCanonicalAndOversizedRewardAmountsAreRejectedBeforeBigUIntConstruction' "fearless-iOS reward amount resource-bound regression"
  require_pattern "$reward_source_test" 'testLegacyRewardItemsRemainBackwardCompatibleAndUnattributed' "fearless-iOS legacy aggregate compatibility regression"

  local tx_failure="$web/src/helpers/transactionFailure.ts"
  local google_progress="$web/src/helpers/googleWalletProgress.ts"
  local provider="$web/src/extension/background/extension-base/src/page/PostMessageProvider.ts"
  local confirmation="$web/src/screens/wallet&asset/ConfirmationPasswordPopup.vue"
  local flow_steps="$web/src/screens/addWallet/google/FlowStepLayout.vue"
  local en_locale="$web/src/locales/en/translation.json"
  local ru_locale="$web/src/locales/ru/translation.json"
  local tx_failure_test="$web/tests/unit/transaction-failure.spec.ts"
  local confirmation_test="$web/tests/unit/confirmation-password-popup.spec.ts"
  local google_progress_test="$web/tests/unit/google-wallet-progress.spec.ts"
  local google_layout_test="$web/tests/unit/google-wallet-flow-step-layout.spec.ts"
  local provider_test="$web/tests/unit/post-message-provider.spec.ts"
  local web_file
  for web_file in "$tx_failure" "$google_progress" "$provider" "$confirmation" "$flow_steps" "$en_locale" "$ru_locale" "$tx_failure_test" "$confirmation_test" "$google_progress_test" "$google_layout_test" "$provider_test"; do
    require_file "$web_file" "fearless-wallet-web fail-closed wallet edge-case contract"
  done
  require_pattern_multiline "$tx_failure" 'KNOWN_MESSAGE_KEYS = new Map<string, string>[\s\S]*SAFE_ASSET_SYMBOL = /\^\[A-Za-z0-9\]\[A-Za-z0-9\._-\]\{0,19\}\$/u[\s\S]*insufficientBalanceGeneric[\s\S]*common\.invalidPassword[\s\S]*KNOWN_MESSAGE_KEYS\.get\(error\.message\)[\s\S]*transactionFailedDetails' "fearless-wallet-web prototype-safe localized bounded transaction failure mapping"
  require_pattern_multiline "$tx_failure" 'Object\.getPrototypeOf\(value\)[\s\S]*prototype === Object\.prototype \|\| prototype === null[\s\S]*Object\.getOwnPropertyDescriptor\(value, key\)[\s\S]*hasOwnProperty\.call\(descriptor, '\''value'\''\)' "fearless-wallet-web own-data-property response boundary"
  require_pattern_multiline "$tx_failure" 'transactionResponseSucceeded[\s\S]*ownDataProperty\(response, '\''status'\''\)[\s\S]*status\.value === true[\s\S]*errors !== null[\s\S]*passwordError\.valid[\s\S]*!passwordError\.present' "fearless-wallet-web explicit own-field transaction success contract"
  require_pattern_multiline "$confirmation" 'try \{[\s\S]*await this\.makeExtrinsic\(\)[\s\S]*catch \{[\s\S]*applyTransactionResponse\(undefined\)' "fearless-wallet-web rejected transaction promise closure"
  require_pattern "$confirmation" 'getTransactionFailurePresentation' "fearless-wallet-web safe transaction error presentation"
  reject_pattern "$confirmation" 'console\.info\('\''errors:|TODO.*balanceTooLow|TODO.*ошиб' "fearless-wallet-web raw transaction-error logging/placeholder"
  require_pattern "$en_locale" '"transactionFailedDetails"' "fearless-wallet-web English generic transaction failure locale"
  require_pattern "$en_locale" '"insufficientBalanceGeneric"' "fearless-wallet-web English generic insufficient-balance locale"
  require_pattern "$ru_locale" '"transactionFailedDetails"' "fearless-wallet-web Russian generic transaction failure locale"
  require_pattern "$ru_locale" '"insufficientBalanceGeneric"' "fearless-wallet-web Russian generic insufficient-balance locale"
  require_pattern_multiline "$google_progress" 'MAX_GOOGLE_WALLET_FLOW_STEPS = 32;[\s\S]*Number\.isSafeInteger\(countSteps\)[\s\S]*Number\.isSafeInteger\(step\)[\s\S]*step === countSteps[\s\S]*isFinishStep: true' "fearless-wallet-web bounded terminal Google-wallet progress"
  require_pattern_multiline "$flow_steps" 'v-for="progressStep in progressState\.steps"[\s\S]*getGoogleWalletProgressState[\s\S]*this\.progressState\.isFinishStep' "fearless-wallet-web Google-wallet progress UI binding"
  reject_pattern "$flow_steps" 'TODO it maybe broken|v-for="num in countSteps"' "fearless-wallet-web retired Google-wallet progress stub"
  require_pattern "$provider" 'post_message_provider_manual_lifecycle_unsupported' "fearless-wallet-web explicit unsupported provider lifecycle error"
  require_pattern_multiline "$provider" 'connect\(\): Promise<void>[\s\S]*Promise\.reject\(manualLifecycleError\('\''connect'\''\)\)[\s\S]*disconnect\(\): Promise<void>[\s\S]*Promise\.reject\(manualLifecycleError\('\''disconnect'\''\)\)' "fearless-wallet-web deterministic provider lifecycle rejection"
  require_pattern_multiline "$provider" 'MAX_PROVIDER_KEY_LENGTH = 128[\s\S]*MAX_PROVIDER_META_FIELD_LENGTH = 256[\s\S]*(?:^|\n)const CONTROL_CHARACTERS = /\\p\{Cc\}/u[\s\S]*value\.trim\(\) === value[\s\S]*hasOwnProperty\.call\(meta, key\)' "fearless-wallet-web bounded own-field provider transport text"
  require_pattern_multiline "$provider" '#startGeneration[\s\S]*generation !== this\.#startGeneration[\s\S]*isProviderMeta[\s\S]*subscribed !== true[\s\S]*this\.#startGeneration \+= 1' "fearless-wallet-web provider generation/meta/subscription fencing"
  require_pattern "$tx_failure_test" 'fails safely for malformed and hostile error payloads' "fearless-wallet-web hostile transaction-error regression"
  require_pattern "$tx_failure_test" 'does not inherit a locale key for prototype message' "fearless-wallet-web prototype-key transaction-error regression"
  require_pattern "$tx_failure_test" 'rejects a response with inherited %s state' "fearless-wallet-web inherited response-state regression"
  require_pattern "$tx_failure_test" 'rejects an accessor-backed %s field without invoking it' "fearless-wallet-web accessor-free response-state regression"
  require_pattern "$tx_failure_test" 'accepts a null-prototype response only through its own data fields' "fearless-wallet-web null-prototype response regression"
  require_pattern "$tx_failure_test" 'does not inherit nested transaction error codes or messages' "fearless-wallet-web nested inherited-error regression"
  require_pattern "$confirmation_test" 'leaves pending state and shows a safe failure when the request promise rejects' "fearless-wallet-web rejected transaction-promise regression"
  require_pattern "$google_progress_test" 'fails closed without allocating progress' "fearless-wallet-web malformed progress regression"
  require_pattern "$google_layout_test" 'fails closed for an out-of-range step without allocating progress or claiming completion' "fearless-wallet-web malformed progress UI regression"
  require_pattern "$provider_test" 'fails unsupported manual connect and disconnect closed without logging or changing state' "fearless-wallet-web unsupported provider lifecycle regression"
  require_pattern "$provider_test" 'rejects malformed connection notifications and drops a previously connected state' "fearless-wallet-web malformed provider notification regression"
  require_pattern "$provider_test" 'deduplicates repeated starts and rejects attempts to switch a bound page channel' "fearless-wallet-web provider start race regression"
  require_pattern "$provider_test" 'fails malformed start responses closed and allows a clean retry' "fearless-wallet-web malformed provider start regression"
  require_pattern "$provider_test" 'rejects %s provider metadata before subscribing' "fearless-wallet-web hostile provider metadata regression"
  require_pattern "$provider_test" 'rejects empty, padded, control-bearing, oversized, and non-string provider keys before posting a request' "fearless-wallet-web hostile provider-key regression"
  reject_pattern "$web/config/todo-debt-baseline.tsv" 'PostMessageProvider\.ts.*provider can disconnect' "fearless-wallet-web resolved provider lifecycle TODO baseline debt"
}

main() {
  local android="${PLAN_AUDIT_ANDROID_ROOT:-$ROOT_DIR/fearless-Android-production-consolidated-20260731}"
  local ios="${PLAN_AUDIT_IOS_ROOT:-$ROOT_DIR/fearless-iOS-production-consolidated-20260731}"
  local ios_testflight="${PLAN_AUDIT_IOS_TESTFLIGHT_ROOT:-$ios}"
  local web="$ROOT_DIR/fearless-wallet-web"
  local site="$ROOT_DIR/fearless-site-web"
  local ton="$PARENT_DIR/ton-indexer"
  local solswap="$PARENT_DIR/solswap-indexer"
  local polkaswap="$PARENT_DIR/polkaswap-indexer"
  local iroha="${PLAN_AUDIT_IROHA_ROOT:-$PARENT_DIR/iroha}"

  require_repo "$android" "fearless-Android"
  require_repo "$ios" "fearless-iOS"
  require_repo "$ios_testflight" "fearless-iOS current TestFlight release candidate"
  require_repo "$web" "fearless-wallet-web"
  require_repo "$site" "fearless-site-web"
  require_repo "$ton" "../ton-indexer"
  require_repo "$solswap" "../solswap-indexer"
  require_repo "$polkaswap" "../polkaswap-indexer"
  require_repo "$iroha" "../iroha"

  log "Checking maintained repo release gates under $ROOT_DIR"
  mobile_checks "$android" "fearless-Android" "$android/.github/workflows/android-ci.yml"
  android_public_dependency_checks "$android"
  android_google_testing_distribution_checks "$android"
  android_xcm_contract_checks "$android"
  iroha_production_send_readiness_checks "$android" "fearless-Android" "android" "$android/.github/workflows/android-ci.yml"
  android_iroha_staged_bridge_checks "$android"
  mobile_checks "$ios" "fearless-iOS" "$ios/.github/workflows/codecov.yml"
  ios_dependency_contract_checks "$ios"
  ios_transaction_builder_checks "$ios"
  ios_testflight_publication_checks "$ios_testflight"
  ios_release_signing_gate_checks "$ios"
  iroha_production_send_readiness_checks "$ios" "fearless-iOS" "ios" "$ios/.github/workflows/codecov.yml"
  ios_iroha_readiness_v2_checks "$ios"
  native_passkey_implementation_checks "$android" "$ios"
  web_extension_checks "$web"
  web_firefox_release_checks "$web"
  wallet_edge_case_closure_checks "$android" "$ios" "$web"
  iroha_production_send_readiness_checks "$web" "fearless-wallet-web" "browser-extension" "$web/.github/workflows/ci.yml"
  web_iroha_source_only_codec_readiness_checks "$web"
  website_checks "$site"
  ios_website_association_parity_checks "$site" "$ios"
  indexer_checks "$ton" "../ton-indexer" "TON_INDEXER_BASE_URL" "https://ti.soramitsu.io"
  indexer_checks "$solswap" "../solswap-indexer" "SOLSWAP_INDEXER_BASE_URL" "https://si.soramitsu.io"
  polkaswap_indexer_checks "$polkaswap"
  iroha_sccp_v1_and_kagemusha_checks "$iroha"
  iroha_kagemusha_abi21_v4_policy_closure_checks "$iroha"
  iroha_browser_transaction_codec_checks "$iroha"
  iroha_ivm_artifact_release_checks "$iroha"
  root_release_readiness_checks

  if ((${#failures[@]} > 0)); then
    echo "[plan-readiness][error] Plan readiness audit failed:" >&2
    printf '  - %s\n' "${failures[@]}" >&2
    exit 1
  fi

  log "Plan readiness audit passed."
}

main "$@"
